          style={{ pointerEvents: "none" }}
        />
      )}

      {changeColor && (
        <rect
          x={x} y={y} width={width} height={headerHeight}
          fill={changeColor} fillOpacity="0.15" rx="8"
          style={{ pointerEvents: "none" }}
        />
      )}

      {hasChildren && (
        <g>
          <rect
            x={x + width - 25}
            y={y + 5}
