            rx="3"
            style={{ cursor: "pointer", pointerEvents: "all" }}
            onClick={handleToggleCollapse}
          />
          <text
            x={x + width - 15}
            y={y + 18}
            textAnchor="middle"
            className={classes.toggleText}
            fontSize="12"
            fontWeight="bold"
            style={{ cursor: "pointer", pointerEvents: "none" }}
          >
            {isCollapsed ? "+" : "−"}
          </text>
        </g>
      )}

      <text
        x={x + 10}
