          >
            <animateTransform
              attributeName="transform"
              type="rotate"
              values="0;360"
              dur="1s"
              repeatCount="indefinite"
              transformOrigin={`${x + width / 2} ${y + height / 2}`}
            />
          </circle>
          <text
            x={x + width / 2}
