/**
 * PDG visual styling — Tailwind className strings with light/dark support.
 *
 * Matches the dependency graph's monochrome emerald palette:
 *   light → emerald/white backgrounds, dark borders
 *   dark  → slate-800/900 backgrounds, emerald borders
 *
 * Every value is a Tailwind className string, not a hex color.
 */

import {
  EDGE_COLORS,
  EDGE_DIMMED,
  EDGE_HIGHLIGHTED,
  MARKER_COLORS,
} from "@ui/lib/graphTheme";
import { getNodeClasses } from "../viewNodes/nodeClasses";

export { EDGE_COLORS, EDGE_DIMMED, EDGE_HIGHLIGHTED, MARKER_COLORS };

// Derive scope container classes from the centralized node classes so PDG and
// dependency graph visuals stay consistent. This centralizes color decisions
// in one place (`nodeClasses.getNodeClasses`) making future adjustments easy.
const NODE_CLASSES = getNodeClasses();

// ── Scope containers (by nesting depth) ─────────────────
// For now we keep the same classes across depths, but this is a single place
// to add depth-based variants later if desired.
export const SCOPE_CLASSES: Record<
  number,
  { container: string; header: string; label: string }
> = {
  0: {
    container: NODE_CLASSES.container,
    header: NODE_CLASSES.header,
    label: NODE_CLASSES.titleText,
  },
  1: {
    container: NODE_CLASSES.container,
    header: NODE_CLASSES.header,
    label: NODE_CLASSES.titleText,
  },
  2: {
    container: NODE_CLASSES.container,
    header: NODE_CLASSES.header,
    label: NODE_CLASSES.titleText,
  },
  3: {
    container: NODE_CLASSES.container,
    header: NODE_CLASSES.header,
    label: NODE_CLASSES.titleText,
  },
};

export const SCOPE_SELECTED = {
  container: NODE_CLASSES.containerSelected,
  label: NODE_CLASSES.titleText,
};

// ── Leaf node shapes ────────────────────────────────────

interface LeafStyle {
  fill: string;
  stroke: string;
  text: string;
  selectedFill: string;
  selectedStroke: string;
}

export const LEAF_STYLES: Record<string, LeafStyle> = {
  condition: {
    fill: NODE_CLASSES.leaf,
    stroke: "",
    text: "",
    selectedFill: NODE_CLASSES.leafSelected,
    selectedStroke: "",
  },
  call: {
    fill: NODE_CLASSES.leaf,
    stroke: "",
    text: "",
    selectedFill: NODE_CLASSES.leafSelected,
    selectedStroke: "",
  },
  statement: {
    fill: NODE_CLASSES.leaf,
    stroke: "",
    text: "",
    selectedFill: NODE_CLASSES.leafSelected,
    selectedStroke: "",
  },
  variable: {
    fill: NODE_CLASSES.leaf,
    stroke: "",
    text: "",
    selectedFill: NODE_CLASSES.leafSelected,
    selectedStroke: "",
  },
  literal: {
    fill: NODE_CLASSES.leaf,
    stroke: "stroke-cyan-400 dark:stroke-cyan-500",
    text: "fill-cyan-200",
    selectedFill: NODE_CLASSES.leafSelected,
    selectedStroke: "",
  },
  merge: {
    fill: "fill-emerald-400 dark:fill-emerald-600",
    stroke: "",
    text: "",
    selectedFill: NODE_CLASSES.leafHighlighted,
    selectedStroke: "",
  },
};

// ── Highlight / dim state overrides ─────────────────────

export const HIGHLIGHT_OVERRIDES = {
  scope: {
    container: NODE_CLASSES.containerHighlighted,
    label: NODE_CLASSES.titleText,
  },
  leaf: {
    fill: NODE_CLASSES.containerHighlighted,
    stroke: NODE_CLASSES.containerHighlighted,
    text: NODE_CLASSES.titleText,
  },
};

export const DIM_OVERRIDES = {
  scope: {
    container: NODE_CLASSES.containerDimmed,
    label: NODE_CLASSES.titleText,
  },
  leaf: {
    fill: NODE_CLASSES.containerDimmed,
    stroke: NODE_CLASSES.containerDimmed,
    text: NODE_CLASSES.titleText,
  },
};

// ── Dimmed edge colors ──────────────────────────────────

// Edge theme values are now sourced from graphTheme.

interface LeafStyle {
  fill: string;
  stroke: string;
  text: string;
  selectedFill: string;
  selectedStroke: string;
}

/**
 * PdgScopeNode — scope container (module, function, class).
 *
 * Rounded-rect with a tinted header band and dashed border.
 * Supports: collapse toggle, hover, highlight/dim state, mode-aware colors.
 */

import { Node } from "@domains/graph/model/types";
import { getNodeClasses } from "../viewNodes/nodeClasses";
import {
  DIM_OVERRIDES,
  HIGHLIGHT_OVERRIDES,
  SCOPE_CLASSES,
  SCOPE_SELECTED,
} from "./pdgStyles";

interface Props {
  node: Node;
  onClick: (id: string) => void;
  onHover: (id: string | null) => void;
  onToggleCollapse: (id: string) => void;
  selected: boolean;
  hovered: boolean;
  hasSelection: boolean;
}

export default function PdgScopeNode({
  node,
  onClick,
  onHover,
  onToggleCollapse,
  selected,
  hovered,
  hasSelection,
}: Props) {
  const d = 0; // PDG nodes don't use depth the same way - use constant
  const cls = SCOPE_CLASSES[d] ?? SCOPE_CLASSES[3];
  const headerH = 28;

  const nodeClasses = getNodeClasses();
  // Hover class from shared node classes
  const hoverClass = nodeClasses.containerHover || "";

  // Determine visual state
  const isHighlighted = node.highlighted === "path";
  const isDimmed = hasSelection && !selected && !isHighlighted;

  let containerCls = cls.container;
  let labelCls = cls.label;

  if (selected) {
    containerCls = SCOPE_SELECTED.container;
    labelCls = SCOPE_SELECTED.label;
  } else if (isDimmed) {
    containerCls = DIM_OVERRIDES.scope.container;
    labelCls = DIM_OVERRIDES.scope.label;
  } else if (isHighlighted) {
    containerCls = HIGHLIGHT_OVERRIDES.scope.container;
    labelCls = HIGHLIGHT_OVERRIDES.scope.label;
  }

  const isCollapsed = node.collapsed ?? false;

  return (
    <g
      onClick={(e) => {
        e.stopPropagation();
        onClick(node.id);
      }}
      onMouseEnter={() => onHover(node.id)}
      onMouseLeave={() => onHover(null)}
      style={{ cursor: "pointer" }}
      opacity={isDimmed ? 0.4 : 1}
    >
      {/* Container */}
      <rect
        x={node.x}
        y={node.y}
        width={node.width}
        height={node.height}
        rx={8}
        ry={8}
        className={`${containerCls} ${hovered && !selected && !isHighlighted && !isDimmed ? hoverClass : ""}`}
        strokeWidth={selected || hovered ? 1.8 : 1.2}
        strokeDasharray={selected ? undefined : "6 3"}
        style={selected ? { filter: "url(#shadow)" } : undefined}
      />

      {/* Header band */}
      <rect
        x={node.x}
        y={node.y}
        width={node.width}
        height={headerH}
        rx={8}
        ry={8}
        className={cls.header}
      />
      {/* Square-off the bottom corners of the header */}
      <rect
        x={node.x}
        y={node.y + headerH - 8}
        width={node.width}
        height={8}
        className={cls.header}
      />

      {/* Collapse toggle */}
      <rect
        x={node.x + node.width - 25}
        y={node.y + 5}
        width={20}
        height={20}
        className={nodeClasses.toggleButton}
        strokeWidth={1}
        rx={3}
        onClick={(e) => {
          e.stopPropagation();
          onToggleCollapse(node.id);
        }}
        style={{ cursor: "pointer" }}
      />
      <text
        x={node.x + node.width - 15}
        y={node.y + 18}
        textAnchor="middle"
        className={nodeClasses.toggleText}
        fontSize={12}
        fontWeight="bold"
        style={{ pointerEvents: "none" }}
      >
        {isCollapsed ? "+" : "−"}
      </text>

      {/* Label */}
      <text
        x={node.x + 10}
        y={node.y + 18}
        fontSize={12}
        fontWeight={600}
        fontFamily="'Fira Code', monospace"
        className={labelCls}
      >
        {node.label}
      </text>
    </g>
  );
}

