      .zoom()
      .scaleExtent([zoomBounds.minZoom, zoomBounds.maxZoom])
      .on("zoom", (event) => {
        g.attr("transform", event.transform);
        setViewport({
          x: event.transform.x,
          y: event.transform.y,
          zoom: event.transform.k,
        });
      });

