      vw / (node.width + pad * 2),
      vh / (node.height + pad * 2),
      0.8,
    );
    const tx = vw / 2 - (node.x + node.width / 2) * fitZoom;
    const ty = vh / 2 - (node.y + node.height / 2) * fitZoom;
