};

export type PdgSlice = {
  pdgNodes: Node[];
  pdgFlatNodes: Node[];
  pdgEdges: CfgEdgeData[];
  pdgAllEdges: CfgEdgeData[];
  isPdgLayoutLoading: boolean;
  pdgVisibleEdgeTypes: Set<string>;
