export type GraphSlice = {
  nodes: Node[];
  visibleEdges: Edge[];
  allNodes: Node[];
  catalogNodes: Node[];
  allEdges: Edge[];
  apiNodes: Node[];
  apiEdges: Edge[];
  sessionPositions: Record<string, { x: number; y: number }>;
  layoutTransition: boolean;
  lastSelectorKey: string;
  graphWidth: number;
  graphHeight: number;
  graphBounds: { minX: number; minY: number; maxX: number; maxY: number } | null;
  padding: number;
  selectedNodeId: string | null;
  hoveredNodeId: string | null;
  renderMode: "svg";
  viewport: Viewport;
  zoomBounds: ZoomBounds;
  isLayoutLoading: boolean;
  loadingPhase: "layout" | null;
  loadingNodeCount: number;
  svgRef: React.RefObject<SVGSVGElement> | null;
  layoutSettings: LayoutSettings;

  initialize: (n: Node[], e?: Edge[]) => void;
  setVisibleEdges: () => void;
  updateParentBounds: (parent: string) => void;
  moveChildWithConstraints: (id: string, parent: string | null, x: number, y: number) => boolean;
  toggleNodeCollapse: (nodeId: string) => void;
  expandParentNodes: (nodeId: string) => void;
  findNodeById: (nodeId: string, nodes?: Node[]) => Node | null;
  applyHierarchicalDependencyLayout: (options?: { clearPositions?: boolean; silent?: boolean; pendingNodes?: Node[] }) => void;
  setLayoutLoading: (loading: boolean) => void;
  setGraphDimensions: (width: number, height: number) => void;
  selectNode: (nodeId: string | null) => void;
  setHoveredNode: (nodeId: string | null) => void;
  highlightDependencies: (nodeId: string, direction: "upstream" | "downstream" | "both") => void;
  highlightDependenciesCustom: (selectedNodeId: string, dependencies: Set<string>, dependents: Set<string>) => void;
  clearHighlights: () => void;
  setRenderMode: (mode: "svg") => void;
  setViewport: (viewport: Viewport) => void;
  setZoomBounds: (bounds: ZoomBounds) => void;
  setSvgRef: (ref: React.RefObject<SVGSVGElement> | null) => void;
  exportPng: () => Promise<void>;
  setLayoutSettings: (patch: Partial<LayoutSettings>) => void;
  flipLayoutDirection: () => void;
  wsSend: ((msg: object) => void) | null;
  setWsSend: (fn: (msg: object) => void) => void;
  dismissChange: (nodeId: string) => void;
  dismissAllChanges: () => void;
  sidebarExpansionSignal: { type: "expand" | "collapse"; nodeId: string | null } | null;
  setSidebarExpansionSignal: (signal: { type: "expand" | "collapse"; nodeId: string | null } | null) => void;
  expandAll: () => void;
  collapseAll: () => void;
  expandChildren: (nodeId: string) => void;
  collapseChildren: (nodeId: string) => void;
  resetLayout: () => void;
};

export type NodePersistState = {
  collapsed?: boolean;
  pinned?: boolean;
  pinnedX?: number;
  pinnedY?: number;
};

export type DisplaySettings = {
  includeThirdPartyPackages: boolean;
  includeStandardPackages: boolean;
  visibleEdgeDepth: number;
  selectorQuery?: string;
  selectorExclude?: string;
};

export type LayoutSettings = {
  rootDirection: "RIGHT" | "DOWN";
  // ELK spacing
  rootNodeBetweenLayers: number;
  rootNodeNode: number;
  childNodeBetweenLayers: number;
  childNodeNode: number;
  edgeNode: number;
  componentComponent: number;
  padding: number;
  // Bezier edge
  edgeCurvature: number;
  edgeStrokeWidth: number;
};

export const DEFAULT_LAYOUT_SETTINGS: LayoutSettings = {
  rootDirection: "RIGHT",
  rootNodeBetweenLayers: 150,
  rootNodeNode: 100,
  childNodeBetweenLayers: 50,
  childNodeNode: 50,
  edgeNode: 50,
  componentComponent: 20,
  padding: 50,
  edgeCurvature: 40,
  edgeStrokeWidth: 1.2,
};

export type PersistedLayoutData = {
  version: 1;
  settings: Partial<DisplaySettings>;
  nodes: Record<string, NodePersistState>;
  layoutSettings?: Partial<LayoutSettings>;
};

export type PersistedLayoutData = {
  version: 1;
  settings: Partial<DisplaySettings>;
  nodes: Record<string, NodePersistState>;
  layoutSettings?: Partial<LayoutSettings>;
};

export type NodePersistState = {
  collapsed?: boolean;
  pinned?: boolean;
  pinnedX?: number;
  pinnedY?: number;
};

export type LayoutSettings = {
  rootDirection: "RIGHT" | "DOWN";
  // ELK spacing
  rootNodeBetweenLayers: number;
  rootNodeNode: number;
  childNodeBetweenLayers: number;
  childNodeNode: number;
  edgeNode: number;
  componentComponent: number;
  padding: number;
  // Bezier edge
  edgeCurvature: number;
  edgeStrokeWidth: number;
};

export type DisplaySettings = {
  includeThirdPartyPackages: boolean;
  includeStandardPackages: boolean;
  visibleEdgeDepth: number;
  selectorQuery?: string;
  selectorExclude?: string;
};

import { Edge, Node } from '../model/types';

function findDependencies(nodeId: string, edges: Edge[]): Set<string> {
  const dependencies = new Set<string>();
  edges.forEach((edge) => {
    if (edge.source === nodeId) dependencies.add(edge.target);
  });
  return dependencies;
}

function findDependents(nodeId: string, edges: Edge[]): Set<string> {
  const dependents = new Set<string>();
  edges.forEach((edge) => {
    if (edge.target === nodeId) dependents.add(edge.source);
  });
  return dependents;
}

export class SelectionAndHighlighting {
  private nodeUtils: any;

  constructor(nodeUtils: any) {
    this.nodeUtils = nodeUtils;
  }

  selectNode(
    nodeId: string | null,
    currentSelectedNodeId: string | null,
    nodes: Node[],
    allEdges: Edge[]
  ): { selectedNodeId: string | null; highlightedNodes: Node[] } {
    if (nodeId === currentSelectedNodeId) {
      return { selectedNodeId: null, highlightedNodes: this.clearHighlights(nodes) };
    }

    if (nodeId) {
      const getAllChildIds = (node: Node): string[] => {
        const childIds = [node.id];
        if (node.children) node.children.forEach((child) => childIds.push(...getAllChildIds(child)));
        return childIds;
      };

      const selectedNode = this.nodeUtils.findNodeById(nodeId, nodes);
      if (selectedNode) {
        const allRelatedIds = getAllChildIds(selectedNode);
        const allDependencies = new Set<string>();
        const allDependents = new Set<string>();
        allRelatedIds.forEach((id) => {
          findDependencies(id, allEdges).forEach((depId: string) => allDependencies.add(depId));
          findDependents(id, allEdges).forEach((depId: string) => allDependents.add(depId));
        });
        return {
          selectedNodeId: nodeId,
          highlightedNodes: this.highlightDependenciesCustom(nodeId, allDependencies, allDependents, nodes),
        };
      } else {
        return {
          selectedNodeId: nodeId,
          highlightedNodes: this.highlightDependencies(nodeId, "both", nodes, allEdges),
        };
      }
    } else {
      return { selectedNodeId: null, highlightedNodes: this.clearHighlights(nodes) };
    }
  }

  highlightDependencies(
    nodeId: string,
    direction: "upstream" | "downstream" | "both",
    nodes: Node[],
    allEdges: Edge[]
  ): Node[] {
    const dependencies = findDependencies(nodeId, allEdges);
    const dependents = findDependents(nodeId, allEdges);

    const updateNodeHighlighting = (nodeList: Node[]): Node[] => {
      return nodeList.map((node) => {
        let highlighted: "upstream" | "downstream" | "path" | null = null;
        if (node.id === nodeId) highlighted = "path";
        else if ((direction === "both" || direction === "upstream") && dependencies.has(node.id)) highlighted = "upstream";
        if ((direction === "both" || direction === "downstream") && dependents.has(node.id)) highlighted = "downstream";
        const processedChildren = node.children ? updateNodeHighlighting(node.children) : undefined;
        if (!highlighted && processedChildren) {
          const hasHighlightedChild = processedChildren.some((child) => child.highlighted);
          if (hasHighlightedChild) {
            const hasUpstream = processedChildren.some((child) => child.highlighted === "upstream");
            const hasDownstream = processedChildren.some((child) => child.highlighted === "downstream");
            const hasPath = processedChildren.some((child) => child.highlighted === "path");
            if (hasPath) highlighted = "path";
