fn collect_use_items(
    ctx: &ParseContext,
    node: Node,
    prefix: &[String],
) -> Vec<(String, Vec<String>, std::collections::HashMap<String, String>)> {
    match node.kind() {
        "identifier" => {
            let name = ctx.get_text(node);
            if prefix.is_empty() {
                vec![(String::new(), vec![name], std::collections::HashMap::new())]
            } else {
                let module = prefix.join(".");
                vec![(module, vec![name], std::collections::HashMap::new())]
            }
        }
        "self" => {
            // `use foo::self` — importing the module itself under the current prefix
            if !prefix.is_empty() {
                let mut parts = prefix.to_vec();
                let name = parts.pop().unwrap_or_default();
                let module = parts.join(".");
                vec![(module, vec![name], std::collections::HashMap::new())]
            } else {
                vec![(ctx.current_module.clone(), vec![], std::collections::HashMap::new())]
            }
        }
        "crate" => {
            // `use crate;` — unusual, just import the crate root
            let module = prefix.join(".");
            vec![(module, vec![ctx.crate_root.clone()], std::collections::HashMap::new())]
        }
        "scoped_identifier" => {
            // `a::b::C` — last segment is name, rest is module
            let raw_segs = get_path_segments(ctx, node);
            let mut all = prefix.to_vec();
            all.extend(raw_segs);
            let normalized = normalize_path_segments(all, &ctx.crate_root, &ctx.current_module);
            if normalized.is_empty() {
                return vec![];
            }
            let mut parts = normalized;
            let name = parts.pop().unwrap_or_default();
            let module = parts.join(".");
            vec![(module, vec![name], std::collections::HashMap::new())]
        }
        "scoped_use_list" => {
            // `a::b::{C, D}` — extend prefix with the path, recurse into list
            let mut new_prefix = prefix.to_vec();
            if let Some(path_node) = node.child_by_field_name("path") {
                let path_segs = get_path_segments(ctx, path_node);
                new_prefix.extend(path_segs);
                new_prefix = normalize_path_segments(
                    new_prefix,
                    &ctx.crate_root,
                    &ctx.current_module,
                );
            }
            node.child_by_field_name("list")
                .map(|list| collect_use_items(ctx, list, &new_prefix))
                .unwrap_or_default()
        }
        "use_list" => {
            // `{C, D, e::F}` — process each item with current prefix
            let mut results = Vec::new();
            let mut cursor = node.walk();
            for child in node.children(&mut cursor) {
                match child.kind() {
                    "{" | "}" | "," | "line_comment" | "block_comment" => {}
                    _ => results.extend(collect_use_items(ctx, child, prefix)),
                }
            }
            results
        }
        "use_as_clause" => {
            // `a::B as C` — import original path, bind locally as alias C
            if let Some(path_node) = node.child_by_field_name("path") {
                let mut items = collect_use_items(ctx, path_node, prefix);
                if let Some(alias_node) = node.child_by_field_name("alias") {
                    let alias = ctx.get_text(alias_node);
                    for (_, names, aliases) in items.iter_mut() {
                        for name in names.iter() {
                            aliases.insert(name.clone(), alias.clone());
                        }
                    }
                }
                items
            } else {
                vec![]
            }
        }
        "use_wildcard" => {
            // `a::b::*` — the entire node text includes `::*` at the end
            let text = ctx.get_text(node);
            let base = text
                .trim_end_matches('*')
                .trim_end_matches(':')
                .trim_end_matches(':');
            let module = if base.is_empty() {
                prefix.join(".")
            } else {
                let mut segs = prefix.to_vec();
                segs.extend(base.split("::").map(|s| s.to_string()));
                let segs =
                    normalize_path_segments(segs, &ctx.crate_root, &ctx.current_module);
                segs.join(".")
            };
            vec![(module, vec!["*".to_string()], std::collections::HashMap::new())]
        }
        _ => vec![],
    }
}

fn collect_arguments(ctx: &ParseContext, node: Node) -> Vec<String> {
    let mut args = Vec::new();
    if let Some(args_node) = node.child_by_field_name("arguments") {
        let mut cursor = args_node.walk();
        for child in args_node.children(&mut cursor) {
            match child.kind() {
                "(" | ")" | "," | "attribute_item" => {}
                _ if child.is_named() => {
                    args.push(ctx.get_text(child));
                }
                _ => {}
            }
        }
    }
    args
}

fn build_qualname(ctx: &ParseContext, node: Node, name: &str) -> String {
    let mut parts: Vec<String> = Vec::new();
    if !name.is_empty() {
        parts.push(name.to_string());
    }

    let mut current = node.parent();
    while let Some(parent) = current {
        match parent.kind() {
            "function_item" | "struct_item" | "enum_item" | "trait_item" | "mod_item" => {
                if let Some(name_node) = parent.child_by_field_name("name") {
                    parts.insert(0, ctx.get_text(name_node));
                }
            }
            "impl_item" => {
                if let Some(type_node) = parent.child_by_field_name("type") {
                    parts.insert(0, strip_generics(&ctx.get_text(type_node)));
                }
            }
            _ => {}
        }
        current = parent.parent();
    }

    if !ctx.module_path.is_empty() {
        let mut full = ctx.module_path.clone();
        full.extend(parts);
        return full.join(".");
    }
    parts.join(".")
}

impl<'a> ParseContext<'a> {
    fn get_text(&self, node: Node) -> String {
        self.source[node.start_byte()..node.end_byte()].to_string()
    }
}

pub mod config;

use crate::events::{generate_node_id, Event, ScopeType};
use tree_sitter::{Node, Tree};

// ============================================================================
// Docstring extraction helpers
// ============================================================================

/// Extract the docstring from a function or class body node.
/// Looks for the first child of the body that is an `expression_statement`
/// containing a `string` literal.
fn extract_body_docstring(ctx: &ParseContext, node: Node) -> Option<String> {
    let body = node.child_by_field_name("body")?;
    let mut cursor = body.walk();
    for child in body.children(&mut cursor) {
        match child.kind() {
            "decorator" | "comment" => continue,
            "expression_statement" => {
                let mut c2 = child.walk();
                for inner in child.children(&mut c2) {
                    if inner.kind() == "string" {
                        let raw = get_node_text(ctx, inner);
                        return Some(clean_docstring(&raw));
                    }
                }
                return None;
            }
            _ => return None,
        }
    }
    None
}

/// Extract a module-level docstring from the root `module` node.
fn extract_module_docstring(ctx: &ParseContext, root: Node) -> Option<String> {
    let mut cursor = root.walk();
    for child in root.children(&mut cursor) {
        match child.kind() {
            "comment" => continue,
            "expression_statement" => {
                let mut c2 = child.walk();
                for inner in child.children(&mut c2) {
                    if inner.kind() == "string" {
                        let raw = get_node_text(ctx, inner);
                        return Some(clean_docstring(&raw));
                    }
                }
                return None;
            }
            _ => return None,
        }
    }
    None
}

/// Strip outer quotes from a Python string literal and dedent the content.
fn clean_docstring(raw: &str) -> String {
    let inner = if (raw.starts_with("\"\"\"") && raw.ends_with("\"\"\"") && raw.len() >= 6)
        || (raw.starts_with("'''") && raw.ends_with("'''") && raw.len() >= 6)
    {
        &raw[3..raw.len() - 3]
    } else if (raw.starts_with('"') && raw.ends_with('"') && raw.len() >= 2)
        || (raw.starts_with('\'') && raw.ends_with('\'') && raw.len() >= 2)
    {
        &raw[1..raw.len() - 1]
    } else {
        raw
    };
    dedent(inner.trim_matches('\n'))
}

/// Remove uniform leading whitespace from all non-empty lines (textwrap.dedent).
fn dedent(s: &str) -> String {
    let lines: Vec<&str> = s.split('\n').collect();
    let indent = lines
        .iter()
        .filter(|l| !l.trim().is_empty())
        .map(|l| l.len() - l.trim_start().len())
        .min()
        .unwrap_or(0);
    lines
        .iter()
        .map(|l| if l.len() >= indent { &l[indent..] } else { l.trim_start() })
        .collect::<Vec<_>>()
        .join("\n")
        .trim_end()
        .to_string()
}

pub fn parse(source: &str, tree: &Option<Tree>, file_path: &str) -> Vec<Event> {
    let mut events = Vec::new();

    // Emit source line events first so subscribers can capture the raw source
    for (i, line) in source.lines().enumerate() {
        events.push(Event::SourceLine {
            file: file_path.to_string(),
            line_number: i + 1,
            text: line.to_string(),
        });
    }

    if let Some(tree) = tree {
        let root = tree.root_node();
        let module_path = derive_module_path(file_path);
        let is_init = std::path::Path::new(file_path)
            .file_stem()
            .and_then(|s| s.to_str())
            .map(|s| s == "__init__")
            .unwrap_or(false);
        let context = ParseContext {
            source,
            file_path,
            module_path,
            is_init,
        };

        // Emit module-level EnterScope so the docstring and scope range are captured.
        let module_qualname = context.module_path.join(".");
        let module_name = context.module_path.last().cloned().unwrap_or_else(|| "module".to_string());
        let module_docstring = extract_module_docstring(&context, root);
        events.push(Event::enter_scope_with_docstring(
            ScopeType::Module,
            module_name.clone(),
            module_qualname.clone(),
            vec![],
            vec![],
            module_docstring,
            root,
            file_path,
        ));

        walk_node_python(&context, root, &mut events);

        events.push(Event::exit_scope(
            ScopeType::Module,
            module_name,
            module_qualname,
            root,
            file_path,
        ));
    }
    events
}

/// Derive a Python module path from a file path.
///
/// Walks up the directory tree collecting only directories that are actual
/// Python packages (i.e., contain an `__init__.py` file).
///
/// e.g., "/path/to/project/src/serpentine/adapters/serialize.py" -> ["serpentine", "adapters", "serialize"]
///   (src/ has no __init__.py, so it is not included)
/// e.g., "/path/to/test_package/app.py" -> ["test_package", "app"]
pub fn derive_module_path(file_path: &str) -> Vec<String> {
    use std::path::Path;

    let path = Path::new(file_path);

    // Get the file stem (without .py extension)
    let stem = path
        .file_stem()
        .and_then(|s| s.to_str())
        .unwrap_or("__main__");

    // For __init__.py files, the module is the package itself (the parent directory).
    let is_init = stem == "__init__";

    // Walk up the directory tree collecting package names.
    // Include a directory only if it contains __init__.py (i.e., it is an actual Python package).
    let mut parts = Vec::new();
    let mut current = path.parent();

    while let Some(dir) = current {
        if let Some(dir_name) = dir.file_name().and_then(|s| s.to_str()) {
            // Stop at hidden directories (like .venv, .git)
            if dir_name.starts_with('.') {
                break;
            }

            // Stop at empty names (filesystem root)
            if dir_name.is_empty() {
                break;
            }

            // Stop at site-packages/dist-packages (installed packages boundary)
            if matches!(dir_name, "site-packages" | "dist-packages") {
                break;
            }

            // Stop if this directory is not a Python package (no __init__.py)
            if !dir.join("__init__.py").exists() {
                break;
            }

            // This is a Python package directory, include it
            parts.push(dir_name.to_string());
        } else {
            break;
        }

        current = dir.parent();
    }

    // Reverse since we collected from leaf to root
    parts.reverse();

    // Add the file stem (module name) — but NOT for __init__.py files,
    // since the package identity is the directory itself.
    if !is_init {
        parts.push(stem.to_string());
    }

    parts
}

struct ParseContext<'a> {
    source: &'a str,
    file_path: &'a str,
    module_path: Vec<String>,
    is_init: bool,
}

fn walk_node_python(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    let kind = node.kind();

    // Track if this node creates a scope (we need to emit exit after children)
    let scope_info = match kind {
        "class_definition" => {
            if let Some(name_node) = node.child_by_field_name("name") {
                let name = get_node_text(ctx, name_node);
                let qualname = build_qualname(ctx, node, &name);
                Some((ScopeType::Class, name, qualname))
            } else {
                None
            }
        }
        "function_definition" => {
            if let Some(name_node) = node.child_by_field_name("name") {
                let name = get_node_text(ctx, name_node);
                let qualname = build_qualname(ctx, node, &name);
                Some((ScopeType::Function, name, qualname))
            } else {
                None
            }
        }
        "lambda" => {
            let pos = node.start_position();
            let name = format!("<lambda:{}>", pos.row + 1);
            let qualname = build_qualname(ctx, node, &name);
            Some((ScopeType::Lambda, name, qualname))
        }
        _ => None,
    };

    // Track whether this is an assignment node — Assignment event is emitted POST
    // (after children are walked) so that the RHS expression events (CallExpression,
    // UseName) fire before the assignment node is created in the PDG.
    let is_assignment = kind == "assignment";
    let is_annotated_assignment = kind == "annotated_assignment";

    // Call events are also emitted POST so that nested calls (arguments evaluated
    // before the outer call) fire in the correct execution order.
    // e.g. car.drive(math.sqrt(25)): math.sqrt fires first (argument), then car.drive.
    let is_call = kind == "call";

    // Track control block info for emitting end events
    let control_block_info = match kind {
        "if_statement" | "for_statement" | "while_statement" | "try_statement"
        | "with_statement" | "async_for_statement" | "async_with_statement" => Some(kind),
        _ => None,
    };

    // Emit events based on node type
    match kind {
        "import_statement" | "import_from_statement" => emit_import_events(ctx, node, events),
        "class_definition" => emit_class_events(ctx, node, events),
        "function_definition" => emit_function_events(ctx, node, events),
        "assignment" => emit_assignment_define_events(ctx, node, events),
        "annotated_assignment" => emit_annotated_assignment_define_events(ctx, node, events),
        "type_alias_statement" => emit_type_alias_events(ctx, node, events),
        "identifier" => emit_identifier_events(ctx, node, events),
        "attribute" => emit_attribute_events(ctx, node, events),
        "if_statement" | "for_statement" | "while_statement" | "try_statement"
        | "with_statement" => emit_control_block_events(ctx, node, events, kind),
        "else_clause" => emit_else_block_events(ctx, node, events),
        "elif_clause" => emit_elif_block_events(ctx, node, events),
        "return_statement" => emit_return_events(ctx, node, events),
        "break_statement" => emit_break_events(ctx, node, events),
        "continue_statement" => emit_continue_events(ctx, node, events),
        "raise_statement" => emit_raise_events(ctx, node, events),
        "string" | "integer" | "float" | "true" | "false" | "none" => {
            emit_literal_events(ctx, node, events, kind)
        }
        "decorator" => emit_decorator_events(ctx, node, events),
        "match_statement" => emit_match_events(ctx, node, events),
        "case_clause" => emit_case_clause_events(ctx, node, events),
        "named_expression" => emit_named_expression_events(ctx, node, events),
        "list_comprehension" | "dictionary_comprehension" | "set_comprehension"
        | "generator_expression" => emit_comprehension_events(ctx, node, events, kind),
        "lambda" => emit_lambda_events(ctx, node, events),
        "augmented_assignment" => emit_augmented_assignment_events(ctx, node, events),
        "global_statement" | "nonlocal_statement" => {
            emit_global_nonlocal_events(ctx, node, events, kind)
        }
        "assert_statement" => emit_assert_events(ctx, node, events),
        "delete_statement" => emit_delete_events(ctx, node, events),
        "yield" => emit_yield_events(ctx, node, events),
        "async_for_statement" => emit_control_block_events(ctx, node, events, "async_for"),
        "async_with_statement" => emit_control_block_events(ctx, node, events, "async_with"),
        "except_clause" => emit_except_clause_events(ctx, node, events),
        _ => {}
    }

    // Walk all children
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        walk_node_python(ctx, child, events);
    }

    // Emit Assignment event after children so the RHS call/use events fire first,
    // giving correct PDG ordering: build_car → car, not car → build_car.
    if is_assignment {
        emit_assignment_post_event(ctx, node, events);
    }
    if is_annotated_assignment {
        emit_annotated_assignment_post_event(ctx, node, events);
    }

    // Emit Call event after children so nested argument calls fire first
    // (execution order: inner calls before outer call).
    if is_call {
        emit_call_events(ctx, node, events);
    }

    // Emit end_control_block after walking children
    if let Some(block_kind) = control_block_info {
        let block_type = match block_kind {
            "if_statement" => "if",
            "for_statement" => "for",
            "while_statement" => "while",
            "try_statement" => "try",
            "with_statement" => "with",
            "async_for_statement" => "async_for",
            "async_with_statement" => "async_with",
            _ => block_kind,
        };
        events.push(Event::end_control_block(block_type, node, ctx.file_path));
    }

    // Emit exit_scope after walking children
    if let Some((scope_type, name, qualname)) = scope_info {
        events.push(Event::exit_scope(
            scope_type,
            name,
            qualname,
            node,
            ctx.file_path,
        ));
    }
}

// ============================================================================
// Event Emitters - Each Python node type emits appropriate events
// ============================================================================

/// Emit events for import statements
///
/// Python import grammar (from grammar.txt):
/// ```
/// import_stmt: import_name | import_from
/// import_name: 'import' dotted_as_names
/// import_from: 'from' ('.' | '...')* dotted_name 'import' import_from_targets
///            | 'from' ('.' | '...')+ 'import' import_from_targets
/// import_from_targets: '(' import_from_as_names ','? ')' | import_from_as_names | '*'
/// import_from_as_names: import_from_as_name (',' import_from_as_name)*
/// import_from_as_name: NAME ['as' NAME]
/// dotted_as_names: dotted_as_name (',' dotted_as_name)*
/// dotted_as_name: dotted_name ['as' NAME]
/// dotted_name: NAME ('.' NAME)*
/// ```
///
/// Key insight: Imports create bindings (references) to external definitions,
/// NOT new local definitions. We emit ImportStatement events that the graph
/// builder uses to create edges between modules.
fn emit_import_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    let kind = node.kind();

    if kind == "import_statement" {
        // Handle: import x, import x.y, import x as y, import x, y, z
        emit_import_name_events(ctx, node, events);
    } else if kind == "import_from_statement" {
        // Handle: from x import y, from x import *, from . import y, etc.
        emit_import_from_events(ctx, node, events);
    }
}

/// Handle `import x`, `import x.y.z`, `import x as y`, `import a, b, c`
fn emit_import_name_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    let mut cursor = node.walk();
    let is_tc = is_in_type_checking_block(ctx, node);

    for child in node.children(&mut cursor) {
        match child.kind() {
            "dotted_name" => {
                // Simple import: `import x` or `import x.y.z`
                let module = get_node_text(ctx, child);
                events.push(Event::import_statement(module, vec![], std::collections::HashMap::new(), is_tc, node, ctx.file_path));
            }
            "aliased_import" => {
                // Aliased import: `import x as y`
                if let Some(dotted) = child.child_by_field_name("name") {
                    let module = get_node_text(ctx, dotted);
                    let mut aliases = std::collections::HashMap::new();
                    if let Some(alias_node) = child.child_by_field_name("alias") {
                        let alias = get_node_text(ctx, alias_node);
                        aliases.insert(module.clone(), alias);
                    }
                    events.push(Event::import_statement(module, vec![], aliases, is_tc, node, ctx.file_path));
                }
            }
            _ => {}
        }
    }
}

/// Handle `from x import y`, `from x import *`, `from . import y`, etc.
fn emit_import_from_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    // Extract the module being imported from
    let mut module_name = String::new();
    let mut relative_level = 0;
    let mut cursor = node.walk();

    // First pass: collect module name and relative level
    for child in node.children(&mut cursor) {
        match child.kind() {
            "dotted_name" => {
                // This could be the module name or an imported name
                // The module name comes before "import" keyword
                let text = get_node_text(ctx, child);
                if module_name.is_empty() && !has_passed_import_keyword(ctx, node, child) {
                    module_name = text;
                }
            }
            "relative_import" => {
                // Handle relative imports: from . import x, from .. import x
                let text = get_node_text(ctx, child);
                relative_level = text.chars().filter(|c| *c == '.').count();
                // The tree-sitter Python grammar has no named field for the dotted_name
                // inside relative_import — iterate children to find it.
                let mut ri_cursor = child.walk();
                for ri_child in child.children(&mut ri_cursor) {
                    if ri_child.kind() == "dotted_name" {
                        module_name = get_node_text(ctx, ri_child);
                        break;
                    }
                }
            }
            "import_prefix" => {
                // Dots for relative import level
                let text = get_node_text(ctx, child);
                relative_level = text.chars().filter(|c| *c == '.').count();
            }
            _ => {}
        }
    }

    // Build the full source module path
    let source_module = if relative_level > 0 {
        // Relative import - resolve against current module
        resolve_relative_import(ctx, relative_level, &module_name)
    } else {
        module_name.clone()
    };

    // Second pass: collect imported names and aliases
    let mut imported_names = Vec::new();
    let mut aliases = std::collections::HashMap::new();
    let mut cursor2 = node.walk();

    for child in node.children(&mut cursor2) {
        match child.kind() {
            "wildcard_import" => {
                // from x import *
                imported_names.push("*".to_string());
            }
            "dotted_name" | "identifier" => {
                // Check if this is an imported name (appears after "import" keyword)
                if has_passed_import_keyword(ctx, node, child) {
                    let name = get_node_text(ctx, child);
                    imported_names.push(name);
                }
            }
            "aliased_import" => {
                // from x import y as z - extract original name and alias
                if let Some(name_node) = child.child_by_field_name("name") {
                    let original = get_node_text(ctx, name_node);
                    imported_names.push(original.clone());
                    if let Some(alias_node) = child.child_by_field_name("alias") {
                        let alias = get_node_text(ctx, alias_node);
                        aliases.insert(original, alias);
                    }
                }
            }
            _ => {}
        }
    }

    let is_tc = is_in_type_checking_block(ctx, node);
    events.push(Event::import_statement(
        source_module,
        imported_names,
        aliases,
        is_tc,
        node,
        ctx.file_path,
    ));
}

/// Check if a node appears after the "import" keyword in the parent statement
fn has_passed_import_keyword(ctx: &ParseContext, parent: Node, node: Node) -> bool {
    let mut cursor = parent.walk();
    let mut found_import = false;

    for child in parent.children(&mut cursor) {
        if child.kind() == "import" {
            found_import = true;
            continue;
        }
        if found_import && child.id() == node.id() {
            return true;
        }
        // Also check inside lists like (a, b, c)
        if found_import
            && (child.kind() == "import_from_as_names"
                || child.kind() == "identifier"
                || child.kind() == "dotted_name"
                || child.kind() == "aliased_import")
        {
            // Check if our node is this child or a descendant
            if child.id() == node.id() || is_ancestor(child, node) {
                return true;
            }
        }
    }

    // Fallback: check byte positions
    // Find the "import" keyword position
    let parent_text = get_node_text(ctx, parent);
    if let Some(import_pos) = parent_text.find("import") {
        let import_end = parent.start_byte() + import_pos + 6;
        return node.start_byte() > import_end;
    }

    false
}

/// Check if potential_ancestor is an ancestor of node
fn is_ancestor(potential_ancestor: Node, node: Node) -> bool {
    let mut current = node.parent();
    while let Some(parent) = current {
        if parent.id() == potential_ancestor.id() {
            return true;
        }
        current = parent.parent();
    }
    false
}

/// Resolve a relative import to an absolute module path
fn resolve_relative_import(ctx: &ParseContext, level: usize, module_name: &str) -> String {
    // level 1 = from . import (current package)
    // level 2 = from .. import (parent package)
    // etc.

    let current_parts = &ctx.module_path;

    // For __init__.py, module_path is already the package (e.g. ["requests"]).
    // level=1 means "this package", so we should not subtract anything.
    // For regular modules, module_path includes the file stem (e.g. ["requests","sessions"]),
    // and level=1 means "go up to the package", so we subtract 1.
    let effective_level = if ctx.is_init && level > 0 { level - 1 } else { level };

    if current_parts.is_empty() || effective_level > current_parts.len() {
        // Can't resolve, return as-is with dots preserved for debugging
        let dots = ".".repeat(level);
        if module_name.is_empty() {
            return dots;
        }
        return format!("{}{}", dots, module_name);
    }

    // Go up 'effective_level' directories
    let base_len = current_parts.len().saturating_sub(effective_level);
    let base_parts: Vec<&str> = current_parts
        .iter()
        .take(base_len)
        .map(|s| s.as_str())
        .collect();

    if module_name.is_empty() {
        // from . import x - the module is the parent package itself
        base_parts.join(".")
    } else {
        // from .foo import x - combine base with the submodule
        if base_parts.is_empty() {
            module_name.to_string()
        } else {
            format!("{}.{}", base_parts.join("."), module_name)
        }
    }
}

/// Emit events for class definitions
fn emit_class_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    if let Some(name_node) = node.child_by_field_name("name") {
        let name = get_node_text(ctx, name_node);
        let qualname = build_qualname(ctx, node, &name);

        // Extract base class names from the superclasses argument list
        let mut bases = Vec::new();
        if let Some(superclasses_node) = node.child_by_field_name("superclasses") {
            let mut cursor = superclasses_node.walk();
            for base_child in superclasses_node.children(&mut cursor) {
                match base_child.kind() {
                    "identifier" => {
                        bases.push(get_node_text(ctx, base_child));
                    }
                    "attribute" => {
                        bases.push(get_node_text(ctx, base_child));
                    }
                    _ => {} // Skip commas, parens, keyword_argument
                }
            }
        }

        let docstring = extract_body_docstring(ctx, node);
        events.push(Event::define_name(
            name.clone(),
            qualname.clone(),
            "class",
            node,
            ctx.file_path,
        ));
        events.push(Event::enter_scope_with_docstring(
            ScopeType::Class,
            name.clone(),
            qualname.clone(),
            Vec::new(),
            bases,
            docstring,
            node,
            ctx.file_path,
        ));
        // exit_scope is emitted by walk_node_python after processing children
    }
}

/// Emit events for function definitions
fn emit_function_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    if let Some(name_node) = node.child_by_field_name("name") {
        let name = get_node_text(ctx, name_node);
        let qualname = build_qualname(ctx, node, &name);

        // Extract parameter names from the function's parameters node
        let mut parameters = Vec::new();
        if let Some(params_node) = node.child_by_field_name("parameters") {
            let mut cursor = params_node.walk();
            for child in params_node.children(&mut cursor) {
                match child.kind() {
                    "identifier" => {
                        let param_name = get_node_text(ctx, child);
                        if param_name != "self" && param_name != "cls" {
                            parameters.push(param_name);
                        }
                    }
                    "default_parameter" | "typed_parameter" | "typed_default_parameter" => {
                        // These have a "name" field child that is the parameter name
                        if let Some(param_name_node) = child.child_by_field_name("name") {
                            let param_name = get_node_text(ctx, param_name_node);
                            if param_name != "self" && param_name != "cls" {
                                parameters.push(param_name);
                            }
                        }
                    }
                    "list_splat_pattern" | "list_splat" => {
                        // *args
                        let mut cursor2 = child.walk();
                        for inner in child.children(&mut cursor2) {
                            if inner.kind() == "identifier" {
                                let param_name = get_node_text(ctx, inner);
                                if param_name != "self" && param_name != "cls" {
                                    parameters.push(format!("*{}", param_name));
                                }
                            }
                        }
                    }
                    "dictionary_splat_pattern" | "dictionary_splat" => {
                        // **kwargs
                        let mut cursor2 = child.walk();
                        for inner in child.children(&mut cursor2) {
                            if inner.kind() == "identifier" {
                                let param_name = get_node_text(ctx, inner);
                                if param_name != "self" && param_name != "cls" {
                                    parameters.push(format!("**{}", param_name));
                                }
                            }
                        }
                    }
                    _ => {} // Skip commas, parentheses, etc.
                }
            }
        }

        // Feature 7: Emit UseName for type annotations in parameters and return type.
        // These act as secondary type-reference edges (e.g., def f(x: Config) → uses Config).
        if let Some(params_node) = node.child_by_field_name("parameters") {
            let mut cursor = params_node.walk();
            for child in params_node.children(&mut cursor) {
                if matches!(child.kind(), "typed_parameter" | "typed_default_parameter") {
                    if let Some(type_node) = child.child_by_field_name("type") {
                        emit_use_names_recursive(ctx, type_node, events);
                    }
                }
            }
        }
        if let Some(return_type_node) = node.child_by_field_name("return_type") {
            emit_use_names_recursive(ctx, return_type_node, events);
        }

        let docstring = extract_body_docstring(ctx, node);
        events.push(Event::define_name(
            name.clone(),
            qualname.clone(),
            "function",
            node,
            ctx.file_path,
        ));
        events.push(Event::enter_scope_with_docstring(
            ScopeType::Function,
            name.clone(),
            qualname.clone(),
            parameters,
            vec![],
            docstring,
            node,
            ctx.file_path,
        ));
        // exit_scope is emitted by walk_node_python after processing children
    }
}

/// PRE phase: emit only DefineName for assignments (scope/definition tracking).
/// The Assignment event is emitted POST (after RHS children are walked) via
/// `emit_assignment_post_event`, so call nodes on the RHS appear before the
/// assignment node in the PDG.
fn emit_assignment_define_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    if let Some(left_node) = node.child_by_field_name("left") {
        match left_node.kind() {
            "identifier" => {
                let name = get_node_text(ctx, left_node);
                let qualname = build_qualname(ctx, node, &name);
                let start_pos = left_node.start_position();
                let end_line = node.end_position().row + 1;
                events.push(Event::DefineName {
                    node_id: generate_node_id(ctx.file_path, left_node),
                    name: name.clone(),
                    qualname: qualname.clone(),
                    node_type: "variable".to_string(),
                    file: ctx.file_path.to_string(),
                    line: start_pos.row + 1,
                    end_line,
                    column: start_pos.column,
                });
            }
            "pattern_list" | "tuple_pattern" => {
                let mut cursor = left_node.walk();
                for part in left_node.children(&mut cursor) {
                    if part.kind() == "identifier" {
                        let name = get_node_text(ctx, part);
                        let qualname = build_qualname(ctx, node, &name);
                        events.push(Event::define_name(
                            name,
                            qualname,
                            "variable",
                            part,
                            ctx.file_path,
                        ));
                    }
                }
            }
            _ => {}
        }
    }
}

/// POST phase: emit Assignment event after RHS children have been walked.
fn emit_assignment_post_event(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    if let Some(left_node) = node.child_by_field_name("left") {
        if let Some(right_node) = node.child_by_field_name("right") {
            let value = get_node_text(ctx, right_node);
            let value_type = classify_value_type(right_node.kind());
            match left_node.kind() {
                "identifier" => {
                    let name = get_node_text(ctx, left_node);
                    let qualname = build_qualname(ctx, node, &name);
                    events.push(Event::assignment(
                        name,
                        qualname,
                        value,
                        value_type,
                        node,
                        ctx.file_path,
                    ));
                }
                "pattern_list" | "tuple_pattern" => {
                    let target = get_node_text(ctx, left_node);
                    let qualname = build_qualname(ctx, node, &target);
                    events.push(Event::assignment(
                        target,
                        qualname,
                        value,
                        value_type,
                        node,
                        ctx.file_path,
                    ));
                }
                _ => {}
            }
        }
    }
}

/// PRE phase: emit DefineName for annotated assignments (`x: Type = value`).
fn emit_annotated_assignment_define_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    if let Some(name_node) = node.child_by_field_name("name") {
        if name_node.kind() == "identifier" {
            let name = get_node_text(ctx, name_node);
            let qualname = build_qualname(ctx, node, &name);
            events.push(Event::define_name(name, qualname, "variable", name_node, ctx.file_path));
        }
    }
}

/// POST phase: emit Assignment event for annotated assignments that have a value.
fn emit_annotated_assignment_post_event(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    let name_node = match node.child_by_field_name("name") {
        Some(n) if n.kind() == "identifier" => n,
        _ => return,
    };
    let value_node = match node.child_by_field_name("value") {
        Some(v) => v,
        None => return, // declaration-only annotation, no RHS
    };
    let name = get_node_text(ctx, name_node);
    let qualname = build_qualname(ctx, node, &name);
    let value = get_node_text(ctx, value_node);
    let value_type = classify_value_type(value_node.kind());
    events.push(Event::assignment(name, qualname, value, value_type, node, ctx.file_path));
}

/// Emit DefineName for a Python 3.12 `type Alias = ...` statement.
fn emit_type_alias_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    if let Some(name_node) = node.child_by_field_name("name") {
        if name_node.kind() == "identifier" {
            let name = get_node_text(ctx, name_node);
            let qualname = build_qualname(ctx, node, &name);
            events.push(Event::define_name(name, qualname, "variable", name_node, ctx.file_path));
        }
    }
    // UseName for type expression identifiers is handled by normal recursion.
}

/// Classify the type of a value expression
fn classify_value_type(kind: &str) -> &'static str {
    match kind {
        "string" | "integer" | "float" | "true" | "false" | "none" => "literal",
        "call" => "call",
        "identifier" => "name",
        "attribute" => "attribute",
        "list" | "tuple" | "dictionary" | "set" => "collection",
        _ => "expression",
    }
}

/// Emit events for identifier usage
fn emit_identifier_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    // Only emit use_name if this identifier is not part of a definition
    if let Some(parent) = node.parent() {
        let parent_kind = parent.kind();

        // Skip if this is a definition context
        if matches!(parent_kind, "function_definition" | "class_definition") {
            if let Some(name_field) = parent.child_by_field_name("name") {
                if name_field.id() == node.id() {
                    return; // This is the name being defined, not used
                }
            }
        }

        // Skip if this is part of an assignment target
        if parent_kind == "assignment" {
            if let Some(left) = parent.child_by_field_name("left") {
                if left.id() == node.id() {
                    return; // This is being assigned to, not used
                }
            }
        }

        // Skip if this is the name field of an annotated assignment (e.g., `x: Type = value`)
        if parent_kind == "annotated_assignment" {
            if let Some(name_field) = parent.child_by_field_name("name") {
                if name_field.id() == node.id() {
                    return;
                }
            }
        }

        // Skip if this is a keyword argument name (e.g., `target` in `f(target=x)`)
        if parent_kind == "keyword_argument" {
            if let Some(name_field) = parent.child_by_field_name("name") {
                if name_field.id() == node.id() {
                    return;
                }
            }
        }

        // Skip if this is the name field of a type alias statement (Python 3.12 `type X = ...`)
        if parent_kind == "type_alias_statement" {
            if let Some(name_field) = parent.child_by_field_name("name") {
                if name_field.id() == node.id() {
                    return;
                }
            }
        }

        // Skip if this is the bound variable in an except clause (e.g., `e` in `except E as e:`)
        if parent_kind == "except_clause" {
            if let Some(name_field) = parent.child_by_field_name("name") {
                if name_field.id() == node.id() {
                    return;
                }
            }
        }

        // Skip if this is part of an import
        if matches!(
            parent_kind,
            "import_statement" | "import_from_statement" | "dotted_name"
        ) {
            return;
        }

        // Skip if this is part of an attribute access (will be handled separately)
        if parent_kind == "attribute" {
            return;
        }

        // Otherwise, this is a use
        let name = get_node_text(ctx, node);
        events.push(Event::use_name(name, node, ctx.file_path));
    }
}

/// Emit events for function/method calls
fn emit_call_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    if let Some(function_node) = node.child_by_field_name("function") {
        let callee = get_node_text(ctx, function_node);

        // Extract top-level argument expressions
        let mut arguments = Vec::new();
        if let Some(args_node) = node.child_by_field_name("arguments") {
            let mut cursor = args_node.walk();
            for child in args_node.children(&mut cursor) {
                match child.kind() {
                    // Skip punctuation and the parens themselves
                    "(" | ")" | "," => {}
                    // For keyword arguments, capture "key=value" text
                    _ => {
                        let text = get_node_text(ctx, child);
                        if !text.is_empty() {
                            arguments.push(text);
                        }
                    }
                }
            }
        }

        events.push(Event::call_expression(
            callee,
            arguments,
            node,
            ctx.file_path,
        ));
    }
}

/// Emit events for attribute access (e.g., obj.attr)
fn emit_attribute_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    let object = node
        .child_by_field_name("object")
        .map(|n| get_node_text(ctx, n))
        .unwrap_or_default();

    let attribute = node
        .child_by_field_name("attribute")
        .map(|n| get_node_text(ctx, n))
        .unwrap_or_default();

    events.push(Event::attribute_access(
        object,
        attribute,
        node,
        ctx.file_path,
    ));
}

/// Emit DefineName events for all identifiers within a pattern/target node.
/// Handles simple identifiers and tuple/pattern unpacking.
fn emit_define_identifiers_in(ctx: &ParseContext, target_node: Node, scope_node: Node, events: &mut Vec<Event>) {
    match target_node.kind() {
        "identifier" => {
            let name = get_node_text(ctx, target_node);
            let qualname = build_qualname(ctx, scope_node, &name);
            events.push(Event::define_name(name, qualname, "variable", target_node, ctx.file_path));
        }
        "pattern_list" | "tuple_pattern" => {
            let mut cursor = target_node.walk();
            for child in target_node.children(&mut cursor) {
                if child.kind() == "identifier" {
                    let name = get_node_text(ctx, child);
                    let qualname = build_qualname(ctx, scope_node, &name);
                    events.push(Event::define_name(name, qualname, "variable", child, ctx.file_path));
                }
            }
        }
        _ => {}
    }
}

/// Emit events for control flow blocks
fn emit_control_block_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>, kind: &str) {
    let block_type = match kind {
        "if_statement" => "if",
        "for_statement" => "for",
        "while_statement" => "while",
        "try_statement" => "try",
        "with_statement" => "with",
        "async_for_statement" | "async_for" => "async_for",
        "async_with_statement" | "async_with" => "async_with",
        _ => kind,
    };

    // Extract the condition/expression based on block type
    let condition = match kind {
        "if_statement" | "while_statement" => {
            // if/while have a "condition" field
            node.child_by_field_name("condition")
                .map(|n| get_node_text(ctx, n))
                .unwrap_or_default()
        }
        "for_statement" | "async_for_statement" | "async_for" => {
            // for has "left" (loop var) and "right" (iterable)
            let left = node
                .child_by_field_name("left")
                .map(|n| get_node_text(ctx, n))
                .unwrap_or_default();
            let right = node
                .child_by_field_name("right")
                .map(|n| get_node_text(ctx, n))
                .unwrap_or_default();
            format!("{} in {}", left, right)
        }
        "with_statement" | "async_with_statement" | "async_with" => {
            // Extract the context expression
            let mut cursor = node.walk();
            let result = node
                .children(&mut cursor)
                .find(|c| c.kind() == "with_clause" || c.kind() == "with_item")
                .map(|n| get_node_text(ctx, n))
                .unwrap_or_default();
            result
        }
        "try_statement" => "try".to_string(),
        _ => String::new(),
    };

    events.push(Event::control_block(
        block_type,
        condition,
        node,
        ctx.file_path,
    ));

    // Feature 3: Bind for-loop variables so they are resolvable inside the loop body.
    if matches!(kind, "for_statement" | "async_for_statement" | "async_for") {
        if let Some(left_node) = node.child_by_field_name("left") {
            emit_define_identifiers_in(ctx, left_node, node, events);
        }
    }

    // Feature 4: Bind with-statement `as` variables.
    if matches!(kind, "with_statement" | "async_with_statement" | "async_with") {
        let mut outer_cursor = node.walk();
        for child in node.children(&mut outer_cursor) {
            if child.kind() == "with_clause" {
                let mut clause_cursor = child.walk();
                for with_item in child.children(&mut clause_cursor) {
                    if with_item.kind() == "with_item" {
                        if let Some(alias_node) = with_item.child_by_field_name("alias") {
                            emit_define_identifiers_in(ctx, alias_node, node, events);
                        }
                    }
                }
            } else if child.kind() == "with_item" {
                if let Some(alias_node) = child.child_by_field_name("alias") {
                    emit_define_identifiers_in(ctx, alias_node, node, events);
                }
            }
        }
    }
}

/// Emit events for return statements
fn emit_return_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    // Get the return value if present
    let mut cursor = node.walk();
    let value_node = node.children(&mut cursor).find(|c| c.kind() != "return");

    let (value, value_type) = if let Some(val_node) = value_node {
        let val_text = get_node_text(ctx, val_node);
        let val_type = classify_value_type(val_node.kind());
        (val_text, val_type)
    } else {
        (String::new(), "none")
    };

    events.push(Event::return_stmt(value, value_type, node, ctx.file_path));
}

/// Emit events for break statements
fn emit_break_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    events.push(Event::break_statement(node, ctx.file_path));
}

/// Emit events for continue statements
fn emit_continue_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    events.push(Event::continue_statement(node, ctx.file_path));
}

/// Emit events for raise statements
fn emit_raise_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    // Get the exception expression if present
    let mut cursor = node.walk();
    let exception_node = node.children(&mut cursor).find(|c| c.kind() != "raise");

    let exception = if let Some(exc_node) = exception_node {
        get_node_text(ctx, exc_node)
    } else {
        String::new()
    };

    events.push(Event::raise_statement(exception, node, ctx.file_path));
}

/// Emit events for literal values (strings, numbers, booleans, None)
fn emit_literal_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>, kind: &str) {
    let value = get_node_text(ctx, node);
    let literal_type = match kind {
        "string" => "string",
        "integer" => "integer",
        "float" => "float",
        "true" | "false" => "boolean",
        "none" => "none",
        _ => "unknown",
    };

    events.push(Event::literal(value, literal_type, node, ctx.file_path));
}

// ============================================================================
// Helper Functions
// ============================================================================

/// Get the text content of a node
fn get_node_text(ctx: &ParseContext, node: Node) -> String {
    ctx.source[node.start_byte()..node.end_byte()].to_string()
}

/// Build qualified name by walking up the TreeSitter parent chain
/// This leverages TreeSitter's native parent tracking instead of manual stacks
fn build_qualname(ctx: &ParseContext, node: Node, name: &str) -> String {
    let mut parts = Vec::new();

    // Add the current node's name first
    if name != "module" && !name.is_empty() {
        parts.push(name.to_string());
    }

    // Walk up the parent chain to build the qualified name
    let mut current = node.parent();
    while let Some(parent) = current {
        let parent_kind = parent.kind();

        // Only add names from scope-creating nodes (classes and functions)
        if is_scope_creating_node(parent_kind) {
            if let Some(parent_name_node) = parent.child_by_field_name("name") {
                let parent_name = ctx.source
                    [parent_name_node.start_byte()..parent_name_node.end_byte()]
                    .to_string();
                parts.insert(0, parent_name);
            }
        }

        current = parent.parent();
    }

    // Add module path if present
    if !ctx.module_path.is_empty() {
        let mut full_parts = ctx.module_path.clone();
        full_parts.extend(parts);
        return full_parts.join(".");
    }

    if parts.is_empty() {
        name.to_string()
    } else {
        parts.join(".")
    }
}

/// Check if a node type creates a scope for qualified names
fn is_scope_creating_node(kind: &str) -> bool {
    matches!(kind, "class_definition" | "function_definition")
}

/// Emit events for else clauses
fn emit_else_block_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    events.push(Event::else_block(
        "else",
        String::new(),
        node,
        ctx.file_path,
    ));
}

/// Emit events for elif clauses
fn emit_elif_block_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    // elif has a condition child
    let condition = node
        .child_by_field_name("condition")
        .map(|n| get_node_text(ctx, n))
        .unwrap_or_default();
    events.push(Event::else_block("elif", condition, node, ctx.file_path));
}

// ============================================================================
// Phase 3 & 4: New Emit Functions
// ============================================================================

/// Check if a node is inside an `if TYPE_CHECKING:` block
fn is_in_type_checking_block(ctx: &ParseContext, node: Node) -> bool {
    let mut current = node.parent();
    while let Some(parent) = current {
        if parent.kind() == "if_statement" {
            if let Some(cond) = parent.child_by_field_name("condition") {
                let cond_text = get_node_text(ctx, cond);
                if cond_text == "TYPE_CHECKING" {
                    return true;
                }
            }
        }
        current = parent.parent();
    }
    false
}

/// Emit events for decorator expressions
fn emit_decorator_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    let mut cursor = node.walk();
    // A decorator node has one child: the expression (@expr)
    for child in node.children(&mut cursor) {
        match child.kind() {
            "identifier" => {
                let name = get_node_text(ctx, child);
                events.push(Event::decorator(name, false, vec![], node, ctx.file_path));
            }
            "attribute" => {
                let name = get_node_text(ctx, child);
                events.push(Event::decorator(name, false, vec![], node, ctx.file_path));
            }
            "call" => {
                let callee = child
                    .child_by_field_name("function")
                    .map(|n| get_node_text(ctx, n))
                    .unwrap_or_default();
                let mut args = Vec::new();
                if let Some(args_node) = child.child_by_field_name("arguments") {
                    let mut c = args_node.walk();
                    for arg in args_node.children(&mut c) {
                        match arg.kind() {
                            "(" | ")" | "," => {}
                            _ => {
                                let text = get_node_text(ctx, arg);
                                if !text.is_empty() {
                                    args.push(text);
                                }
                            }
                        }
                    }
                }
                events.push(Event::decorator(callee, true, args, node, ctx.file_path));
            }
            _ => {}
        }
    }
}

/// Emit events for match statements (Python 3.10+)
fn emit_match_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    let subject = node
        .child_by_field_name("subject")
        .map(|n| get_node_text(ctx, n))
        .unwrap_or_default();
    events.push(Event::control_block("match", subject, node, ctx.file_path));
}

/// Emit events for case clauses within match statements
fn emit_case_clause_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    let pattern = node
        .child_by_field_name("pattern")
        .map(|n| get_node_text(ctx, n))
        .unwrap_or_default();
    events.push(Event::else_block("case", pattern, node, ctx.file_path));
}

/// Emit events for walrus operator := (named_expression)
fn emit_named_expression_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    if let Some(name_node) = node.child_by_field_name("name") {
        let name = get_node_text(ctx, name_node);
        let qualname = build_qualname(ctx, node, &name);
        events.push(Event::define_name(
            name.clone(),
            qualname.clone(),
            "variable",
            name_node,
            ctx.file_path,
        ));
        if let Some(value_node) = node.child_by_field_name("value") {
            let value = get_node_text(ctx, value_node);
            let value_type = classify_value_type(value_node.kind());
            events.push(Event::assignment(
                name,
                qualname,
                value,
                value_type,
                node,
                ctx.file_path,
            ));
        }
    }
}

/// Emit events for comprehension expressions (list/dict/set/generator)
fn emit_comprehension_events(
    ctx: &ParseContext,
    node: Node,
    events: &mut Vec<Event>,
    kind: &str,
) {
    let scope_name = format!(
        "<{}>",
        match kind {
            "list_comprehension" => "listcomp",
            "dictionary_comprehension" => "dictcomp",
            "set_comprehension" => "setcomp",
            "generator_expression" => "genexpr",
            _ => kind,
        }
    );
    let qualname = build_qualname(ctx, node, &scope_name);
    // Emit both enter and exit immediately — comprehensions are not tracked via scope_info
    events.push(Event::enter_scope(
        ScopeType::Comprehension,
        scope_name.clone(),
        qualname.clone(),
        vec![],
        vec![],
        node,
        ctx.file_path,
    ));
    events.push(Event::exit_scope(
        ScopeType::Comprehension,
        scope_name,
        qualname,
        node,
        ctx.file_path,
    ));
}

/// Emit events for lambda expressions
/// Note: enter_scope is emitted here; exit_scope is emitted by walk_node_python
/// via the scope_info tracking for "lambda" nodes.
fn emit_lambda_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    let pos = node.start_position();
    let scope_name = format!("<lambda:{}>", pos.row + 1);
    let qualname = build_qualname(ctx, node, &scope_name);

    // Extract lambda parameters
    let mut parameters = Vec::new();
    if let Some(params_node) = node.child_by_field_name("parameters") {
        let mut cursor = params_node.walk();
        for child in params_node.children(&mut cursor) {
            match child.kind() {
                "identifier" => {
                    let param_name = get_node_text(ctx, child);
                    parameters.push(param_name);
                }
                "default_parameter" => {
                    if let Some(param_name_node) = child.child_by_field_name("name") {
                        parameters.push(get_node_text(ctx, param_name_node));
                    }
                }
                _ => {}
            }
        }
    }

    events.push(Event::define_name(
        scope_name.clone(),
        qualname.clone(),
        "function",
        node,
        ctx.file_path,
    ));
    // Only emit enter_scope here; exit_scope is deferred to walk_node_python via scope_info
    events.push(Event::enter_scope(
        ScopeType::Lambda,
        scope_name,
        qualname,
        parameters,
        vec![],
        node,
        ctx.file_path,
    ));
}

/// Emit events for augmented assignments (+=, -=, etc.)
fn emit_augmented_assignment_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    if let Some(left_node) = node.child_by_field_name("left") {
        if left_node.kind() == "identifier" {
            let name = get_node_text(ctx, left_node);
            let qualname = build_qualname(ctx, node, &name);
            // Augmented assignment reads AND writes the target
            events.push(Event::use_name(name.clone(), left_node, ctx.file_path));
            if let Some(right_node) = node.child_by_field_name("right") {
                let value = get_node_text(ctx, right_node);
                let value_type = classify_value_type(right_node.kind());
                events.push(Event::assignment(
                    name,
                    qualname,
                    value,
                    value_type,
                    node,
                    ctx.file_path,
                ));
            }
        }
    }
}

/// Emit events for global/nonlocal statements
fn emit_global_nonlocal_events(
    ctx: &ParseContext,
    node: Node,
    events: &mut Vec<Event>,
    kind: &str,
) {
    let decl_type = if kind == "global_statement" {
        "global"
    } else {
        "nonlocal"
    };
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        if child.kind() == "identifier" {
            let name = get_node_text(ctx, child);
            let qualname = build_qualname(ctx, node, &name);
            events.push(Event::define_name(
                name,
                qualname,
                decl_type,
                child,
                ctx.file_path,
            ));
        }
    }
}

/// Emit events for assert statements
fn emit_assert_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    let condition = node
        .child_by_field_name("condition")
        .map(|n| get_node_text(ctx, n))
        .unwrap_or_default();
    events.push(Event::control_block("assert", condition, node, ctx.file_path));
    events.push(Event::end_control_block("assert", node, ctx.file_path));
}

/// Emit events for delete statements
fn emit_delete_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        if child.kind() == "identifier" {
            let name = get_node_text(ctx, child);
            events.push(Event::use_name(name, child, ctx.file_path));
        }
    }
}

/// Emit events for yield expressions
fn emit_yield_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    let mut cursor = node.walk();
    let children: Vec<Node> = node.children(&mut cursor).collect();

    // Check if this is `yield from` by looking for "from" keyword child
    let is_from = children.iter().any(|c| c.kind() == "from");

    // Get the value (the expression after yield or yield from)
    let value = children
        .iter()
        .find(|c| !matches!(c.kind(), "yield" | "from"))
        .map(|n| get_node_text(ctx, *n))
        .unwrap_or_default();

    events.push(Event::yield_expression(value, is_from, node, ctx.file_path));
}

/// Emit events for except clauses (exception variable binding + type use).
fn emit_except_clause_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    // except SomeException as e: -> bind 'e' as a variable
    if let Some(name_node) = node.child_by_field_name("name") {
        if name_node.kind() == "identifier" {
            let name = get_node_text(ctx, name_node);
            let qualname = build_qualname(ctx, node, &name);
            events.push(Event::define_name(
                name,
                qualname,
                "variable",
                name_node,
                ctx.file_path,
            ));
        }
    }

    // Emit UseName for the exception type(s): `except ValueError as e:` → UseName("ValueError")
    // Also handles tuples: `except (ValueError, TypeError):` → UseName for each
    if let Some(type_node) = node.child_by_field_name("type") {
        emit_use_names_recursive(ctx, type_node, events);
    }
}

/// Recursively emit UseName for every identifier/type_identifier within a node.
/// Used for type expressions where we want to capture all referenced type names.
fn emit_use_names_recursive(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    match node.kind() {
        "identifier" | "type_identifier" => {
            let name = get_node_text(ctx, node);
            events.push(Event::use_name(name, node, ctx.file_path));
        }
        _ => {
            let mut cursor = node.walk();
            for child in node.children(&mut cursor) {
                emit_use_names_recursive(ctx, child, events);
            }
        }
    }
}

fn walk_node_python(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    let kind = node.kind();

    // Track if this node creates a scope (we need to emit exit after children)
    let scope_info = match kind {
        "class_definition" => {
            if let Some(name_node) = node.child_by_field_name("name") {
                let name = get_node_text(ctx, name_node);
                let qualname = build_qualname(ctx, node, &name);
                Some((ScopeType::Class, name, qualname))
            } else {
                None
            }
        }
        "function_definition" => {
            if let Some(name_node) = node.child_by_field_name("name") {
                let name = get_node_text(ctx, name_node);
                let qualname = build_qualname(ctx, node, &name);
                Some((ScopeType::Function, name, qualname))
            } else {
                None
            }
        }
        "lambda" => {
            let pos = node.start_position();
            let name = format!("<lambda:{}>", pos.row + 1);
            let qualname = build_qualname(ctx, node, &name);
            Some((ScopeType::Lambda, name, qualname))
        }
        _ => None,
    };

    // Track whether this is an assignment node — Assignment event is emitted POST
    // (after children are walked) so that the RHS expression events (CallExpression,
    // UseName) fire before the assignment node is created in the PDG.
    let is_assignment = kind == "assignment";
    let is_annotated_assignment = kind == "annotated_assignment";

    // Call events are also emitted POST so that nested calls (arguments evaluated
    // before the outer call) fire in the correct execution order.
    // e.g. car.drive(math.sqrt(25)): math.sqrt fires first (argument), then car.drive.
    let is_call = kind == "call";

    // Track control block info for emitting end events
    let control_block_info = match kind {
        "if_statement" | "for_statement" | "while_statement" | "try_statement"
        | "with_statement" | "async_for_statement" | "async_with_statement" => Some(kind),
        _ => None,
    };

    // Emit events based on node type
    match kind {
        "import_statement" | "import_from_statement" => emit_import_events(ctx, node, events),
        "class_definition" => emit_class_events(ctx, node, events),
        "function_definition" => emit_function_events(ctx, node, events),
        "assignment" => emit_assignment_define_events(ctx, node, events),
        "annotated_assignment" => emit_annotated_assignment_define_events(ctx, node, events),
        "type_alias_statement" => emit_type_alias_events(ctx, node, events),
        "identifier" => emit_identifier_events(ctx, node, events),
        "attribute" => emit_attribute_events(ctx, node, events),
        "if_statement" | "for_statement" | "while_statement" | "try_statement"
        | "with_statement" => emit_control_block_events(ctx, node, events, kind),
        "else_clause" => emit_else_block_events(ctx, node, events),
        "elif_clause" => emit_elif_block_events(ctx, node, events),
        "return_statement" => emit_return_events(ctx, node, events),
        "break_statement" => emit_break_events(ctx, node, events),
        "continue_statement" => emit_continue_events(ctx, node, events),
        "raise_statement" => emit_raise_events(ctx, node, events),
        "string" | "integer" | "float" | "true" | "false" | "none" => {
            emit_literal_events(ctx, node, events, kind)
        }
        "decorator" => emit_decorator_events(ctx, node, events),
        "match_statement" => emit_match_events(ctx, node, events),
        "case_clause" => emit_case_clause_events(ctx, node, events),
        "named_expression" => emit_named_expression_events(ctx, node, events),
        "list_comprehension" | "dictionary_comprehension" | "set_comprehension"
        | "generator_expression" => emit_comprehension_events(ctx, node, events, kind),
        "lambda" => emit_lambda_events(ctx, node, events),
        "augmented_assignment" => emit_augmented_assignment_events(ctx, node, events),
        "global_statement" | "nonlocal_statement" => {
            emit_global_nonlocal_events(ctx, node, events, kind)
        }
        "assert_statement" => emit_assert_events(ctx, node, events),
        "delete_statement" => emit_delete_events(ctx, node, events),
        "yield" => emit_yield_events(ctx, node, events),
        "async_for_statement" => emit_control_block_events(ctx, node, events, "async_for"),
        "async_with_statement" => emit_control_block_events(ctx, node, events, "async_with"),
        "except_clause" => emit_except_clause_events(ctx, node, events),
        _ => {}
    }

    // Walk all children
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        walk_node_python(ctx, child, events);
    }

    // Emit Assignment event after children so the RHS call/use events fire first,
    // giving correct PDG ordering: build_car → car, not car → build_car.
    if is_assignment {
        emit_assignment_post_event(ctx, node, events);
    }
    if is_annotated_assignment {
        emit_annotated_assignment_post_event(ctx, node, events);
    }

    // Emit Call event after children so nested argument calls fire first
    // (execution order: inner calls before outer call).
    if is_call {
        emit_call_events(ctx, node, events);
    }

    // Emit end_control_block after walking children
    if let Some(block_kind) = control_block_info {
        let block_type = match block_kind {
            "if_statement" => "if",
            "for_statement" => "for",
            "while_statement" => "while",
            "try_statement" => "try",
            "with_statement" => "with",
            "async_for_statement" => "async_for",
            "async_with_statement" => "async_with",
            _ => block_kind,
        };
        events.push(Event::end_control_block(block_type, node, ctx.file_path));
    }

    // Emit exit_scope after walking children
    if let Some((scope_type, name, qualname)) = scope_info {
        events.push(Event::exit_scope(
            scope_type,
            name,
            qualname,
            node,
            ctx.file_path,
        ));
    }
}

fn resolve_relative_import(ctx: &ParseContext, level: usize, module_name: &str) -> String {
    // level 1 = from . import (current package)
    // level 2 = from .. import (parent package)
    // etc.

    let current_parts = &ctx.module_path;

    // For __init__.py, module_path is already the package (e.g. ["requests"]).
    // level=1 means "this package", so we should not subtract anything.
    // For regular modules, module_path includes the file stem (e.g. ["requests","sessions"]),
    // and level=1 means "go up to the package", so we subtract 1.
    let effective_level = if ctx.is_init && level > 0 { level - 1 } else { level };

    if current_parts.is_empty() || effective_level > current_parts.len() {
        // Can't resolve, return as-is with dots preserved for debugging
        let dots = ".".repeat(level);
        if module_name.is_empty() {
            return dots;
        }
        return format!("{}{}", dots, module_name);
    }

    // Go up 'effective_level' directories
    let base_len = current_parts.len().saturating_sub(effective_level);
    let base_parts: Vec<&str> = current_parts
        .iter()
        .take(base_len)
        .map(|s| s.as_str())
        .collect();

    if module_name.is_empty() {
        // from . import x - the module is the parent package itself
        base_parts.join(".")
    } else {
        // from .foo import x - combine base with the submodule
        if base_parts.is_empty() {
            module_name.to_string()
        } else {
            format!("{}.{}", base_parts.join("."), module_name)
        }
    }
}

pub fn parse(source: &str, tree: &Option<Tree>, file_path: &str) -> Vec<Event> {
    let mut events = Vec::new();

    // Emit source line events first so subscribers can capture the raw source
    for (i, line) in source.lines().enumerate() {
        events.push(Event::SourceLine {
            file: file_path.to_string(),
            line_number: i + 1,
            text: line.to_string(),
        });
    }

    if let Some(tree) = tree {
        let root = tree.root_node();
        let module_path = derive_module_path(file_path);
        let is_init = std::path::Path::new(file_path)
            .file_stem()
            .and_then(|s| s.to_str())
            .map(|s| s == "__init__")
            .unwrap_or(false);
        let context = ParseContext {
            source,
            file_path,
            module_path,
            is_init,
        };

        // Emit module-level EnterScope so the docstring and scope range are captured.
        let module_qualname = context.module_path.join(".");
        let module_name = context.module_path.last().cloned().unwrap_or_else(|| "module".to_string());
        let module_docstring = extract_module_docstring(&context, root);
        events.push(Event::enter_scope_with_docstring(
            ScopeType::Module,
            module_name.clone(),
            module_qualname.clone(),
            vec![],
            vec![],
            module_docstring,
            root,
            file_path,
        ));

        walk_node_python(&context, root, &mut events);

        events.push(Event::exit_scope(
            ScopeType::Module,
            module_name,
            module_qualname,
            root,
            file_path,
        ));
    }
    events
}

fn is_in_type_checking_block(ctx: &ParseContext, node: Node) -> bool {
    let mut current = node.parent();
    while let Some(parent) = current {
        if parent.kind() == "if_statement" {
            if let Some(cond) = parent.child_by_field_name("condition") {
                let cond_text = get_node_text(ctx, cond);
                if cond_text == "TYPE_CHECKING" {
                    return true;
                }
            }
        }
        current = parent.parent();
    }
    false
}

fn is_ancestor(potential_ancestor: Node, node: Node) -> bool {
    let mut current = node.parent();
    while let Some(parent) = current {
        if parent.id() == potential_ancestor.id() {
            return true;
        }
        current = parent.parent();
    }
    false
}

fn has_passed_import_keyword(ctx: &ParseContext, parent: Node, node: Node) -> bool {
    let mut cursor = parent.walk();
    let mut found_import = false;

    for child in parent.children(&mut cursor) {
        if child.kind() == "import" {
            found_import = true;
            continue;
        }
        if found_import && child.id() == node.id() {
            return true;
        }
        // Also check inside lists like (a, b, c)
        if found_import
            && (child.kind() == "import_from_as_names"
                || child.kind() == "identifier"
                || child.kind() == "dotted_name"
                || child.kind() == "aliased_import")
        {
            // Check if our node is this child or a descendant
            if child.id() == node.id() || is_ancestor(child, node) {
                return true;
            }
        }
    }

    // Fallback: check byte positions
    // Find the "import" keyword position
    let parent_text = get_node_text(ctx, parent);
    if let Some(import_pos) = parent_text.find("import") {
        let import_end = parent.start_byte() + import_pos + 6;
        return node.start_byte() > import_end;
    }

    false
}

fn extract_module_docstring(ctx: &ParseContext, root: Node) -> Option<String> {
    let mut cursor = root.walk();
    for child in root.children(&mut cursor) {
        match child.kind() {
            "comment" => continue,
            "expression_statement" => {
                let mut c2 = child.walk();
                for inner in child.children(&mut c2) {
                    if inner.kind() == "string" {
                        let raw = get_node_text(ctx, inner);
                        return Some(clean_docstring(&raw));
                    }
                }
                return None;
            }
            _ => return None,
        }
    }
    None
}

fn extract_body_docstring(ctx: &ParseContext, node: Node) -> Option<String> {
    let body = node.child_by_field_name("body")?;
    let mut cursor = body.walk();
    for child in body.children(&mut cursor) {
        match child.kind() {
            "decorator" | "comment" => continue,
            "expression_statement" => {
                let mut c2 = child.walk();
                for inner in child.children(&mut c2) {
                    if inner.kind() == "string" {
                        let raw = get_node_text(ctx, inner);
                        return Some(clean_docstring(&raw));
                    }
                }
                return None;
            }
            _ => return None,
        }
    }
    None
}

fn emit_yield_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    let mut cursor = node.walk();
    let children: Vec<Node> = node.children(&mut cursor).collect();

    // Check if this is `yield from` by looking for "from" keyword child
    let is_from = children.iter().any(|c| c.kind() == "from");

    // Get the value (the expression after yield or yield from)
    let value = children
        .iter()
        .find(|c| !matches!(c.kind(), "yield" | "from"))
        .map(|n| get_node_text(ctx, *n))
        .unwrap_or_default();

    events.push(Event::yield_expression(value, is_from, node, ctx.file_path));
}

fn emit_use_names_recursive(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    match node.kind() {
        "identifier" | "type_identifier" => {
            let name = get_node_text(ctx, node);
            events.push(Event::use_name(name, node, ctx.file_path));
        }
        _ => {
            let mut cursor = node.walk();
            for child in node.children(&mut cursor) {
                emit_use_names_recursive(ctx, child, events);
            }
        }
    }
}

fn emit_type_alias_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    if let Some(name_node) = node.child_by_field_name("name") {
        if name_node.kind() == "identifier" {
            let name = get_node_text(ctx, name_node);
            let qualname = build_qualname(ctx, node, &name);
            events.push(Event::define_name(name, qualname, "variable", name_node, ctx.file_path));
        }
    }
    // UseName for type expression identifiers is handled by normal recursion.
}

fn emit_return_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    // Get the return value if present
    let mut cursor = node.walk();
    let value_node = node.children(&mut cursor).find(|c| c.kind() != "return");

    let (value, value_type) = if let Some(val_node) = value_node {
        let val_text = get_node_text(ctx, val_node);
        let val_type = classify_value_type(val_node.kind());
        (val_text, val_type)
    } else {
        (String::new(), "none")
    };

    events.push(Event::return_stmt(value, value_type, node, ctx.file_path));
}

fn emit_raise_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    // Get the exception expression if present
    let mut cursor = node.walk();
    let exception_node = node.children(&mut cursor).find(|c| c.kind() != "raise");

    let exception = if let Some(exc_node) = exception_node {
        get_node_text(ctx, exc_node)
    } else {
        String::new()
    };

    events.push(Event::raise_statement(exception, node, ctx.file_path));
}

fn emit_named_expression_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    if let Some(name_node) = node.child_by_field_name("name") {
        let name = get_node_text(ctx, name_node);
        let qualname = build_qualname(ctx, node, &name);
        events.push(Event::define_name(
            name.clone(),
            qualname.clone(),
            "variable",
            name_node,
            ctx.file_path,
        ));
        if let Some(value_node) = node.child_by_field_name("value") {
            let value = get_node_text(ctx, value_node);
            let value_type = classify_value_type(value_node.kind());
            events.push(Event::assignment(
                name,
                qualname,
                value,
                value_type,
                node,
                ctx.file_path,
            ));
        }
    }
}

fn emit_match_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    let subject = node
        .child_by_field_name("subject")
        .map(|n| get_node_text(ctx, n))
        .unwrap_or_default();
    events.push(Event::control_block("match", subject, node, ctx.file_path));
}

fn emit_literal_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>, kind: &str) {
    let value = get_node_text(ctx, node);
    let literal_type = match kind {
        "string" => "string",
        "integer" => "integer",
        "float" => "float",
        "true" | "false" => "boolean",
        "none" => "none",
        _ => "unknown",
    };

    events.push(Event::literal(value, literal_type, node, ctx.file_path));
}

fn emit_lambda_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    let pos = node.start_position();
    let scope_name = format!("<lambda:{}>", pos.row + 1);
    let qualname = build_qualname(ctx, node, &scope_name);

    // Extract lambda parameters
    let mut parameters = Vec::new();
    if let Some(params_node) = node.child_by_field_name("parameters") {
        let mut cursor = params_node.walk();
        for child in params_node.children(&mut cursor) {
            match child.kind() {
                "identifier" => {
                    let param_name = get_node_text(ctx, child);
                    parameters.push(param_name);
                }
                "default_parameter" => {
                    if let Some(param_name_node) = child.child_by_field_name("name") {
                        parameters.push(get_node_text(ctx, param_name_node));
                    }
                }
                _ => {}
            }
        }
    }

    events.push(Event::define_name(
        scope_name.clone(),
        qualname.clone(),
        "function",
        node,
        ctx.file_path,
    ));
    // Only emit enter_scope here; exit_scope is deferred to walk_node_python via scope_info
    events.push(Event::enter_scope(
        ScopeType::Lambda,
        scope_name,
        qualname,
        parameters,
        vec![],
        node,
        ctx.file_path,
    ));
}

fn emit_import_name_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    let mut cursor = node.walk();
    let is_tc = is_in_type_checking_block(ctx, node);

    for child in node.children(&mut cursor) {
        match child.kind() {
            "dotted_name" => {
                // Simple import: `import x` or `import x.y.z`
                let module = get_node_text(ctx, child);
                events.push(Event::import_statement(module, vec![], std::collections::HashMap::new(), is_tc, node, ctx.file_path));
            }
            "aliased_import" => {
                // Aliased import: `import x as y`
                if let Some(dotted) = child.child_by_field_name("name") {
                    let module = get_node_text(ctx, dotted);
                    let mut aliases = std::collections::HashMap::new();
                    if let Some(alias_node) = child.child_by_field_name("alias") {
                        let alias = get_node_text(ctx, alias_node);
                        aliases.insert(module.clone(), alias);
                    }
                    events.push(Event::import_statement(module, vec![], aliases, is_tc, node, ctx.file_path));
                }
            }
            _ => {}
        }
    }
}

fn emit_import_from_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    // Extract the module being imported from
    let mut module_name = String::new();
    let mut relative_level = 0;
    let mut cursor = node.walk();

    // First pass: collect module name and relative level
    for child in node.children(&mut cursor) {
        match child.kind() {
            "dotted_name" => {
                // This could be the module name or an imported name
                // The module name comes before "import" keyword
                let text = get_node_text(ctx, child);
                if module_name.is_empty() && !has_passed_import_keyword(ctx, node, child) {
                    module_name = text;
                }
            }
            "relative_import" => {
                // Handle relative imports: from . import x, from .. import x
                let text = get_node_text(ctx, child);
                relative_level = text.chars().filter(|c| *c == '.').count();
                // The tree-sitter Python grammar has no named field for the dotted_name
                // inside relative_import — iterate children to find it.
                let mut ri_cursor = child.walk();
                for ri_child in child.children(&mut ri_cursor) {
                    if ri_child.kind() == "dotted_name" {
                        module_name = get_node_text(ctx, ri_child);
                        break;
                    }
                }
            }
            "import_prefix" => {
                // Dots for relative import level
                let text = get_node_text(ctx, child);
                relative_level = text.chars().filter(|c| *c == '.').count();
            }
            _ => {}
        }
    }

    // Build the full source module path
    let source_module = if relative_level > 0 {
        // Relative import - resolve against current module
        resolve_relative_import(ctx, relative_level, &module_name)
    } else {
        module_name.clone()
    };

    // Second pass: collect imported names and aliases
    let mut imported_names = Vec::new();
    let mut aliases = std::collections::HashMap::new();
    let mut cursor2 = node.walk();

    for child in node.children(&mut cursor2) {
        match child.kind() {
            "wildcard_import" => {
                // from x import *
                imported_names.push("*".to_string());
            }
            "dotted_name" | "identifier" => {
                // Check if this is an imported name (appears after "import" keyword)
                if has_passed_import_keyword(ctx, node, child) {
                    let name = get_node_text(ctx, child);
                    imported_names.push(name);
                }
            }
            "aliased_import" => {
                // from x import y as z - extract original name and alias
                if let Some(name_node) = child.child_by_field_name("name") {
                    let original = get_node_text(ctx, name_node);
                    imported_names.push(original.clone());
                    if let Some(alias_node) = child.child_by_field_name("alias") {
                        let alias = get_node_text(ctx, alias_node);
                        aliases.insert(original, alias);
                    }
                }
            }
            _ => {}
        }
    }

    let is_tc = is_in_type_checking_block(ctx, node);
    events.push(Event::import_statement(
        source_module,
        imported_names,
        aliases,
        is_tc,
        node,
        ctx.file_path,
    ));
}

fn emit_import_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    let kind = node.kind();

    if kind == "import_statement" {
        // Handle: import x, import x.y, import x as y, import x, y, z
        emit_import_name_events(ctx, node, events);
    } else if kind == "import_from_statement" {
        // Handle: from x import y, from x import *, from . import y, etc.
        emit_import_from_events(ctx, node, events);
    }
}

fn emit_identifier_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    // Only emit use_name if this identifier is not part of a definition
    if let Some(parent) = node.parent() {
        let parent_kind = parent.kind();

        // Skip if this is a definition context
        if matches!(parent_kind, "function_definition" | "class_definition") {
            if let Some(name_field) = parent.child_by_field_name("name") {
                if name_field.id() == node.id() {
                    return; // This is the name being defined, not used
                }
            }
        }

        // Skip if this is part of an assignment target
        if parent_kind == "assignment" {
            if let Some(left) = parent.child_by_field_name("left") {
                if left.id() == node.id() {
                    return; // This is being assigned to, not used
                }
            }
        }

        // Skip if this is the name field of an annotated assignment (e.g., `x: Type = value`)
        if parent_kind == "annotated_assignment" {
            if let Some(name_field) = parent.child_by_field_name("name") {
                if name_field.id() == node.id() {
                    return;
                }
            }
        }

        // Skip if this is a keyword argument name (e.g., `target` in `f(target=x)`)
        if parent_kind == "keyword_argument" {
            if let Some(name_field) = parent.child_by_field_name("name") {
                if name_field.id() == node.id() {
                    return;
                }
            }
        }

        // Skip if this is the name field of a type alias statement (Python 3.12 `type X = ...`)
        if parent_kind == "type_alias_statement" {
            if let Some(name_field) = parent.child_by_field_name("name") {
                if name_field.id() == node.id() {
                    return;
                }
            }
        }

        // Skip if this is the bound variable in an except clause (e.g., `e` in `except E as e:`)
        if parent_kind == "except_clause" {
            if let Some(name_field) = parent.child_by_field_name("name") {
                if name_field.id() == node.id() {
                    return;
                }
            }
        }

        // Skip if this is part of an import
        if matches!(
            parent_kind,
            "import_statement" | "import_from_statement" | "dotted_name"
        ) {
            return;
        }

        // Skip if this is part of an attribute access (will be handled separately)
        if parent_kind == "attribute" {
            return;
        }

        // Otherwise, this is a use
        let name = get_node_text(ctx, node);
        events.push(Event::use_name(name, node, ctx.file_path));
    }
}

fn emit_global_nonlocal_events(
    ctx: &ParseContext,
    node: Node,
    events: &mut Vec<Event>,
    kind: &str,
) {
    let decl_type = if kind == "global_statement" {
        "global"
    } else {
        "nonlocal"
    };
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        if child.kind() == "identifier" {
            let name = get_node_text(ctx, child);
            let qualname = build_qualname(ctx, node, &name);
            events.push(Event::define_name(
                name,
                qualname,
                decl_type,
                child,
                ctx.file_path,
            ));
        }
    }
}

fn emit_function_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    if let Some(name_node) = node.child_by_field_name("name") {
        let name = get_node_text(ctx, name_node);
        let qualname = build_qualname(ctx, node, &name);

        // Extract parameter names from the function's parameters node
        let mut parameters = Vec::new();
        if let Some(params_node) = node.child_by_field_name("parameters") {
            let mut cursor = params_node.walk();
            for child in params_node.children(&mut cursor) {
                match child.kind() {
                    "identifier" => {
                        let param_name = get_node_text(ctx, child);
                        if param_name != "self" && param_name != "cls" {
                            parameters.push(param_name);
                        }
                    }
                    "default_parameter" | "typed_parameter" | "typed_default_parameter" => {
                        // These have a "name" field child that is the parameter name
                        if let Some(param_name_node) = child.child_by_field_name("name") {
                            let param_name = get_node_text(ctx, param_name_node);
                            if param_name != "self" && param_name != "cls" {
                                parameters.push(param_name);
                            }
                        }
                    }
                    "list_splat_pattern" | "list_splat" => {
                        // *args
                        let mut cursor2 = child.walk();
                        for inner in child.children(&mut cursor2) {
                            if inner.kind() == "identifier" {
                                let param_name = get_node_text(ctx, inner);
                                if param_name != "self" && param_name != "cls" {
                                    parameters.push(format!("*{}", param_name));
                                }
                            }
                        }
                    }
                    "dictionary_splat_pattern" | "dictionary_splat" => {
                        // **kwargs
                        let mut cursor2 = child.walk();
                        for inner in child.children(&mut cursor2) {
                            if inner.kind() == "identifier" {
                                let param_name = get_node_text(ctx, inner);
                                if param_name != "self" && param_name != "cls" {
                                    parameters.push(format!("**{}", param_name));
                                }
                            }
                        }
                    }
                    _ => {} // Skip commas, parentheses, etc.
                }
            }
        }

        // Feature 7: Emit UseName for type annotations in parameters and return type.
        // These act as secondary type-reference edges (e.g., def f(x: Config) → uses Config).
        if let Some(params_node) = node.child_by_field_name("parameters") {
            let mut cursor = params_node.walk();
            for child in params_node.children(&mut cursor) {
                if matches!(child.kind(), "typed_parameter" | "typed_default_parameter") {
                    if let Some(type_node) = child.child_by_field_name("type") {
                        emit_use_names_recursive(ctx, type_node, events);
                    }
                }
            }
        }
        if let Some(return_type_node) = node.child_by_field_name("return_type") {
            emit_use_names_recursive(ctx, return_type_node, events);
        }

        let docstring = extract_body_docstring(ctx, node);
        events.push(Event::define_name(
            name.clone(),
            qualname.clone(),
            "function",
            node,
            ctx.file_path,
        ));
        events.push(Event::enter_scope_with_docstring(
            ScopeType::Function,
            name.clone(),
            qualname.clone(),
            parameters,
            vec![],
            docstring,
            node,
            ctx.file_path,
        ));
        // exit_scope is emitted by walk_node_python after processing children
    }
}

fn emit_except_clause_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    // except SomeException as e: -> bind 'e' as a variable
    if let Some(name_node) = node.child_by_field_name("name") {
        if name_node.kind() == "identifier" {
            let name = get_node_text(ctx, name_node);
            let qualname = build_qualname(ctx, node, &name);
            events.push(Event::define_name(
                name,
                qualname,
                "variable",
                name_node,
                ctx.file_path,
            ));
        }
    }

    // Emit UseName for the exception type(s): `except ValueError as e:` → UseName("ValueError")
    // Also handles tuples: `except (ValueError, TypeError):` → UseName for each
    if let Some(type_node) = node.child_by_field_name("type") {
        emit_use_names_recursive(ctx, type_node, events);
    }
}

fn emit_else_block_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    events.push(Event::else_block(
        "else",
        String::new(),
        node,
        ctx.file_path,
    ));
}

fn emit_elif_block_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    // elif has a condition child
    let condition = node
        .child_by_field_name("condition")
        .map(|n| get_node_text(ctx, n))
        .unwrap_or_default();
    events.push(Event::else_block("elif", condition, node, ctx.file_path));
}

fn emit_delete_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        if child.kind() == "identifier" {
            let name = get_node_text(ctx, child);
            events.push(Event::use_name(name, child, ctx.file_path));
        }
    }
}

fn emit_define_identifiers_in(ctx: &ParseContext, target_node: Node, scope_node: Node, events: &mut Vec<Event>) {
    match target_node.kind() {
        "identifier" => {
            let name = get_node_text(ctx, target_node);
            let qualname = build_qualname(ctx, scope_node, &name);
            events.push(Event::define_name(name, qualname, "variable", target_node, ctx.file_path));
        }
        "pattern_list" | "tuple_pattern" => {
            let mut cursor = target_node.walk();
            for child in target_node.children(&mut cursor) {
                if child.kind() == "identifier" {
                    let name = get_node_text(ctx, child);
                    let qualname = build_qualname(ctx, scope_node, &name);
                    events.push(Event::define_name(name, qualname, "variable", child, ctx.file_path));
                }
            }
        }
        _ => {}
    }
}

fn emit_decorator_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    let mut cursor = node.walk();
    // A decorator node has one child: the expression (@expr)
    for child in node.children(&mut cursor) {
        match child.kind() {
            "identifier" => {
                let name = get_node_text(ctx, child);
                events.push(Event::decorator(name, false, vec![], node, ctx.file_path));
            }
            "attribute" => {
                let name = get_node_text(ctx, child);
                events.push(Event::decorator(name, false, vec![], node, ctx.file_path));
            }
            "call" => {
                let callee = child
                    .child_by_field_name("function")
                    .map(|n| get_node_text(ctx, n))
                    .unwrap_or_default();
                let mut args = Vec::new();
                if let Some(args_node) = child.child_by_field_name("arguments") {
                    let mut c = args_node.walk();
                    for arg in args_node.children(&mut c) {
                        match arg.kind() {
                            "(" | ")" | "," => {}
                            _ => {
                                let text = get_node_text(ctx, arg);
                                if !text.is_empty() {
                                    args.push(text);
                                }
                            }
                        }
                    }
                }
                events.push(Event::decorator(callee, true, args, node, ctx.file_path));
            }
            _ => {}
        }
    }
}

fn emit_control_block_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>, kind: &str) {
    let block_type = match kind {
        "if_statement" => "if",
        "for_statement" => "for",
        "while_statement" => "while",
        "try_statement" => "try",
        "with_statement" => "with",
        "async_for_statement" | "async_for" => "async_for",
        "async_with_statement" | "async_with" => "async_with",
        _ => kind,
    };

    // Extract the condition/expression based on block type
    let condition = match kind {
        "if_statement" | "while_statement" => {
            // if/while have a "condition" field
            node.child_by_field_name("condition")
                .map(|n| get_node_text(ctx, n))
                .unwrap_or_default()
        }
        "for_statement" | "async_for_statement" | "async_for" => {
            // for has "left" (loop var) and "right" (iterable)
            let left = node
                .child_by_field_name("left")
                .map(|n| get_node_text(ctx, n))
                .unwrap_or_default();
            let right = node
                .child_by_field_name("right")
                .map(|n| get_node_text(ctx, n))
                .unwrap_or_default();
            format!("{} in {}", left, right)
        }
        "with_statement" | "async_with_statement" | "async_with" => {
            // Extract the context expression
            let mut cursor = node.walk();
            let result = node
                .children(&mut cursor)
                .find(|c| c.kind() == "with_clause" || c.kind() == "with_item")
                .map(|n| get_node_text(ctx, n))
                .unwrap_or_default();
            result
        }
        "try_statement" => "try".to_string(),
        _ => String::new(),
    };

    events.push(Event::control_block(
        block_type,
        condition,
        node,
        ctx.file_path,
    ));

    // Feature 3: Bind for-loop variables so they are resolvable inside the loop body.
    if matches!(kind, "for_statement" | "async_for_statement" | "async_for") {
        if let Some(left_node) = node.child_by_field_name("left") {
            emit_define_identifiers_in(ctx, left_node, node, events);
        }
    }

    // Feature 4: Bind with-statement `as` variables.
    if matches!(kind, "with_statement" | "async_with_statement" | "async_with") {
        let mut outer_cursor = node.walk();
        for child in node.children(&mut outer_cursor) {
            if child.kind() == "with_clause" {
                let mut clause_cursor = child.walk();
                for with_item in child.children(&mut clause_cursor) {
                    if with_item.kind() == "with_item" {
                        if let Some(alias_node) = with_item.child_by_field_name("alias") {
                            emit_define_identifiers_in(ctx, alias_node, node, events);
                        }
                    }
                }
            } else if child.kind() == "with_item" {
                if let Some(alias_node) = child.child_by_field_name("alias") {
                    emit_define_identifiers_in(ctx, alias_node, node, events);
                }
            }
        }
    }
}

fn emit_continue_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    events.push(Event::continue_statement(node, ctx.file_path));
}

fn emit_comprehension_events(
    ctx: &ParseContext,
    node: Node,
    events: &mut Vec<Event>,
    kind: &str,
) {
    let scope_name = format!(
        "<{}>",
        match kind {
            "list_comprehension" => "listcomp",
            "dictionary_comprehension" => "dictcomp",
            "set_comprehension" => "setcomp",
            "generator_expression" => "genexpr",
            _ => kind,
        }
    );
    let qualname = build_qualname(ctx, node, &scope_name);
    // Emit both enter and exit immediately — comprehensions are not tracked via scope_info
    events.push(Event::enter_scope(
        ScopeType::Comprehension,
        scope_name.clone(),
        qualname.clone(),
        vec![],
        vec![],
        node,
        ctx.file_path,
    ));
    events.push(Event::exit_scope(
        ScopeType::Comprehension,
        scope_name,
        qualname,
        node,
        ctx.file_path,
    ));
}

fn emit_class_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    if let Some(name_node) = node.child_by_field_name("name") {
        let name = get_node_text(ctx, name_node);
        let qualname = build_qualname(ctx, node, &name);

        // Extract base class names from the superclasses argument list
        let mut bases = Vec::new();
        if let Some(superclasses_node) = node.child_by_field_name("superclasses") {
            let mut cursor = superclasses_node.walk();
            for base_child in superclasses_node.children(&mut cursor) {
                match base_child.kind() {
                    "identifier" => {
                        bases.push(get_node_text(ctx, base_child));
                    }
                    "attribute" => {
                        bases.push(get_node_text(ctx, base_child));
                    }
                    _ => {} // Skip commas, parens, keyword_argument
                }
            }
        }

        let docstring = extract_body_docstring(ctx, node);
        events.push(Event::define_name(
            name.clone(),
            qualname.clone(),
            "class",
            node,
            ctx.file_path,
        ));
        events.push(Event::enter_scope_with_docstring(
            ScopeType::Class,
            name.clone(),
            qualname.clone(),
            Vec::new(),
            bases,
            docstring,
            node,
            ctx.file_path,
        ));
        // exit_scope is emitted by walk_node_python after processing children
    }
}

fn emit_case_clause_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    let pattern = node
        .child_by_field_name("pattern")
        .map(|n| get_node_text(ctx, n))
        .unwrap_or_default();
    events.push(Event::else_block("case", pattern, node, ctx.file_path));
}

fn emit_call_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    if let Some(function_node) = node.child_by_field_name("function") {
        let callee = get_node_text(ctx, function_node);

        // Extract top-level argument expressions
        let mut arguments = Vec::new();
        if let Some(args_node) = node.child_by_field_name("arguments") {
            let mut cursor = args_node.walk();
            for child in args_node.children(&mut cursor) {
                match child.kind() {
                    // Skip punctuation and the parens themselves
                    "(" | ")" | "," => {}
                    // For keyword arguments, capture "key=value" text
                    _ => {
                        let text = get_node_text(ctx, child);
                        if !text.is_empty() {
                            arguments.push(text);
                        }
                    }
                }
            }
        }

        events.push(Event::call_expression(
            callee,
            arguments,
            node,
            ctx.file_path,
        ));
    }
}

fn emit_break_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    events.push(Event::break_statement(node, ctx.file_path));
}

fn emit_augmented_assignment_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    if let Some(left_node) = node.child_by_field_name("left") {
        if left_node.kind() == "identifier" {
            let name = get_node_text(ctx, left_node);
            let qualname = build_qualname(ctx, node, &name);
            // Augmented assignment reads AND writes the target
            events.push(Event::use_name(name.clone(), left_node, ctx.file_path));
            if let Some(right_node) = node.child_by_field_name("right") {
                let value = get_node_text(ctx, right_node);
                let value_type = classify_value_type(right_node.kind());
                events.push(Event::assignment(
                    name,
                    qualname,
                    value,
                    value_type,
                    node,
                    ctx.file_path,
                ));
            }
        }
    }
}

fn emit_attribute_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    let object = node
        .child_by_field_name("object")
        .map(|n| get_node_text(ctx, n))
        .unwrap_or_default();

    let attribute = node
        .child_by_field_name("attribute")
        .map(|n| get_node_text(ctx, n))
        .unwrap_or_default();

    events.push(Event::attribute_access(
        object,
        attribute,
        node,
        ctx.file_path,
    ));
}

fn emit_assignment_post_event(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    if let Some(left_node) = node.child_by_field_name("left") {
        if let Some(right_node) = node.child_by_field_name("right") {
            let value = get_node_text(ctx, right_node);
            let value_type = classify_value_type(right_node.kind());
            match left_node.kind() {
                "identifier" => {
                    let name = get_node_text(ctx, left_node);
                    let qualname = build_qualname(ctx, node, &name);
                    events.push(Event::assignment(
                        name,
                        qualname,
                        value,
                        value_type,
                        node,
                        ctx.file_path,
                    ));
                }
                "pattern_list" | "tuple_pattern" => {
                    let target = get_node_text(ctx, left_node);
                    let qualname = build_qualname(ctx, node, &target);
                    events.push(Event::assignment(
                        target,
                        qualname,
                        value,
                        value_type,
                        node,
                        ctx.file_path,
                    ));
                }
                _ => {}
            }
        }
    }
}

fn emit_assignment_define_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    if let Some(left_node) = node.child_by_field_name("left") {
        match left_node.kind() {
            "identifier" => {
                let name = get_node_text(ctx, left_node);
                let qualname = build_qualname(ctx, node, &name);
                let start_pos = left_node.start_position();
                let end_line = node.end_position().row + 1;
                events.push(Event::DefineName {
                    node_id: generate_node_id(ctx.file_path, left_node),
                    name: name.clone(),
                    qualname: qualname.clone(),
                    node_type: "variable".to_string(),
                    file: ctx.file_path.to_string(),
                    line: start_pos.row + 1,
                    end_line,
                    column: start_pos.column,
                });
            }
            "pattern_list" | "tuple_pattern" => {
                let mut cursor = left_node.walk();
                for part in left_node.children(&mut cursor) {
                    if part.kind() == "identifier" {
                        let name = get_node_text(ctx, part);
                        let qualname = build_qualname(ctx, node, &name);
                        events.push(Event::define_name(
                            name,
                            qualname,
                            "variable",
                            part,
                            ctx.file_path,
                        ));
                    }
                }
            }
            _ => {}
        }
    }
}

fn emit_assert_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    let condition = node
        .child_by_field_name("condition")
        .map(|n| get_node_text(ctx, n))
        .unwrap_or_default();
    events.push(Event::control_block("assert", condition, node, ctx.file_path));
    events.push(Event::end_control_block("assert", node, ctx.file_path));
}

fn emit_annotated_assignment_post_event(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    let name_node = match node.child_by_field_name("name") {
        Some(n) if n.kind() == "identifier" => n,
        _ => return,
    };
    let value_node = match node.child_by_field_name("value") {
        Some(v) => v,
        None => return, // declaration-only annotation, no RHS
    };
    let name = get_node_text(ctx, name_node);
    let qualname = build_qualname(ctx, node, &name);
    let value = get_node_text(ctx, value_node);
    let value_type = classify_value_type(value_node.kind());
    events.push(Event::assignment(name, qualname, value, value_type, node, ctx.file_path));
}

fn emit_annotated_assignment_define_events(ctx: &ParseContext, node: Node, events: &mut Vec<Event>) {
    if let Some(name_node) = node.child_by_field_name("name") {
        if name_node.kind() == "identifier" {
            let name = get_node_text(ctx, name_node);
            let qualname = build_qualname(ctx, node, &name);
            events.push(Event::define_name(name, qualname, "variable", name_node, ctx.file_path));
        }
    }
}

pub fn derive_module_path(file_path: &str) -> Vec<String> {
    use std::path::Path;

    let path = Path::new(file_path);

    // Get the file stem (without .py extension)
    let stem = path
        .file_stem()
        .and_then(|s| s.to_str())
        .unwrap_or("__main__");

    // For __init__.py files, the module is the package itself (the parent directory).
    let is_init = stem == "__init__";

    // Walk up the directory tree collecting package names.
    // Include a directory only if it contains __init__.py (i.e., it is an actual Python package).
    let mut parts = Vec::new();
    let mut current = path.parent();

    while let Some(dir) = current {
        if let Some(dir_name) = dir.file_name().and_then(|s| s.to_str()) {
            // Stop at hidden directories (like .venv, .git)
            if dir_name.starts_with('.') {
                break;
            }

            // Stop at empty names (filesystem root)
            if dir_name.is_empty() {
                break;
            }

            // Stop at site-packages/dist-packages (installed packages boundary)
            if matches!(dir_name, "site-packages" | "dist-packages") {
                break;
            }

            // Stop if this directory is not a Python package (no __init__.py)
            if !dir.join("__init__.py").exists() {
                break;
            }

            // This is a Python package directory, include it
            parts.push(dir_name.to_string());
        } else {
            break;
        }

        current = dir.parent();
    }

    // Reverse since we collected from leaf to root
    parts.reverse();

    // Add the file stem (module name) — but NOT for __init__.py files,
    // since the package identity is the directory itself.
    if !is_init {
        parts.push(stem.to_string());
    }

    parts
}

fn stdlib_set() -> &'static HashSet<&'static str> {
    STDLIB_SET.get_or_init(|| STDLIB_MODULES.iter().copied().collect())
}

impl LanguageConfig for PythonConfig {
    /// Derive the logical module qualname from a Python file path.
    ///
    /// Delegates to `crate::python::derive_module_path` which handles
    /// `__init__.py` → package directory and walks up to the project root.
    fn derive_module_path(&self, file_path: &str, _project_root: &str) -> String {
        crate::python::derive_module_path(file_path).join(".")
    }

    /// Returns `true` for `__init__.py` files, which re-export the package
    /// namespace in Python projects.
    fn is_reexport_file(&self, file_path: &str) -> bool {
        file_path.ends_with("__init__.py")
    }

    /// Returns `true` if `module` is a Python standard library module.
    fn is_stdlib(&self, module: &str) -> bool {
        let top_level = module.split('.').next().unwrap_or(module);
        stdlib_set().contains(top_level)
    }

    /// Returns `true` if `module` is not a Python stdlib module.
    ///
    /// Note: distinguishing third-party from local requires access to the
    /// graph's known definitions, which is handled by `GraphBuilder::classify_module`.
    /// This method is a coarse filter only.
    fn is_third_party(&self, module: &str) -> bool {
        !self.is_stdlib(module)
    }

    fn extensions(&self) -> &[&str] {
        &[".py"]
    }
}

fn is_stdlib(&self, module: &str) -> bool {
    let top_level = module.split('.').next().unwrap_or(module);
    stdlib_set().contains(top_level)
}

fn clean_docstring(raw: &str) -> String {
    let inner = if (raw.starts_with("\"\"\"") && raw.ends_with("\"\"\"") && raw.len() >= 6)
        || (raw.starts_with("'''") && raw.ends_with("'''") && raw.len() >= 6)
    {
        &raw[3..raw.len() - 3]
    } else if (raw.starts_with('"') && raw.ends_with('"') && raw.len() >= 2)
        || (raw.starts_with('\'') && raw.ends_with('\'') && raw.len() >= 2)
    {
        &raw[1..raw.len() - 1]
    } else {
        raw
    };
    dedent(inner.trim_matches('\n'))
}

fn build_qualname(ctx: &ParseContext, node: Node, name: &str) -> String {
    let mut parts = Vec::new();

    // Add the current node's name first
    if name != "module" && !name.is_empty() {
        parts.push(name.to_string());
    }

    // Walk up the parent chain to build the qualified name
    let mut current = node.parent();
    while let Some(parent) = current {
        let parent_kind = parent.kind();

        // Only add names from scope-creating nodes (classes and functions)
        if is_scope_creating_node(parent_kind) {
            if let Some(parent_name_node) = parent.child_by_field_name("name") {
                let parent_name = ctx.source
                    [parent_name_node.start_byte()..parent_name_node.end_byte()]
                    .to_string();
                parts.insert(0, parent_name);
            }
        }

        current = parent.parent();
    }

    // Add module path if present
    if !ctx.module_path.is_empty() {
        let mut full_parts = ctx.module_path.clone();
        full_parts.extend(parts);
        return full_parts.join(".");
    }

    if parts.is_empty() {
        name.to_string()
    } else {
        parts.join(".")
    }
}

struct ParseContext<'a> {
    source: &'a str,
    file_path: &'a str,
    module_path: Vec<String>,
    is_init: bool,
}

use crate::events::Event;

/// Trait for subscribers that process events.
///
/// Subscribers receive events one at a time via `handle_event`, then
/// produce a final result via `finalize` when all events have been processed.
pub trait Subscriber: Send {
    /// Handle a single event. Returns an error if processing fails.
    fn handle_event(&mut self, event: &Event) -> Result<(), String>;

    /// Called when all events have been published. Returns the final result.
    fn finalize(&mut self) -> Result<SubscriberResult, String>;

    /// Get the name of this subscriber (for debugging/logging).
    #[allow(dead_code)]
    fn name(&self) -> &str;
}

/// Factory trait for creating fresh subscriber instances.
///
/// Factories are registered with the message bus and used to create new
/// subscriber instances for each `publish_events` call.
pub trait SubscriberFactory: Send + Sync {
    fn create(&self) -> Box<dyn Subscriber>;
}

/// Result from a subscriber after processing all events.
#[derive(Debug, Clone)]
pub struct SubscriberResult {
    pub subscriber_name: String,
    pub data: serde_json::Value,
}

/// Message bus that fans out events to multiple subscribers sequentially.
pub struct MessageBus {
    factories: Vec<Box<dyn SubscriberFactory>>,
}

impl MessageBus {
    pub fn new() -> Self {
        MessageBus {
            factories: Vec::new(),
        }
    }

    /// Register a subscriber factory.
    pub fn register<F: SubscriberFactory + 'static>(&mut self, factory: F) {
        self.factories.push(Box::new(factory));
    }

    /// Publish events to all subscribers sequentially.
    ///
    /// Creates fresh subscriber instances from factories, processes all events
    /// through each subscriber in order, and collects results.
    /// Parallelism is handled at the file level via `open_files_bulk`.
    pub fn publish_events(&mut self, events: Vec<Event>) -> Result<Vec<SubscriberResult>, String> {
        if self.factories.is_empty() {
            return Ok(Vec::new());
        }

        let mut subscribers: Vec<_> = self.factories.iter().map(|f| f.create()).collect();

        for event in &events {
            for subscriber in &mut subscribers {
                subscriber.handle_event(event)?;
            }
        }

        subscribers.into_iter().map(|mut s| s.finalize()).collect()
    }
}

impl Default for MessageBus {
    fn default() -> Self {
        Self::new()
    }
}

pub struct SubscriberResult {
    pub subscriber_name: String,
    pub data: serde_json::Value,
}

pub trait SubscriberFactory: Send + Sync {
    fn create(&self) -> Box<dyn Subscriber>;
}

pub trait Subscriber: Send {
    /// Handle a single event. Returns an error if processing fails.
    fn handle_event(&mut self, event: &Event) -> Result<(), String>;

    /// Called when all events have been published. Returns the final result.
    fn finalize(&mut self) -> Result<SubscriberResult, String>;

    /// Get the name of this subscriber (for debugging/logging).
    #[allow(dead_code)]
    fn name(&self) -> &str;
}

impl Default for MessageBus {
    fn default() -> Self {
        Self::new()
    }
}

pub fn register<F: SubscriberFactory + 'static>(&mut self, factory: F) {
    self.factories.push(Box::new(factory));
}

pub fn publish_events(&mut self, events: Vec<Event>) -> Result<Vec<SubscriberResult>, String> {
    if self.factories.is_empty() {
        return Ok(Vec::new());
    }

    let mut subscribers: Vec<_> = self.factories.iter().map(|f| f.create()).collect();

    for event in &events {
        for subscriber in &mut subscribers {
            subscriber.handle_event(event)?;
        }
    }

    subscribers.into_iter().map(|mut s| s.finalize()).collect()
}

pub fn new() -> Self {
    MessageBus {
        factories: Vec::new(),
    }
}

//! JavaScript/TypeScript/JSX/TSX tree-sitter walker.
//!
//! All four JS-family variants share this single walker. Grammar-specific node kinds
//! (e.g. TypeScript `interface_declaration`) are only emitted when the `JsLang`
//! flag indicates a TypeScript variant; JS grammars never produce those node kinds
//! anyway, so the match arms are safe for all variants.
//!
//! Event model mirrors the Python walker:
//! - `EnterScope`/`ExitScope` for module, function, class, interface
//! - `DefineName` for variables and imports
//! - `ImportStatement` for ES module imports
//! - `CallExpression` for function/constructor calls

pub mod config;

use crate::events::{Event, ScopeType};
use tree_sitter::{Node, Tree};

// ============================================================================
// Language variant
// ============================================================================

/// Identifies which JS-family grammar was used to parse the file.
#[derive(Clone, Copy, PartialEq, Debug)]
pub enum JsLang {
    JavaScript,
    TypeScript,
    Tsx,
}

// ============================================================================
// Parse context
// ============================================================================

/// Project-level information resolved once per file and cached in `Ctx`.
struct ProjectInfo {
    /// Name of the directory containing `package.json` (e.g. `"frontend"`).
    root_name: String,
    /// Absolute path string of that directory (e.g. `"/path/to/frontend"`).
    root_path: String,
    /// Tsconfig path alias mappings: `(alias_prefix, target_dir)`.
    /// e.g. `("@app", "src/app")`.
    aliases: Vec<(String, String)>,
}

struct Ctx<'a> {
    source: &'a str,
    file_path: &'a str,
    /// Stack of (short name, qualname) for the current scope chain.
    scope_stack: Vec<(String, String)>,
    /// Project root info, used for module path derivation and import resolution.
    project_info: Option<ProjectInfo>,
}

impl<'a> Ctx<'a> {
    fn current_qualname(&self) -> String {
        self.scope_stack
            .last()
            .map(|(_, qn)| qn.as_str())
            .unwrap_or("")
            .to_string()
    }

    fn build_qualname(&self, name: &str) -> String {
        let parent = self.current_qualname();
        if parent.is_empty() {
            name.to_string()
        } else {
            format!("{}.{}", parent, name)
        }
    }

    fn get_text(&self, node: Node) -> &'a str {
        &self.source[node.start_byte()..node.end_byte()]
    }
}

// ============================================================================
// JSDoc extraction helpers
// ============================================================================

/// Extract a JSDoc comment (`/** ... */`) immediately preceding `node`.
/// Returns the cleaned comment text, or `None` if no JSDoc is present.
fn extract_jsdoc(node: Node, source: &str) -> Option<String> {
    let prev = node.prev_named_sibling()?;
    if prev.kind() != "comment" {
        return None;
    }
    let text = &source[prev.byte_range()];
    if !text.starts_with("/**") {
        return None;
    }
    Some(clean_jsdoc(text))
}

/// Extract a file-level JSDoc from the root node's first named child comment.
fn extract_module_jsdoc(root: Node, source: &str) -> Option<String> {
    let mut cursor = root.walk();
    for child in root.children(&mut cursor) {
        if child.kind() == "comment" {
            let text = &source[child.byte_range()];
            if text.starts_with("/**") {
                return Some(clean_jsdoc(text));
            }
            // Non-JSDoc comment at top — skip
            continue;
        }
        break;
    }
    None
}

/// Strip `/** ... */` delimiters and leading `* ` from each line.
fn clean_jsdoc(raw: &str) -> String {
    let inner = raw
        .trim_start_matches("/**")
        .trim_end_matches("*/")
        .trim_matches('\n');
    let lines: Vec<&str> = inner
        .lines()
        .map(|l| {
            let t = l.trim();
            t.strip_prefix("* ").or_else(|| t.strip_prefix('*')).unwrap_or(t)
        })
        .collect();
    // Drop leading/trailing blank lines
    let start = lines.iter().position(|l| !l.trim().is_empty()).unwrap_or(0);
    let end = lines.iter().rposition(|l| !l.trim().is_empty()).map(|i| i + 1).unwrap_or(lines.len());
    lines[start..end].join("\n")
}

// ============================================================================
// Module path derivation
// ============================================================================

/// Derive a dotted module qualname from a JS/TS file path.
///
/// Walks up from the file to find `package.json` (the project root), then
/// builds a path as `project_name.relative.path.stem`.
/// e.g. `frontend/src/app/App.tsx` → `["frontend", "src", "app", "App"]`.
///
/// `index.*` files take the name of their parent directory — the stem is
/// omitted so the module represents the directory itself.
pub fn derive_module_path(file_path: &str) -> Vec<String> {
    use std::path::{Component, Path};

    let path = Path::new(file_path);
    let stem = path
        .file_stem()
        .and_then(|s| s.to_str())
        .unwrap_or("index");

    // Use the project root as anchor when available.
    if let Some(info) = find_project_info(file_path) {
        let prefix = format!("{}/", info.root_path);
        if file_path.starts_with(&prefix) {
            let rest = &file_path[prefix.len()..]; // e.g. "src/app/App.tsx"
            if !rest.starts_with("node_modules") {
                let rest_path = Path::new(rest);
                let rest_stem = rest_path
                    .file_stem()
                    .and_then(|s| s.to_str())
                    .unwrap_or(stem);
                let rest_dir = rest_path
                    .parent()
                    .and_then(|p| p.to_str())
                    .unwrap_or("");

                let mut parts = vec![info.root_name];
                if !rest_dir.is_empty() && rest_dir != "." {
                    for seg in rest_dir.split('/') {
                        if !seg.is_empty() {
                            parts.push(seg.to_string());
                        }
                    }
                }
                if rest_stem != "index" {
                    parts.push(rest_stem.to_string());
                }
                return parts;
            }
        }
    }

    // Fallback: collect normal directory components, strip src root.
    let dir_parts: Vec<String> = path
        .parent()
        .map(|p| {
            p.components()
                .filter_map(|c| match c {
                    Component::Normal(n) => n.to_str().map(String::from),
                    _ => None,
                })
                .collect()
        })
        .unwrap_or_default();

    let stops = ["node_modules", ".git", ".venv"];
    let trim_at = dir_parts
        .iter()
        .position(|p| stops.contains(&p.as_str()))
        .unwrap_or(dir_parts.len());
    let dir_parts = &dir_parts[..trim_at];

    // "app" excluded — it is a valid subdirectory name, not a source root.
    let src_roots = ["src", "lib", "packages", "source"];
    let start = dir_parts
        .iter()
        .rposition(|p| src_roots.contains(&p.as_str()))
        .map(|i| i + 1)
        .unwrap_or_else(|| {
            if dir_parts.is_empty() { 0 } else { dir_parts.len() - 1 }
        });

    let mut parts: Vec<String> = dir_parts[start..].to_vec();
    if stem != "index" {
        parts.push(stem.to_string());
    }
    if parts.is_empty() {
        parts.push(stem.to_string());
    }
    parts
}

/// Walk up from `file_path` to find the JS project root (directory containing
/// `package.json` or `tsconfig.json`) and collect tsconfig path aliases.
///
/// Stops immediately if `node_modules` is encountered so dependency files are
/// not attributed to a parent project.
fn find_project_info(file_path: &str) -> Option<ProjectInfo> {
    use std::path::Path;

    let mut dir = Path::new(file_path).parent()?;
    loop {
        if dir.file_name().and_then(|n| n.to_str()) == Some("node_modules") {
            return None;
        }

        let has_package_json = dir.join("package.json").exists();
        let tsconfig_path = dir.join("tsconfig.json");
        let has_tsconfig = tsconfig_path.exists();

        if has_package_json || has_tsconfig {
            let root_name = dir.file_name()?.to_str()?.to_string();
            let root_path = dir.to_str()?.to_string();

            let aliases = if has_tsconfig {
                read_tsconfig_aliases_from(&tsconfig_path).unwrap_or_default()
            } else {
                vec![]
            };

            return Some(ProjectInfo { root_name, root_path, aliases });
        }

        dir = dir.parent()?;
    }
}

/// Parse `compilerOptions.paths` from a `tsconfig.json` file.
///
/// Returns `(alias_prefix, target_dir)` pairs, e.g. `("@app", "src/app")`.
/// Single-character aliases like `@` are skipped (too generic).
///
/// Targets that start with `../` are resolved to absolute filesystem paths using
/// the tsconfig's directory as the base. This allows cross-package alias targets
/// (e.g. `"@my-company/*": ["../lib/*"]` in a monorepo) to resolve correctly
/// in `normalize_import` via `derive_module_path`.
fn read_tsconfig_aliases_from(path: &std::path::Path) -> Option<Vec<(String, String)>> {
    use std::path::{Component, PathBuf};

    let content = std::fs::read_to_string(path).ok()?;
    let json: serde_json::Value = serde_json::from_str(&content).ok()?;
    let paths_obj = json.get("compilerOptions")?.get("paths")?.as_object()?;

    let tsconfig_dir = path.parent().unwrap_or(std::path::Path::new("."));

    let mut aliases = Vec::new();
    for (alias, targets) in paths_obj {
        let alias_prefix = alias.strip_suffix("/*").unwrap_or(alias.as_str());
        if alias_prefix.is_empty() || alias_prefix == "@" {
            continue;
        }
        if let Some(target_str) = targets
            .as_array()
            .and_then(|a| a.first())
            .and_then(|v| v.as_str())
        {
            // Strip glob suffix and trailing slashes.
            let without_glob = target_str
                .strip_suffix("/*")
                .unwrap_or(target_str)
                .trim_end_matches('/');
            // Strip file extensions from file-targeted aliases like "./src/store.ts" → "src/store"
            let without_ext = [".ts", ".tsx", ".js", ".jsx", ".mjs"]
                .iter()
                .fold(without_glob.to_string(), |s, ext| {
                    s.strip_suffix(ext).unwrap_or(&s).to_string()
                });

            let target_dir = if without_ext.starts_with("../") || without_ext == ".." {
                // Parent-relative target — resolve to absolute path so that
                // normalize_import can use derive_module_path on it.
                let abs = tsconfig_dir.join(&without_ext);
                let normalized: PathBuf = abs.components().fold(PathBuf::new(), |mut acc, c| {
                    match c {
                        Component::ParentDir => { acc.pop(); }
                        Component::CurDir => {}
                        _ => acc.push(c),
                    }
                    acc
                });
                normalized.to_string_lossy().to_string()
            } else {
                // In-project target — strip leading `./` and store as relative.
                without_ext.strip_prefix("./").unwrap_or(&without_ext).to_string()
            };

            aliases.push((alias_prefix.to_string(), target_dir));
        }
    }
    Some(aliases)
}

/// Resolve a JS import string to a canonical dotted module qualname.
///
/// Relative imports (`./foo`, `../bar/baz`) are resolved against the importing
/// file's path and then converted to the same dotted form as `derive_module_path`:
///   `../domains/cfg`  (from `frontend/src/app/store.ts`)
///     →  `frontend.src.domains.cfg`
///
/// For `@`-prefixed imports that match a known tsconfig alias, the alias is
/// expanded to the real directory path and prefixed with the project root name:
///   `@app/store`  →  `frontend.src.app.store`
///   `@ui/components/SearchBar`  →  `frontend.src.ui.components.SearchBar`
///
/// Unrecognised `@`-prefixed imports (scoped npm packages) fall through with
/// slashes replaced by dots so their IDs are consistent:
///   `@tanstack/react-query`  →  `@tanstack.react-query`
fn normalize_import(module: &str, file_path: &str, info: &Option<ProjectInfo>) -> String {
    // Relative import — resolve against the importing file's directory.
    if module.starts_with("./") || module.starts_with("../") {
        use std::path::Path;
        // Skip imports that point to non-source files (e.g. .css, .svg, .png).
        if let Some(ext) = Path::new(module).extension() {
            let ext = ext.to_string_lossy();
            if !matches!(ext.as_ref(), "ts" | "tsx" | "js" | "jsx" | "mjs" | "cjs" | "py") {
                return String::new();
            }
        }
        if let Some(dir) = Path::new(file_path).parent() {
            // Build the resolved filesystem path (without extension).
            let resolved = dir.join(module);
            // Normalise away `..` and `.` components.
            let canonical: std::path::PathBuf = resolved
                .components()
                .fold(std::path::PathBuf::new(), |mut acc, c| {
                    use std::path::Component;
                    match c {
                        Component::ParentDir => { acc.pop(); }
                        Component::CurDir => {}
                        _ => acc.push(c),
                    }
                    acc
                });
            // derive_module_path expects a file path string; give it a fake
            // extension so the stem logic works correctly for non-index files.
            let as_str = canonical.to_string_lossy();
            return derive_module_path(&format!("{}.ts", as_str)).join(".");
        }
    }

    // Try alias lookup for any non-relative import (not just `@`-prefixed).
    if let Some(info) = info {
        for (alias_prefix, target_dir) in &info.aliases {
            let alias_slash = format!("{}/", alias_prefix);
            let rest = if module.starts_with(&alias_slash) {
                &module[alias_slash.len()..] // "store" from "@app/store"
            } else if module == alias_prefix.as_str() {
                "" // exact alias with no trailing path
            } else {
                continue;
            };

            if target_dir.starts_with('/') {
                // Absolute path target (from a `../`-prefixed tsconfig entry).
                // Build a fake file path and use derive_module_path for resolution
                // so the result is consistent with how real files are named.
                let mut fake_path = target_dir.clone();
                if !rest.is_empty() {
                    fake_path.push('/');
                    fake_path.push_str(rest);
                }
                let parts = derive_module_path(&format!("{}.ts", fake_path));
                return parts.join(".");
            } else {
                // Relative target — build dotted path from root_name + target segments.
                let mut parts = vec![info.root_name.clone()];
                for seg in target_dir.split('/') {
                    if !seg.is_empty() {
                        parts.push(seg.to_string());
                    }
                }
                for seg in rest.split('/') {
                    if !seg.is_empty() {
                        parts.push(seg.to_string());
                    }
                }
                return parts.join(".");
            }
        }
    }

    if !module.starts_with('@') {
        return module.to_string();
    }

    // No alias matched — scoped npm package; normalise slashes for consistency.
    module.replace('/', ".")
}

// ============================================================================
// Public parse entry point
// ============================================================================

pub fn parse(source: &str, tree: &Option<Tree>, file_path: &str, _lang: JsLang) -> Vec<Event> {
    let mut events = Vec::new();

    // Source line events (for CodeSnippet subscriber)
    for (i, line) in source.lines().enumerate() {
        events.push(Event::SourceLine {
            file: file_path.to_string(),
            line_number: i + 1,
            text: line.to_string(),
        });
    }

    let Some(tree) = tree else {
        return events;
    };

    let root = tree.root_node();
    let project_info = find_project_info(file_path);
    let module_parts = derive_module_path(file_path);
    let module_name = module_parts.last().cloned().unwrap_or_else(|| "module".to_string());
    let module_qualname = module_parts.join(".");

    let mut ctx = Ctx {
        source,
        file_path,
        scope_stack: vec![(module_name.clone(), module_qualname.clone())],
        project_info,
    };

    // Enter module scope.
    let module_docstring = extract_module_jsdoc(root, source);
    events.push(Event::enter_scope_with_docstring(
        ScopeType::Module,
        module_name.clone(),
        module_qualname.clone(),
        vec![],
        vec![],
        module_docstring,
        root,
        file_path,
    ));

    let mut cursor = root.walk();
    for child in root.children(&mut cursor) {
        walk_node(&mut ctx, child, &mut events);
    }

    ctx.scope_stack.pop();
    events.push(Event::exit_scope(
        ScopeType::Module,
        module_name,
        module_qualname,
        root,
        file_path,
    ));

    events
}

// ============================================================================
// Tree walker
// ============================================================================

/// Emit a UseName event if `node` is an identifier in a USE context (not a
/// definition site, import binding, member-expression property, etc.).
///
/// Filters mirror Python's `emit_identifier_events` logic adapted for the JS/TS AST.
fn emit_identifier_use(ctx: &Ctx, node: Node, events: &mut Vec<Event>) {
    if let Some(parent) = node.parent() {
        match parent.kind() {
            // Skip: declarator name (const FOO = ...)
            "variable_declarator" => {
                if parent.child_by_field_name("name").is_some_and(|n| n.id() == node.id()) {
                    return;
                }
            }
            // Skip: function / generator declaration name
            "function_declaration" | "generator_function_declaration"
            | "function" | "generator_function" => {
                if parent.child_by_field_name("name").is_some_and(|n| n.id() == node.id()) {
                    return;
                }
            }
            // Skip: class declaration name
            "class_declaration" | "class" | "abstract_class_declaration" => {
                if parent.child_by_field_name("name").is_some_and(|n| n.id() == node.id()) {
                    return;
                }
            }
            // Skip: method / property signature name
            "method_definition" | "method_signature" | "property_signature"
            | "public_field_definition" => {
                if parent.child_by_field_name("name").is_some_and(|n| n.id() == node.id()) {
                    return;
                }
            }
            // Skip: all import binding positions
            "import_clause" | "import_specifier" | "namespace_import" => return,
            // Skip: export specifier  (export { X })
            "export_specifier" => return,
            // Skip: labeled statement label
            "labeled_statement" => {
                if parent.child_by_field_name("label").is_some_and(|n| n.id() == node.id()) {
                    return;
                }
            }
            // Skip: member-expression property  (obj.PROP — not LEGB-resolvable)
            // The object part (obj) is NOT skipped and will fire separately.
            "member_expression" => {
                if parent.child_by_field_name("property").is_some_and(|n| n.id() == node.id()) {
                    return;
                }
            }
            // Skip: object literal key  { key: value }
            "pair" => {
                if parent.child_by_field_name("key").is_some_and(|n| n.id() == node.id()) {
                    return;
                }
            }
            // Skip: TypeScript type parameter declaration
            "type_parameter" => return,
            // Skip: TypeScript parameter names — the `name` field is a definition, not a use.
            // The `type` field IS walked (by the required_parameter arm in walk_node).
            "required_parameter" | "optional_parameter" => {
                if parent.child_by_field_name("name").is_some_and(|n| n.id() == node.id()) {
                    return;
                }
            }
            _ => {}
        }
    }
    let name = ctx.get_text(node);
    if name.is_empty()
        || name == "undefined"
        || name == "null"
        || name == "this"
        || name == "super"
    {
        return;
    }
    events.push(Event::use_name(name.to_string(), node, ctx.file_path));
}

/// Emit a Decorator event for a TypeScript/JS decorator node (`@expr`).
///
/// Handles three forms:
/// - `@Identifier`          → Decorator(name, is_call=false)
/// - `@member.expr`         → Decorator(member.expr, is_call=false)
/// - `@call_expression(…)`  → Decorator(callee, is_call=true, args)
fn emit_decorator(ctx: &mut Ctx, node: Node, events: &mut Vec<Event>) {
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        match child.kind() {
            "identifier" => {
                let name = ctx.get_text(child).to_string();
                events.push(Event::decorator(name, false, vec![], node, ctx.file_path));
            }
            "member_expression" => {
                let name = ctx.get_text(child).to_string();
                events.push(Event::decorator(name, false, vec![], node, ctx.file_path));
            }
            "call_expression" => {
                let callee = child
                    .child_by_field_name("function")
                    .map(|n| ctx.get_text(n).to_string())
                    .unwrap_or_default();
                let mut args = Vec::new();
                if let Some(args_node) = child.child_by_field_name("arguments") {
                    let mut c = args_node.walk();
                    for arg in args_node.children(&mut c) {
                        match arg.kind() {
                            "(" | ")" | "," => {}
                            _ if arg.is_named() => {
                                let text = ctx.get_text(arg).to_string();
                                if !text.is_empty() {
                                    args.push(text);
                                }
                            }
                            _ => {}
                        }
                    }
                }
                events.push(Event::decorator(callee, true, args, node, ctx.file_path));
            }
            _ => {}
        }
    }
}

fn walk_node(ctx: &mut Ctx, node: Node, events: &mut Vec<Event>) {
    match node.kind() {
        "function_declaration" | "generator_function_declaration" => {
            emit_function(ctx, node, events);
        }
        "class_declaration" | "abstract_class_declaration" => {
            emit_class(ctx, node, events);
        }
        "lexical_declaration" | "variable_declaration" => {
            emit_variable_declaration(ctx, node, events);
        }
        "import_statement" => {
            emit_import(ctx, node, events);
        }
        // POST-ORDER: recurse arguments first so inner call events fire before the
        // outer call — matches Python's emission order for correct PDG sequencing.
        "call_expression" | "new_expression" => {
            if let Some(args) = node.child_by_field_name("arguments") {
                let mut cursor = args.walk();
                for child in args.children(&mut cursor) {
                    walk_node(ctx, child, events);
                }
            }
            emit_call(ctx, node, events);
        }
        "export_statement" => {
            emit_export(ctx, node, events);
        }
        // ── Control flow ────────────────────────────────────────────────────────
        "if_statement" => {
            let condition = node
                .child_by_field_name("condition")
                .map(|c| ctx.get_text(c).to_string())
                .unwrap_or_default();
            events.push(Event::control_block("if", condition, node, ctx.file_path));
            if let Some(c) = node.child_by_field_name("condition") {
                walk_node(ctx, c, events);
            }
            if let Some(c) = node.child_by_field_name("consequence") {
                walk_node(ctx, c, events);
            }
            if let Some(c) = node.child_by_field_name("alternative") {
                walk_node(ctx, c, events);
            }
            events.push(Event::end_control_block("if", node, ctx.file_path));
        }
        "else_clause" => {
            events.push(Event::else_block("else", String::new(), node, ctx.file_path));
            let mut cursor = node.walk();
            for child in node.children(&mut cursor) {
                walk_node(ctx, child, events);
            }
            events.push(Event::end_control_block("else", node, ctx.file_path));
        }
        "while_statement" => {
            let condition = node
                .child_by_field_name("condition")
                .map(|c| ctx.get_text(c).to_string())
                .unwrap_or_default();
            events.push(Event::control_block("while", condition, node, ctx.file_path));
            let mut cursor = node.walk();
            for child in node.children(&mut cursor) {
                walk_node(ctx, child, events);
            }
            events.push(Event::end_control_block("while", node, ctx.file_path));
        }
        "do_statement" => {
            let condition = node
                .child_by_field_name("condition")
                .map(|c| ctx.get_text(c).to_string())
                .unwrap_or_default();
            events.push(Event::control_block("do-while", condition, node, ctx.file_path));
            let mut cursor = node.walk();
            for child in node.children(&mut cursor) {
                walk_node(ctx, child, events);
            }
            events.push(Event::end_control_block("do-while", node, ctx.file_path));
        }
        "try_statement" => {
            events.push(Event::control_block("try", String::new(), node, ctx.file_path));
            let mut cursor = node.walk();
            for child in node.children(&mut cursor) {
                walk_node(ctx, child, events);
            }
            events.push(Event::end_control_block("try", node, ctx.file_path));
        }
        "finally_clause" => {
            events.push(Event::else_block("finally", String::new(), node, ctx.file_path));
            let mut cursor = node.walk();
            for child in node.children(&mut cursor) {
                walk_node(ctx, child, events);
            }
            events.push(Event::end_control_block("finally", node, ctx.file_path));
        }
        "switch_statement" => {
            let value = node
                .child_by_field_name("value")
                .map(|v| ctx.get_text(v).to_string())
                .unwrap_or_default();
            events.push(Event::control_block("switch", value, node, ctx.file_path));
            if let Some(body) = node.child_by_field_name("body") {
                let mut cursor = body.walk();
                for child in body.children(&mut cursor) {
                    walk_node(ctx, child, events);
                }
            }
            events.push(Event::end_control_block("switch", node, ctx.file_path));
        }
        "switch_case" => {
            let value = node
                .child_by_field_name("value")
                .map(|v| ctx.get_text(v).to_string())
                .unwrap_or_default();
            events.push(Event::else_block("case", value, node, ctx.file_path));
            let mut cursor = node.walk();
            for child in node.children(&mut cursor) {
                walk_node(ctx, child, events);
            }
            events.push(Event::end_control_block("case", node, ctx.file_path));
        }
        "switch_default" => {
            events.push(Event::else_block("default", String::new(), node, ctx.file_path));
            let mut cursor = node.walk();
            for child in node.children(&mut cursor) {
                walk_node(ctx, child, events);
            }
            events.push(Event::end_control_block("default", node, ctx.file_path));
        }
        // ── Early exits ─────────────────────────────────────────────────────────
        "return_statement" => {
            let mut cursor = node.walk();
            let value_node = node
                .children(&mut cursor)
                .find(|c| c.kind() != "return" && c.is_named());
            let (value, value_type) = match value_node {
                Some(v) => (ctx.get_text(v).to_string(), js_classify_value_type(v.kind())),
                None => (String::new(), "none"),
            };
            events.push(Event::return_stmt(value, value_type, node, ctx.file_path));
            // Still recurse to capture calls/uses in the return expression.
            let mut cursor2 = node.walk();
            for child in node.children(&mut cursor2) {
                if child.kind() != "return" {
                    walk_node(ctx, child, events);
                }
            }
        }
        "throw_statement" => {
            let mut cursor = node.walk();
            let exc = node
                .children(&mut cursor)
                .find(|c| c.kind() != "throw" && c.is_named())
                .map(|n| ctx.get_text(n).to_string())
                .unwrap_or_default();
            events.push(Event::raise_statement(exc, node, ctx.file_path));
            let mut cursor2 = node.walk();
            for child in node.children(&mut cursor2) {
                if child.kind() != "throw" {
                    walk_node(ctx, child, events);
                }
            }
        }
        "break_statement" => {
            events.push(Event::break_statement(node, ctx.file_path));
        }
        "continue_statement" => {
            events.push(Event::continue_statement(node, ctx.file_path));
        }
        // ── Literals ────────────────────────────────────────────────────────────
        "number" => {
            events.push(Event::literal(
                ctx.get_text(node).to_string(),
                "number",
                node,
                ctx.file_path,
            ));
        }
        "string" | "template_string" => {
            events.push(Event::literal(
                ctx.get_text(node).to_string(),
                "string",
                node,
                ctx.file_path,
            ));
        }
        "true" | "false" => {
            events.push(Event::literal(
                ctx.get_text(node).to_string(),
                "boolean",
                node,
                ctx.file_path,
            ));
        }
        "null" => {
            events.push(Event::literal("null".to_string(), "null", node, ctx.file_path));
        }
        // ── Augmented assignment (+=, -=, etc.) ─────────────────────────────────
        // LHS is both read and written; emit UseName for the read, then Assignment.
        "augmented_assignment_expression" => {
            if let Some(left) = node.child_by_field_name("left") {
                if left.kind() == "identifier" {
                    let name = ctx.get_text(left).to_string();
                    events.push(Event::use_name(name, left, ctx.file_path));
                }
            }
            if let Some(right) = node.child_by_field_name("right") {
                walk_node(ctx, right, events);
            }
            if let (Some(left), Some(right)) = (
                node.child_by_field_name("left"),
                node.child_by_field_name("right"),
            ) {
                if left.kind() == "identifier" {
                    let name = ctx.get_text(left).to_string();
                    let qualname = ctx.build_qualname(&name);
                    let value = ctx.get_text(right).to_string();
                    let value_type = js_classify_value_type(right.kind());
                    events.push(Event::assignment(
                        name,
                        qualname,
                        value,
                        value_type,
                        node,
                        ctx.file_path,
                    ));
                }
            }
        }
        // ── for...of / for...in ─────────────────────────────────────────────────
        "for_in_statement" | "for_of_statement" => {
            emit_for_loop(ctx, node, events);
        }
        // ── catch clause ────────────────────────────────────────────────────────
        "catch_clause" => {
            emit_catch_clause(ctx, node, events);
        }
        // ── TypeScript-specific ─────────────────────────────────────────────────
        "interface_declaration" => {
            emit_interface(ctx, node, events);
        }
        "type_alias_declaration" => {
            emit_type_alias(ctx, node, events);
        }
        "enum_declaration" => {
            emit_enum(ctx, node, events);
        }
        // ── Member expressions (obj.prop) — emit AttributeAccess + recurse object only
        // The property is a member name, not a scope-resolvable reference; emit_identifier_use
        // already filters it out when walking via the default arm, but with this explicit arm
        // we skip the default recursion entirely and only walk `object`.
        "member_expression" => {
            let obj = node
                .child_by_field_name("object")
                .map(|n| ctx.get_text(n).to_string())
                .unwrap_or_default();
            let prop = node
                .child_by_field_name("property")
                .map(|n| ctx.get_text(n).to_string())
                .unwrap_or_default();
            events.push(Event::attribute_access(obj, prop, node, ctx.file_path));
            // Recurse into object only — property is not a scope name
            if let Some(obj_node) = node.child_by_field_name("object") {
                walk_node(ctx, obj_node, events);
            }
        }
        // ── Decorators (@foo, @foo.bar, @foo()) ─────────────────────────────────
        "decorator" => {
            emit_decorator(ctx, node, events);
        }
        // ── Await expression — pass through to value ─────────────────────────────
        "await_expression" => {
            if let Some(val) = node.child_by_field_name("value") {
                walk_node(ctx, val, events);
            }
        }
        // ── TypeScript typed parameters — walk type annotation only ──────────────
        // The parameter name is a definition (excluded in emit_identifier_use), so
        // we only recurse into the type child to capture type reference UseName events.
        "required_parameter" | "optional_parameter" => {
            if let Some(type_node) = node.child_by_field_name("type") {
                walk_node(ctx, type_node, events);
            }
        }
        // ── Identifier uses ─────────────────────────────────────────────────────
        // type_identifier covers TypeScript type references (const x: SomeType).
        // jsx_identifier covers JSX element names (<MyComponent />).
        "identifier" | "type_identifier" | "jsx_identifier" => {
            emit_identifier_use(ctx, node, events);
        }
        _ => {
            let mut cursor = node.walk();
            for child in node.children(&mut cursor) {
                walk_node(ctx, child, events);
            }
        }
    }
}

// ============================================================================
// Scope emitters
// ============================================================================

fn emit_function(ctx: &mut Ctx, node: Node, events: &mut Vec<Event>) {
    let name = match node.child_by_field_name("name") {
        Some(n) => ctx.get_text(n).to_string(),
        None => return, // anonymous; handled by emit_variable_declarator
    };

    let qualname = ctx.build_qualname(&name);

    let params = node
        .child_by_field_name("parameters")
        .map(|p| collect_params(ctx, p))
        .unwrap_or_default();

    let docstring = extract_jsdoc(node, ctx.source);
    events.push(Event::define_name(
        name.clone(),
        qualname.clone(),
        "function",
        node,
        ctx.file_path,
    ));
    events.push(Event::enter_scope_with_docstring(
        ScopeType::Function,
        name.clone(),
        qualname.clone(),
        params,
        vec![],
        docstring,
        node,
        ctx.file_path,
    ));

    ctx.scope_stack.push((name.clone(), qualname.clone()));

    // Walk TypeScript typed parameter annotations and return type so that type
    // references (e.g. `SomeType` in `fn f(x: SomeType): ReturnType`) emit UseName.
    if let Some(params) = node.child_by_field_name("parameters") {
        let mut cursor = params.walk();
        for child in params.children(&mut cursor) {
            if matches!(child.kind(), "required_parameter" | "optional_parameter") {
                walk_node(ctx, child, events);
            }
        }
    }
    if let Some(rt) = node.child_by_field_name("return_type") {
        walk_node(ctx, rt, events);
    }

    if let Some(body) = node.child_by_field_name("body") {
        let mut cursor = body.walk();
        for child in body.children(&mut cursor) {
            walk_node(ctx, child, events);
        }
    }

    ctx.scope_stack.pop();
    events.push(Event::exit_scope(
        ScopeType::Function,
        name,
        qualname,
        node,
        ctx.file_path,
    ));
}

fn emit_class(ctx: &mut Ctx, node: Node, events: &mut Vec<Event>) {
    let name = match node.child_by_field_name("name") {
        Some(n) => ctx.get_text(n).to_string(),
        None => return,
    };

    let qualname = ctx.build_qualname(&name);

    let bases = node
        .child_by_field_name("superclass")
        .map(|n| vec![ctx.get_text(n).to_string()])
        .unwrap_or_default();

    let docstring = extract_jsdoc(node, ctx.source);
    events.push(Event::define_name(
        name.clone(),
        qualname.clone(),
        "class",
        node,
        ctx.file_path,
    ));
    events.push(Event::enter_scope_with_docstring(
        ScopeType::Class,
        name.clone(),
        qualname.clone(),
        vec![],
        bases,
        docstring,
        node,
        ctx.file_path,
    ));

    ctx.scope_stack.push((name.clone(), qualname.clone()));

    if let Some(body) = node.child_by_field_name("body") {
        let mut cursor = body.walk();
        for child in body.children(&mut cursor) {
            match child.kind() {
                "method_definition" => emit_method(ctx, child, events),
                "public_field_definition" | "field_definition" => {
                    emit_class_field(ctx, child, events);
                }
                _ => {}
            }
        }
    }

    ctx.scope_stack.pop();
    events.push(Event::exit_scope(
        ScopeType::Class,
        name,
        qualname,
        node,
        ctx.file_path,
    ));
}

fn emit_method(ctx: &mut Ctx, node: Node, events: &mut Vec<Event>) {
    let name = match node.child_by_field_name("name") {
        Some(n) => ctx.get_text(n).to_string(),
        None => return,
    };

    let qualname = ctx.build_qualname(&name);

    let params = node
        .child_by_field_name("parameters")
        .map(|p| collect_params(ctx, p))
        .unwrap_or_default();

    let docstring = extract_jsdoc(node, ctx.source);
    events.push(Event::define_name(
        name.clone(),
        qualname.clone(),
        "function",
        node,
        ctx.file_path,
    ));
    events.push(Event::enter_scope_with_docstring(
        ScopeType::Function,
        name.clone(),
        qualname.clone(),
        params,
        vec![],
        docstring,
        node,
        ctx.file_path,
    ));

    ctx.scope_stack.push((name.clone(), qualname.clone()));

    // Walk TypeScript typed parameter annotations and return type
    if let Some(params) = node.child_by_field_name("parameters") {
        let mut cursor = params.walk();
        for child in params.children(&mut cursor) {
            if matches!(child.kind(), "required_parameter" | "optional_parameter") {
                walk_node(ctx, child, events);
            }
        }
    }
    if let Some(rt) = node.child_by_field_name("return_type") {
        walk_node(ctx, rt, events);
    }

    if let Some(body) = node.child_by_field_name("body") {
        let mut cursor = body.walk();
        for child in body.children(&mut cursor) {
            walk_node(ctx, child, events);
        }
    }

    ctx.scope_stack.pop();
    events.push(Event::exit_scope(
        ScopeType::Function,
        name,
        qualname,
        node,
        ctx.file_path,
    ));
}

fn emit_class_field(ctx: &mut Ctx, node: Node, events: &mut Vec<Event>) {
    if let Some(name_node) = node.child_by_field_name("name") {
        let name = ctx.get_text(name_node).to_string();
        let qualname = ctx.build_qualname(&name);
        events.push(Event::define_name(name, qualname, "variable", node, ctx.file_path));
    }
}

fn emit_interface(ctx: &mut Ctx, node: Node, events: &mut Vec<Event>) {
    let name = match node.child_by_field_name("name") {
        Some(n) => ctx.get_text(n).to_string(),
        None => return,
    };

    let qualname = ctx.build_qualname(&name);

    // Collect base interfaces from `extends` clause
    let bases = collect_interface_bases(ctx, node);

    let docstring = extract_jsdoc(node, ctx.source);
    events.push(Event::define_name(
        name.clone(),
        qualname.clone(),
        "interface",
        node,
        ctx.file_path,
    ));
    events.push(Event::enter_scope_with_docstring(
        ScopeType::Interface,
        name.clone(),
        qualname.clone(),
        vec![],
        bases,
        docstring,
        node,
        ctx.file_path,
    ));

    ctx.scope_stack.push((name.clone(), qualname.clone()));

    if let Some(body) = node.child_by_field_name("body") {
        let mut cursor = body.walk();
        for child in body.children(&mut cursor) {
            match child.kind() {
                "method_signature" | "property_signature" | "index_signature" => {
                    if let Some(name_node) = child.child_by_field_name("name") {
                        let member_name = ctx.get_text(name_node).to_string();
                        let member_qualname = ctx.build_qualname(&member_name);
                        let node_type = if child.kind() == "method_signature" {
                            "function"
                        } else {
                            "variable"
                        };
                        events.push(Event::define_name(
                            member_name,
                            member_qualname,
                            node_type,
                            child,
                            ctx.file_path,
                        ));
                    }
                }
                _ => {}
            }
        }
    }

    ctx.scope_stack.pop();
    events.push(Event::exit_scope(
        ScopeType::Interface,
        name,
        qualname,
        node,
        ctx.file_path,
    ));
}

fn emit_type_alias(ctx: &mut Ctx, node: Node, events: &mut Vec<Event>) {
    let name = match node.child_by_field_name("name") {
        Some(n) => ctx.get_text(n).to_string(),
        None => return,
    };

    let qualname = ctx.build_qualname(&name);

    // Always define the type alias name regardless of its shape.
    events.push(Event::define_name(
        name.clone(),
        qualname.clone(),
        "interface",
        node,
        ctx.file_path,
    ));

    // Only create interface scope nodes for object-shape types, not primitive aliases
    // e.g. `type ID = string` is skipped; `type Foo = { bar: string }` is included
    let value_node = match node.child_by_field_name("value") {
        Some(v) => v,
        None => return,
    };

    if value_node.kind() != "object_type" {
        return;
    }

    let docstring = extract_jsdoc(node, ctx.source);
    events.push(Event::enter_scope_with_docstring(
        ScopeType::Interface,
        name.clone(),
        qualname.clone(),
        vec![],
        vec![],
        docstring,
        node,
        ctx.file_path,
    ));

    ctx.scope_stack.push((name.clone(), qualname.clone()));

    // Walk object type members
    let mut cursor = value_node.walk();
    for child in value_node.children(&mut cursor) {
        match child.kind() {
            "method_signature" | "property_signature" => {
                if let Some(name_node) = child.child_by_field_name("name") {
                    let field_name = ctx.get_text(name_node).to_string();
                    let field_qualname = ctx.build_qualname(&field_name);
                    let node_type = if child.kind() == "method_signature" { "function" } else { "variable" };
                    events.push(Event::define_name(
                        field_name,
                        field_qualname,
                        node_type,
                        child,
                        ctx.file_path,
                    ));
                }
            }
            _ => {}
        }
    }

    ctx.scope_stack.pop();
    events.push(Event::exit_scope(
        ScopeType::Interface,
        name,
        qualname,
        node,
        ctx.file_path,
    ));
}

fn emit_enum(ctx: &mut Ctx, node: Node, events: &mut Vec<Event>) {
    let name = match node.child_by_field_name("name") {
        Some(n) => ctx.get_text(n).to_string(),
        None => return,
    };

    let qualname = ctx.build_qualname(&name);

    // Enums are class-like in the graph
    let docstring = extract_jsdoc(node, ctx.source);
    events.push(Event::define_name(
        name.clone(),
        qualname.clone(),
        "class",
        node,
        ctx.file_path,
    ));
    events.push(Event::enter_scope_with_docstring(
        ScopeType::Class,
        name.clone(),
        qualname.clone(),
        vec![],
        vec![],
        docstring,
        node,
        ctx.file_path,
    ));

    ctx.scope_stack.push((name.clone(), qualname.clone()));

    if let Some(body) = node.child_by_field_name("body") {
        let mut cursor = body.walk();
        for child in body.children(&mut cursor) {
            if child.kind() == "enum_member" {
                // First child of enum_member is the property_identifier
                let mut mc = child.walk();
                for member_child in child.children(&mut mc) {
                    if matches!(member_child.kind(), "property_identifier" | "string") {
                        let member_name = ctx
                            .get_text(member_child)
                            .trim_matches(|c| c == '"' || c == '\'')
                            .to_string();
                        if !member_name.is_empty() {
                            let member_qualname = ctx.build_qualname(&member_name);
                            events.push(Event::define_name(
                                member_name,
                                member_qualname,
                                "variable",
                                member_child,
                                ctx.file_path,
                            ));
                        }
                        break;
                    }
                }
            }
        }
    }

    ctx.scope_stack.pop();
    events.push(Event::exit_scope(
        ScopeType::Class,
        name,
        qualname,
        node,
        ctx.file_path,
    ));
}

// ============================================================================
// Variable / import / call emitters
// ============================================================================

fn emit_variable_declaration(ctx: &mut Ctx, node: Node, events: &mut Vec<Event>) {
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        if child.kind() == "variable_declarator" {
            emit_variable_declarator(ctx, child, events);
        }
    }
}

fn emit_variable_declarator(ctx: &mut Ctx, node: Node, events: &mut Vec<Event>) {
    let name_node = match node.child_by_field_name("name") {
        Some(n) => n,
        None => return,
    };

    if name_node.kind() == "identifier" {
        let name = ctx.get_text(name_node).to_string();

        // If the value is a function/arrow, create a named function scope.
        if let Some(value_node) = node.child_by_field_name("value") {
            match value_node.kind() {
                "function" | "arrow_function" | "generator_function" => {
                    let qualname = ctx.build_qualname(&name);

                    let params = value_node
                        .child_by_field_name("parameters")
                        .or_else(|| value_node.child_by_field_name("parameter"))
                        .map(|p| collect_params(ctx, p))
                        .unwrap_or_default();

                    // JSDoc precedes the variable declaration (parent of this declarator)
                    let decl_node = node.parent().unwrap_or(node);
                    let docstring = extract_jsdoc(decl_node, ctx.source);
                    events.push(Event::define_name(
                        name.clone(),
                        qualname.clone(),
                        "function",
                        node,
                        ctx.file_path,
                    ));
                    events.push(Event::enter_scope_with_docstring(
                        ScopeType::Function,
                        name.clone(),
                        qualname.clone(),
                        params,
                        vec![],
                        docstring,
                        value_node,
                        ctx.file_path,
                    ));

                    ctx.scope_stack.push((name.clone(), qualname.clone()));

                    // Arrow function body can be an expression or a statement block.
                    if let Some(body) = value_node.child_by_field_name("body") {
                        if body.kind() == "statement_block" {
                            let mut cursor = body.walk();
                            for child in body.children(&mut cursor) {
                                walk_node(ctx, child, events);
                            }
                        } else {
                            // Expression body (e.g. `() => someCall()`): walk it to
                            // capture UseName / CallExpression events.
                            walk_node(ctx, body, events);
                        }
                    }

                    ctx.scope_stack.pop();
                    events.push(Event::exit_scope(
                        ScopeType::Function,
                        name,
                        qualname,
                        value_node,
                        ctx.file_path,
                    ));
                    return;
                }
                _ => {}
            }
        }

        // Simple variable binding.
        let qualname = ctx.build_qualname(&name);
        events.push(Event::define_name(name.clone(), qualname.clone(), "variable", node, ctx.file_path));
        if let Some(value_node) = node.child_by_field_name("value") {
            // Walk RHS first (post-order: inner call events fire before the assignment event)
            walk_node(ctx, value_node, events);
            // Emit Assignment so the graph builder can create has-a / calls edges from
            // this variable node to the RHS target (mirrors Python's emit_assignment_post_event).
            let value_text = ctx.get_text(value_node).to_string();
            let value_type = js_classify_value_type(value_node.kind());
            events.push(Event::assignment(name, qualname, value_text, value_type, node, ctx.file_path));
        }
    } else {
        // Destructuring pattern — collect all bound names and walk the RHS.
        let bindings = collect_binding_names(ctx, name_node);
        let value_node = node.child_by_field_name("value");
        // Walk RHS first
        if let Some(v) = value_node {
            walk_node(ctx, v, events);
        }
        // Emit DefineName + Assignment for each bound name, pointing to the shared RHS.
        let (value_text, value_type) = match value_node {
            Some(v) => (ctx.get_text(v).to_string(), js_classify_value_type(v.kind())),
            None => (String::new(), "none"),
        };
        for (bound_name, binding_node) in bindings {
            let qualname = ctx.build_qualname(&bound_name);
            events.push(Event::define_name(
                bound_name.clone(),
                qualname.clone(),
                "variable",
                binding_node,
                ctx.file_path,
            ));
            if !value_text.is_empty() {
                events.push(Event::assignment(
                    bound_name,
                    qualname,
                    value_text.clone(),
                    value_type,
                    node,
                    ctx.file_path,
                ));
            }
        }
    }
}

fn emit_import(ctx: &mut Ctx, node: Node, events: &mut Vec<Event>) {
    let mut module = String::new();
    let mut names: Vec<String> = Vec::new();
    let mut aliases: std::collections::HashMap<String, String> = std::collections::HashMap::new();

    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        match child.kind() {
            "string" => {
                module = ctx
                    .get_text(child)
                    .trim_matches(|c| c == '"' || c == '\'' || c == '`')
                    .to_string();
            }
            "import_clause" => {
                let mut c = child.walk();
                for clause_child in child.children(&mut c) {
                    match clause_child.kind() {
                        "identifier" => {
                            // Default import: `import Foo from 'mod'`
                            names.push(ctx.get_text(clause_child).to_string());
                        }
                        "named_imports" => {
                            // Named imports: `import { Foo, Bar } from 'mod'`
                            // Also handles `import { Foo as F } from 'mod'`
                            let mut nc = clause_child.walk();
                            for spec in clause_child.children(&mut nc) {
                                if spec.kind() == "import_specifier" {
                                    if let Some(nm) = spec.child_by_field_name("name") {
                                        let original = ctx.get_text(nm).to_string();
                                        names.push(original.clone());
                                        if let Some(alias_node) = spec.child_by_field_name("alias") {
                                            let alias = ctx.get_text(alias_node).to_string();
                                            aliases.insert(original, alias);
                                        }
                                    }
                                }
                            }
                        }
                        "namespace_import" => {
                            // `import * as Foo from 'mod'`
                            names.push("*".to_string());
                            // Capture alias for `* as Name`
                            if let Some(alias_node) = clause_child.child_by_field_name("name") {
                                let alias = ctx.get_text(alias_node).to_string();
                                aliases.insert("*".to_string(), alias);
                            }
                        }
                        _ => {}
                    }
                }
            }
            _ => {}
        }
    }

    if !module.is_empty() {
        // Resolve path-alias imports to canonical project-rooted qualnames so
        // they match the module paths produced by `derive_module_path`.
        // e.g. `@app/store` → `frontend.src.app.store`.
        let module = normalize_import(&module, ctx.file_path, &ctx.project_info);
        events.push(Event::import_statement(module, names, aliases, false, node, ctx.file_path));
    }
}

fn emit_call(ctx: &mut Ctx, node: Node, events: &mut Vec<Event>) {
    // call_expression: function field; new_expression: constructor field
    let callee_node = node
        .child_by_field_name("function")
        .or_else(|| node.child_by_field_name("constructor"));

    if let Some(func_node) = callee_node {
        let callee = ctx.get_text(func_node).to_string();

        let mut arguments = Vec::new();
        if let Some(args_node) = node.child_by_field_name("arguments") {
            let mut cursor = args_node.walk();
            for child in args_node.children(&mut cursor) {
                match child.kind() {
                    "(" | ")" | "," => {}
                    _ => {
                        let text = ctx.get_text(child).to_string();
                        if !text.is_empty() {
                            arguments.push(text);
                        }
                    }
                }
            }
        }

        events.push(Event::call_expression(callee, arguments, node, ctx.file_path));
    }
}

fn emit_export(ctx: &mut Ctx, node: Node, events: &mut Vec<Event>) {
    // Check for re-export: `export { X } from 'source'` or `export * from 'source'`
    // These have a `string` child for the source module.
    let mut source_module: Option<String> = None;
    let mut export_names: Vec<String> = Vec::new();
    let mut has_export_clause = false;
    let mut has_namespace_export = false;

    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        match child.kind() {
            "string" => {
                source_module = Some(
                    ctx.get_text(child)
                        .trim_matches(|c| c == '"' || c == '\'' || c == '`')
                        .to_string(),
                );
            }
            "export_clause" => {
                has_export_clause = true;
                let mut ec = child.walk();
                for spec in child.children(&mut ec) {
                    if spec.kind() == "export_specifier" {
                        if let Some(nm) = spec.child_by_field_name("name") {
                            export_names.push(ctx.get_text(nm).to_string());
                        }
                    }
                }
            }
            "namespace_export" => {
                has_namespace_export = true;
                export_names.push("*".to_string());
            }
            _ => {}
        }
    }

    if let Some(src) = source_module {
        // This is a re-export statement — emit an import event for the dependency.
        if has_export_clause || has_namespace_export {
            let resolved = normalize_import(&src, ctx.file_path, &ctx.project_info);
            events.push(Event::import_statement(resolved, export_names, std::collections::HashMap::new(), false, node, ctx.file_path));
            return;
        }
    }

    // Not a re-export — walk child declarations normally.
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        match child.kind() {
            "function_declaration" | "generator_function_declaration" => {
                emit_function(ctx, child, events);
            }
            "class_declaration" | "abstract_class_declaration" => {
                emit_class(ctx, child, events);
            }
            "lexical_declaration" | "variable_declaration" => {
                emit_variable_declaration(ctx, child, events);
            }
            "interface_declaration" => {
                emit_interface(ctx, child, events);
            }
            "type_alias_declaration" => {
                emit_type_alias(ctx, child, events);
            }
            "enum_declaration" => {
                emit_enum(ctx, child, events);
            }
            _ => {}
        }
    }
}

/// Emit DefineName for the loop variable in `for...of` / `for...in` statements
/// and recurse into the iterable expression and loop body.
///
/// Grammar:
///   for_in_statement: `for (left in right) body`
///   for_of_statement: `for (left of right) body`
/// The `left` field holds the binding (identifier or destructuring pattern).
/// The optional `var`/`let`/`const` keyword is a sibling, not part of `left`.
fn emit_for_loop(ctx: &mut Ctx, node: Node, events: &mut Vec<Event>) {
    // Walk the `right` (iterable) first to emit use/call events for it.
    if let Some(right) = node.child_by_field_name("right") {
        walk_node(ctx, right, events);
    }

    // Bind the loop variable(s) from the `left` field.
    if let Some(left) = node.child_by_field_name("left") {
        let bindings = collect_binding_names(ctx, left);
        for (name, binding_node) in bindings {
            let qualname = ctx.build_qualname(&name);
            events.push(Event::define_name(
                name,
                qualname,
                "variable",
                binding_node,
                ctx.file_path,
            ));
        }
    }

    // Recurse into the loop body.
    if let Some(body) = node.child_by_field_name("body") {
        walk_node(ctx, body, events);
    }
}

/// Emit DefineName for the caught exception variable in a `catch` clause and
/// recurse into the clause body.
///
/// Grammar:
///   catch_clause: `catch (parameter?) body`
/// The `parameter` field is the bound variable (can be a pattern).
fn emit_catch_clause(ctx: &mut Ctx, node: Node, events: &mut Vec<Event>) {
    if let Some(param) = node.child_by_field_name("parameter") {
        let bindings = collect_binding_names(ctx, param);
        for (name, binding_node) in bindings {
            let qualname = ctx.build_qualname(&name);
            events.push(Event::define_name(
                name,
                qualname,
                "variable",
                binding_node,
                ctx.file_path,
            ));
        }
    }

    // Recurse into body.
    if let Some(body) = node.child_by_field_name("body") {
        let mut cursor = body.walk();
        for child in body.children(&mut cursor) {
            walk_node(ctx, child, events);
        }
    }
}

// ============================================================================
// Helpers
// ============================================================================

fn collect_params(ctx: &Ctx, params_node: Node) -> Vec<String> {
    let mut params = Vec::new();
    let mut cursor = params_node.walk();
    for child in params_node.children(&mut cursor) {
        match child.kind() {
            "identifier" => {
                params.push(ctx.get_text(child).to_string());
            }
            "assignment_pattern" => {
                // `x = default` — use the left-hand identifier
                if let Some(left) = child.child_by_field_name("left") {
                    if left.kind() == "identifier" {
                        params.push(ctx.get_text(left).to_string());
                    }
                }
            }
            "rest_pattern" => {
                // `...args` — find the inner identifier
                let mut rc = child.walk();
                for rest_child in child.children(&mut rc) {
                    if rest_child.kind() == "identifier" {
                        params.push(ctx.get_text(rest_child).to_string());
                        break;
                    }
                }
            }
            // TypeScript: `name: Type` or `name?: Type`
            "required_parameter" | "optional_parameter" => {
                if let Some(pattern) = child.child_by_field_name("pattern") {
                    if pattern.kind() == "identifier" {
                        params.push(ctx.get_text(pattern).to_string());
                    }
                }
            }
            _ => {}
        }
    }
    params
}

/// Classify a JS/TS value expression node kind into a semantic category.
fn js_classify_value_type(kind: &str) -> &'static str {
    match kind {
        "number" | "string" | "template_string" | "true" | "false" | "null" => "literal",
        "call_expression" | "new_expression" | "await_expression" => "call",
        "identifier" => "name",
        "member_expression" | "subscript_expression" => "attribute",
        _ => "expression",
    }
}

/// Recursively collect all identifier bindings introduced by a destructuring pattern node.
///
/// Handles: `object_pattern`, `array_pattern`, `rest_pattern`, `pair_pattern`,
/// `assignment_pattern` (default values), and bare `identifier` / `shorthand_property_identifier_pattern`.
fn collect_binding_names<'a>(ctx: &Ctx<'a>, node: Node<'a>) -> Vec<(String, Node<'a>)> {
    let mut out = Vec::new();
    collect_binding_names_inner(ctx, node, &mut out);
    out
}

fn collect_binding_names_inner<'a>(
    ctx: &Ctx<'a>,
    node: Node<'a>,
    out: &mut Vec<(String, Node<'a>)>,
) {
    match node.kind() {
        // Simple binding: `x` in `const x = ...` or `const { x } = ...`
        "identifier" | "shorthand_property_identifier_pattern" => {
            let name = ctx.get_text(node).to_string();
            if !name.is_empty() && name != "_" {
                out.push((name, node));
            }
        }
        // Object / array destructuring containers
        "object_pattern" | "array_pattern" => {
            let mut cursor = node.walk();
            for child in node.children(&mut cursor) {
                collect_binding_names_inner(ctx, child, out);
            }
        }
        // `...rest`
        "rest_pattern" => {
            let mut cursor = node.walk();
            for child in node.children(&mut cursor) {
                if child.kind() == "identifier" {
                    let name = ctx.get_text(child).to_string();
                    if !name.is_empty() {
                        out.push((name, child));
                    }
                }
            }
        }
        // `{ key: pattern }` — bind the value-side pattern
        "pair_pattern" => {
            if let Some(value) = node.child_by_field_name("value") {
                collect_binding_names_inner(ctx, value, out);
            }
        }
        // `x = default` in a destructuring context — bind the left side
        "assignment_pattern" => {
            if let Some(left) = node.child_by_field_name("left") {
                collect_binding_names_inner(ctx, left, out);
            }
        }
        _ => {}
    }
}

fn collect_interface_bases(ctx: &Ctx, node: Node) -> Vec<String> {
    let mut bases = Vec::new();
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        // `extends_type_clause` contains the base interface names
        if child.kind() == "extends_type_clause" {
            let mut c = child.walk();
            for base in child.children(&mut c) {
                if matches!(base.kind(), "type_identifier" | "identifier") {
                    bases.push(ctx.get_text(base).to_string());
                }
            }
        }
    }
    bases
}

fn walk_node(ctx: &mut Ctx, node: Node, events: &mut Vec<Event>) {
    match node.kind() {
        "function_declaration" | "generator_function_declaration" => {
            emit_function(ctx, node, events);
        }
        "class_declaration" | "abstract_class_declaration" => {
            emit_class(ctx, node, events);
        }
        "lexical_declaration" | "variable_declaration" => {
            emit_variable_declaration(ctx, node, events);
        }
        "import_statement" => {
            emit_import(ctx, node, events);
        }
        // POST-ORDER: recurse arguments first so inner call events fire before the
        // outer call — matches Python's emission order for correct PDG sequencing.
        "call_expression" | "new_expression" => {
            if let Some(args) = node.child_by_field_name("arguments") {
                let mut cursor = args.walk();
                for child in args.children(&mut cursor) {
                    walk_node(ctx, child, events);
                }
            }
            emit_call(ctx, node, events);
        }
        "export_statement" => {
            emit_export(ctx, node, events);
        }
        // ── Control flow ────────────────────────────────────────────────────────
        "if_statement" => {
            let condition = node
                .child_by_field_name("condition")
                .map(|c| ctx.get_text(c).to_string())
                .unwrap_or_default();
            events.push(Event::control_block("if", condition, node, ctx.file_path));
            if let Some(c) = node.child_by_field_name("condition") {
                walk_node(ctx, c, events);
            }
            if let Some(c) = node.child_by_field_name("consequence") {
                walk_node(ctx, c, events);
            }
            if let Some(c) = node.child_by_field_name("alternative") {
                walk_node(ctx, c, events);
            }
            events.push(Event::end_control_block("if", node, ctx.file_path));
        }
        "else_clause" => {
            events.push(Event::else_block("else", String::new(), node, ctx.file_path));
            let mut cursor = node.walk();
            for child in node.children(&mut cursor) {
                walk_node(ctx, child, events);
            }
            events.push(Event::end_control_block("else", node, ctx.file_path));
        }
        "while_statement" => {
            let condition = node
                .child_by_field_name("condition")
                .map(|c| ctx.get_text(c).to_string())
                .unwrap_or_default();
            events.push(Event::control_block("while", condition, node, ctx.file_path));
            let mut cursor = node.walk();
            for child in node.children(&mut cursor) {
                walk_node(ctx, child, events);
            }
            events.push(Event::end_control_block("while", node, ctx.file_path));
        }
        "do_statement" => {
            let condition = node
                .child_by_field_name("condition")
                .map(|c| ctx.get_text(c).to_string())
                .unwrap_or_default();
            events.push(Event::control_block("do-while", condition, node, ctx.file_path));
            let mut cursor = node.walk();
            for child in node.children(&mut cursor) {
                walk_node(ctx, child, events);
            }
            events.push(Event::end_control_block("do-while", node, ctx.file_path));
        }
        "try_statement" => {
            events.push(Event::control_block("try", String::new(), node, ctx.file_path));
            let mut cursor = node.walk();
            for child in node.children(&mut cursor) {
                walk_node(ctx, child, events);
            }
            events.push(Event::end_control_block("try", node, ctx.file_path));
        }
        "finally_clause" => {
            events.push(Event::else_block("finally", String::new(), node, ctx.file_path));
            let mut cursor = node.walk();
            for child in node.children(&mut cursor) {
                walk_node(ctx, child, events);
            }
            events.push(Event::end_control_block("finally", node, ctx.file_path));
        }
        "switch_statement" => {
            let value = node
                .child_by_field_name("value")
                .map(|v| ctx.get_text(v).to_string())
                .unwrap_or_default();
            events.push(Event::control_block("switch", value, node, ctx.file_path));
            if let Some(body) = node.child_by_field_name("body") {
                let mut cursor = body.walk();
                for child in body.children(&mut cursor) {
                    walk_node(ctx, child, events);
                }
            }
            events.push(Event::end_control_block("switch", node, ctx.file_path));
        }
        "switch_case" => {
            let value = node
                .child_by_field_name("value")
                .map(|v| ctx.get_text(v).to_string())
                .unwrap_or_default();
            events.push(Event::else_block("case", value, node, ctx.file_path));
            let mut cursor = node.walk();
            for child in node.children(&mut cursor) {
                walk_node(ctx, child, events);
            }
            events.push(Event::end_control_block("case", node, ctx.file_path));
        }
        "switch_default" => {
            events.push(Event::else_block("default", String::new(), node, ctx.file_path));
            let mut cursor = node.walk();
            for child in node.children(&mut cursor) {
                walk_node(ctx, child, events);
            }
            events.push(Event::end_control_block("default", node, ctx.file_path));
        }
        // ── Early exits ─────────────────────────────────────────────────────────
        "return_statement" => {
            let mut cursor = node.walk();
            let value_node = node
                .children(&mut cursor)
                .find(|c| c.kind() != "return" && c.is_named());
            let (value, value_type) = match value_node {
                Some(v) => (ctx.get_text(v).to_string(), js_classify_value_type(v.kind())),
                None => (String::new(), "none"),
            };
            events.push(Event::return_stmt(value, value_type, node, ctx.file_path));
            // Still recurse to capture calls/uses in the return expression.
            let mut cursor2 = node.walk();
            for child in node.children(&mut cursor2) {
                if child.kind() != "return" {
                    walk_node(ctx, child, events);
                }
            }
        }
        "throw_statement" => {
            let mut cursor = node.walk();
            let exc = node
                .children(&mut cursor)
                .find(|c| c.kind() != "throw" && c.is_named())
                .map(|n| ctx.get_text(n).to_string())
                .unwrap_or_default();
            events.push(Event::raise_statement(exc, node, ctx.file_path));
            let mut cursor2 = node.walk();
            for child in node.children(&mut cursor2) {
                if child.kind() != "throw" {
                    walk_node(ctx, child, events);
                }
            }
        }
        "break_statement" => {
            events.push(Event::break_statement(node, ctx.file_path));
        }
        "continue_statement" => {
            events.push(Event::continue_statement(node, ctx.file_path));
        }
        // ── Literals ────────────────────────────────────────────────────────────
        "number" => {
            events.push(Event::literal(
                ctx.get_text(node).to_string(),
                "number",
                node,
                ctx.file_path,
            ));
        }
        "string" | "template_string" => {
            events.push(Event::literal(
                ctx.get_text(node).to_string(),
                "string",
                node,
                ctx.file_path,
            ));
        }
        "true" | "false" => {
            events.push(Event::literal(
                ctx.get_text(node).to_string(),
                "boolean",
                node,
                ctx.file_path,
            ));
        }
        "null" => {
            events.push(Event::literal("null".to_string(), "null", node, ctx.file_path));
        }
        // ── Augmented assignment (+=, -=, etc.) ─────────────────────────────────
        // LHS is both read and written; emit UseName for the read, then Assignment.
        "augmented_assignment_expression" => {
            if let Some(left) = node.child_by_field_name("left") {
                if left.kind() == "identifier" {
                    let name = ctx.get_text(left).to_string();
                    events.push(Event::use_name(name, left, ctx.file_path));
                }
            }
            if let Some(right) = node.child_by_field_name("right") {
                walk_node(ctx, right, events);
            }
            if let (Some(left), Some(right)) = (
                node.child_by_field_name("left"),
                node.child_by_field_name("right"),
            ) {
                if left.kind() == "identifier" {
                    let name = ctx.get_text(left).to_string();
                    let qualname = ctx.build_qualname(&name);
                    let value = ctx.get_text(right).to_string();
                    let value_type = js_classify_value_type(right.kind());
                    events.push(Event::assignment(
                        name,
                        qualname,
                        value,
                        value_type,
                        node,
                        ctx.file_path,
                    ));
                }
            }
        }
        // ── for...of / for...in ─────────────────────────────────────────────────
        "for_in_statement" | "for_of_statement" => {
            emit_for_loop(ctx, node, events);
        }
        // ── catch clause ────────────────────────────────────────────────────────
        "catch_clause" => {
            emit_catch_clause(ctx, node, events);
        }
        // ── TypeScript-specific ─────────────────────────────────────────────────
        "interface_declaration" => {
            emit_interface(ctx, node, events);
        }
        "type_alias_declaration" => {
            emit_type_alias(ctx, node, events);
        }
        "enum_declaration" => {
            emit_enum(ctx, node, events);
        }
        // ── Member expressions (obj.prop) — emit AttributeAccess + recurse object only
        // The property is a member name, not a scope-resolvable reference; emit_identifier_use
        // already filters it out when walking via the default arm, but with this explicit arm
        // we skip the default recursion entirely and only walk `object`.
        "member_expression" => {
            let obj = node
                .child_by_field_name("object")
                .map(|n| ctx.get_text(n).to_string())
                .unwrap_or_default();
            let prop = node
                .child_by_field_name("property")
                .map(|n| ctx.get_text(n).to_string())
                .unwrap_or_default();
            events.push(Event::attribute_access(obj, prop, node, ctx.file_path));
            // Recurse into object only — property is not a scope name
            if let Some(obj_node) = node.child_by_field_name("object") {
                walk_node(ctx, obj_node, events);
            }
        }
        // ── Decorators (@foo, @foo.bar, @foo()) ─────────────────────────────────
        "decorator" => {
            emit_decorator(ctx, node, events);
        }
        // ── Await expression — pass through to value ─────────────────────────────
        "await_expression" => {
            if let Some(val) = node.child_by_field_name("value") {
                walk_node(ctx, val, events);
            }
        }
        // ── TypeScript typed parameters — walk type annotation only ──────────────
        // The parameter name is a definition (excluded in emit_identifier_use), so
        // we only recurse into the type child to capture type reference UseName events.
        "required_parameter" | "optional_parameter" => {
            if let Some(type_node) = node.child_by_field_name("type") {
                walk_node(ctx, type_node, events);
            }
        }
        // ── Identifier uses ─────────────────────────────────────────────────────
        // type_identifier covers TypeScript type references (const x: SomeType).
        // jsx_identifier covers JSX element names (<MyComponent />).
        "identifier" | "type_identifier" | "jsx_identifier" => {
            emit_identifier_use(ctx, node, events);
        }
        _ => {
            let mut cursor = node.walk();
            for child in node.children(&mut cursor) {
                walk_node(ctx, child, events);
            }
        }
    }
}

fn read_tsconfig_aliases_from(path: &std::path::Path) -> Option<Vec<(String, String)>> {
    use std::path::{Component, PathBuf};

    let content = std::fs::read_to_string(path).ok()?;
    let json: serde_json::Value = serde_json::from_str(&content).ok()?;
    let paths_obj = json.get("compilerOptions")?.get("paths")?.as_object()?;

    let tsconfig_dir = path.parent().unwrap_or(std::path::Path::new("."));

    let mut aliases = Vec::new();
    for (alias, targets) in paths_obj {
        let alias_prefix = alias.strip_suffix("/*").unwrap_or(alias.as_str());
        if alias_prefix.is_empty() || alias_prefix == "@" {
            continue;
        }
        if let Some(target_str) = targets
            .as_array()
            .and_then(|a| a.first())
            .and_then(|v| v.as_str())
        {
            // Strip glob suffix and trailing slashes.
            let without_glob = target_str
                .strip_suffix("/*")
                .unwrap_or(target_str)
                .trim_end_matches('/');
            // Strip file extensions from file-targeted aliases like "./src/store.ts" → "src/store"
            let without_ext = [".ts", ".tsx", ".js", ".jsx", ".mjs"]
                .iter()
                .fold(without_glob.to_string(), |s, ext| {
                    s.strip_suffix(ext).unwrap_or(&s).to_string()
                });

            let target_dir = if without_ext.starts_with("../") || without_ext == ".." {
                // Parent-relative target — resolve to absolute path so that
                // normalize_import can use derive_module_path on it.
                let abs = tsconfig_dir.join(&without_ext);
                let normalized: PathBuf = abs.components().fold(PathBuf::new(), |mut acc, c| {
                    match c {
                        Component::ParentDir => { acc.pop(); }
                        Component::CurDir => {}
                        _ => acc.push(c),
                    }
                    acc
                });
                normalized.to_string_lossy().to_string()
            } else {
                // In-project target — strip leading `./` and store as relative.
                without_ext.strip_prefix("./").unwrap_or(&without_ext).to_string()
            };

            aliases.push((alias_prefix.to_string(), target_dir));
        }
    }
    Some(aliases)
}

let normalized: PathBuf = abs.components().fold(PathBuf::new(), |mut acc, c| {
    match c {
        Component::ParentDir => { acc.pop(); }
        Component::CurDir => {}
        _ => acc.push(c),
    }
    acc
});

pub fn parse(source: &str, tree: &Option<Tree>, file_path: &str, _lang: JsLang) -> Vec<Event> {
    let mut events = Vec::new();

    // Source line events (for CodeSnippet subscriber)
    for (i, line) in source.lines().enumerate() {
        events.push(Event::SourceLine {
            file: file_path.to_string(),
            line_number: i + 1,
            text: line.to_string(),
        });
    }

    let Some(tree) = tree else {
        return events;
    };

    let root = tree.root_node();
    let project_info = find_project_info(file_path);
    let module_parts = derive_module_path(file_path);
    let module_name = module_parts.last().cloned().unwrap_or_else(|| "module".to_string());
    let module_qualname = module_parts.join(".");

    let mut ctx = Ctx {
        source,
        file_path,
        scope_stack: vec![(module_name.clone(), module_qualname.clone())],
        project_info,
    };

    // Enter module scope.
    let module_docstring = extract_module_jsdoc(root, source);
    events.push(Event::enter_scope_with_docstring(
        ScopeType::Module,
        module_name.clone(),
        module_qualname.clone(),
        vec![],
        vec![],
        module_docstring,
        root,
        file_path,
    ));

    let mut cursor = root.walk();
    for child in root.children(&mut cursor) {
        walk_node(&mut ctx, child, &mut events);
    }

    ctx.scope_stack.pop();
    events.push(Event::exit_scope(
        ScopeType::Module,
        module_name,
        module_qualname,
        root,
        file_path,
    ));

    events
}

fn normalize_import(module: &str, file_path: &str, info: &Option<ProjectInfo>) -> String {
    // Relative import — resolve against the importing file's directory.
    if module.starts_with("./") || module.starts_with("../") {
        use std::path::Path;
        // Skip imports that point to non-source files (e.g. .css, .svg, .png).
        if let Some(ext) = Path::new(module).extension() {
            let ext = ext.to_string_lossy();
            if !matches!(ext.as_ref(), "ts" | "tsx" | "js" | "jsx" | "mjs" | "cjs" | "py") {
                return String::new();
            }
        }
        if let Some(dir) = Path::new(file_path).parent() {
            // Build the resolved filesystem path (without extension).
            let resolved = dir.join(module);
            // Normalise away `..` and `.` components.
            let canonical: std::path::PathBuf = resolved
                .components()
                .fold(std::path::PathBuf::new(), |mut acc, c| {
                    use std::path::Component;
                    match c {
                        Component::ParentDir => { acc.pop(); }
                        Component::CurDir => {}
                        _ => acc.push(c),
                    }
                    acc
                });
            // derive_module_path expects a file path string; give it a fake
            // extension so the stem logic works correctly for non-index files.
            let as_str = canonical.to_string_lossy();
            return derive_module_path(&format!("{}.ts", as_str)).join(".");
        }
    }

    // Try alias lookup for any non-relative import (not just `@`-prefixed).
    if let Some(info) = info {
        for (alias_prefix, target_dir) in &info.aliases {
            let alias_slash = format!("{}/", alias_prefix);
            let rest = if module.starts_with(&alias_slash) {
                &module[alias_slash.len()..] // "store" from "@app/store"
            } else if module == alias_prefix.as_str() {
                "" // exact alias with no trailing path
            } else {
                continue;
            };

            if target_dir.starts_with('/') {
                // Absolute path target (from a `../`-prefixed tsconfig entry).
                // Build a fake file path and use derive_module_path for resolution
                // so the result is consistent with how real files are named.
                let mut fake_path = target_dir.clone();
                if !rest.is_empty() {
                    fake_path.push('/');
                    fake_path.push_str(rest);
                }
                let parts = derive_module_path(&format!("{}.ts", fake_path));
                return parts.join(".");
            } else {
                // Relative target — build dotted path from root_name + target segments.
                let mut parts = vec![info.root_name.clone()];
                for seg in target_dir.split('/') {
                    if !seg.is_empty() {
                        parts.push(seg.to_string());
                    }
                }
                for seg in rest.split('/') {
                    if !seg.is_empty() {
                        parts.push(seg.to_string());
                    }
                }
                return parts.join(".");
            }
        }
    }

    if !module.starts_with('@') {
        return module.to_string();
    }

    // No alias matched — scoped npm package; normalise slashes for consistency.
    module.replace('/', ".")
}

.fold(std::path::PathBuf::new(), |mut acc, c| {
    use std::path::Component;
    match c {
        Component::ParentDir => { acc.pop(); }
        Component::CurDir => {}
        _ => acc.push(c),
    }
    acc
});

fn find_project_info(file_path: &str) -> Option<ProjectInfo> {
    use std::path::Path;

    let mut dir = Path::new(file_path).parent()?;
    loop {
        if dir.file_name().and_then(|n| n.to_str()) == Some("node_modules") {
            return None;
        }

        let has_package_json = dir.join("package.json").exists();
        let tsconfig_path = dir.join("tsconfig.json");
        let has_tsconfig = tsconfig_path.exists();

        if has_package_json || has_tsconfig {
            let root_name = dir.file_name()?.to_str()?.to_string();
            let root_path = dir.to_str()?.to_string();

            let aliases = if has_tsconfig {
                read_tsconfig_aliases_from(&tsconfig_path).unwrap_or_default()
            } else {
                vec![]
            };

            return Some(ProjectInfo { root_name, root_path, aliases });
        }

        dir = dir.parent()?;
    }
}

fn extract_module_jsdoc(root: Node, source: &str) -> Option<String> {
    let mut cursor = root.walk();
    for child in root.children(&mut cursor) {
        if child.kind() == "comment" {
            let text = &source[child.byte_range()];
            if text.starts_with("/**") {
                return Some(clean_jsdoc(text));
            }
            // Non-JSDoc comment at top — skip
            continue;
        }
        break;
    }
    None
}

fn extract_jsdoc(node: Node, source: &str) -> Option<String> {
    let prev = node.prev_named_sibling()?;
    if prev.kind() != "comment" {
        return None;
    }
    let text = &source[prev.byte_range()];
    if !text.starts_with("/**") {
        return None;
    }
    Some(clean_jsdoc(text))
}

fn emit_variable_declarator(ctx: &mut Ctx, node: Node, events: &mut Vec<Event>) {
    let name_node = match node.child_by_field_name("name") {
        Some(n) => n,
        None => return,
    };

    if name_node.kind() == "identifier" {
        let name = ctx.get_text(name_node).to_string();

        // If the value is a function/arrow, create a named function scope.
        if let Some(value_node) = node.child_by_field_name("value") {
            match value_node.kind() {
                "function" | "arrow_function" | "generator_function" => {
                    let qualname = ctx.build_qualname(&name);

                    let params = value_node
                        .child_by_field_name("parameters")
                        .or_else(|| value_node.child_by_field_name("parameter"))
                        .map(|p| collect_params(ctx, p))
                        .unwrap_or_default();

                    // JSDoc precedes the variable declaration (parent of this declarator)
                    let decl_node = node.parent().unwrap_or(node);
                    let docstring = extract_jsdoc(decl_node, ctx.source);
                    events.push(Event::define_name(
                        name.clone(),
                        qualname.clone(),
                        "function",
                        node,
                        ctx.file_path,
                    ));
                    events.push(Event::enter_scope_with_docstring(
                        ScopeType::Function,
                        name.clone(),
                        qualname.clone(),
                        params,
                        vec![],
                        docstring,
                        value_node,
                        ctx.file_path,
                    ));

                    ctx.scope_stack.push((name.clone(), qualname.clone()));

                    // Arrow function body can be an expression or a statement block.
                    if let Some(body) = value_node.child_by_field_name("body") {
                        if body.kind() == "statement_block" {
                            let mut cursor = body.walk();
                            for child in body.children(&mut cursor) {
                                walk_node(ctx, child, events);
                            }
                        } else {
                            // Expression body (e.g. `() => someCall()`): walk it to
                            // capture UseName / CallExpression events.
                            walk_node(ctx, body, events);
                        }
                    }

                    ctx.scope_stack.pop();
                    events.push(Event::exit_scope(
                        ScopeType::Function,
                        name,
                        qualname,
                        value_node,
                        ctx.file_path,
                    ));
                    return;
                }
                _ => {}
            }
        }

        // Simple variable binding.
        let qualname = ctx.build_qualname(&name);
        events.push(Event::define_name(name.clone(), qualname.clone(), "variable", node, ctx.file_path));
        if let Some(value_node) = node.child_by_field_name("value") {
            // Walk RHS first (post-order: inner call events fire before the assignment event)
            walk_node(ctx, value_node, events);
            // Emit Assignment so the graph builder can create has-a / calls edges from
            // this variable node to the RHS target (mirrors Python's emit_assignment_post_event).
            let value_text = ctx.get_text(value_node).to_string();
            let value_type = js_classify_value_type(value_node.kind());
            events.push(Event::assignment(name, qualname, value_text, value_type, node, ctx.file_path));
        }
    } else {
        // Destructuring pattern — collect all bound names and walk the RHS.
        let bindings = collect_binding_names(ctx, name_node);
        let value_node = node.child_by_field_name("value");
        // Walk RHS first
        if let Some(v) = value_node {
            walk_node(ctx, v, events);
        }
        // Emit DefineName + Assignment for each bound name, pointing to the shared RHS.
        let (value_text, value_type) = match value_node {
            Some(v) => (ctx.get_text(v).to_string(), js_classify_value_type(v.kind())),
            None => (String::new(), "none"),
        };
        for (bound_name, binding_node) in bindings {
            let qualname = ctx.build_qualname(&bound_name);
            events.push(Event::define_name(
                bound_name.clone(),
                qualname.clone(),
                "variable",
                binding_node,
                ctx.file_path,
            ));
            if !value_text.is_empty() {
                events.push(Event::assignment(
                    bound_name,
                    qualname,
                    value_text.clone(),
                    value_type,
                    node,
                    ctx.file_path,
                ));
            }
        }
    }
}

fn emit_variable_declaration(ctx: &mut Ctx, node: Node, events: &mut Vec<Event>) {
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        if child.kind() == "variable_declarator" {
            emit_variable_declarator(ctx, child, events);
        }
    }
}

fn emit_type_alias(ctx: &mut Ctx, node: Node, events: &mut Vec<Event>) {
    let name = match node.child_by_field_name("name") {
        Some(n) => ctx.get_text(n).to_string(),
        None => return,
    };

    let qualname = ctx.build_qualname(&name);

    // Always define the type alias name regardless of its shape.
    events.push(Event::define_name(
        name.clone(),
        qualname.clone(),
        "interface",
        node,
        ctx.file_path,
    ));

    // Only create interface scope nodes for object-shape types, not primitive aliases
    // e.g. `type ID = string` is skipped; `type Foo = { bar: string }` is included
    let value_node = match node.child_by_field_name("value") {
        Some(v) => v,
        None => return,
    };

    if value_node.kind() != "object_type" {
        return;
    }

    let docstring = extract_jsdoc(node, ctx.source);
    events.push(Event::enter_scope_with_docstring(
        ScopeType::Interface,
        name.clone(),
        qualname.clone(),
        vec![],
        vec![],
        docstring,
        node,
        ctx.file_path,
    ));

    ctx.scope_stack.push((name.clone(), qualname.clone()));

    // Walk object type members
    let mut cursor = value_node.walk();
    for child in value_node.children(&mut cursor) {
        match child.kind() {
            "method_signature" | "property_signature" => {
                if let Some(name_node) = child.child_by_field_name("name") {
                    let field_name = ctx.get_text(name_node).to_string();
                    let field_qualname = ctx.build_qualname(&field_name);
                    let node_type = if child.kind() == "method_signature" { "function" } else { "variable" };
                    events.push(Event::define_name(
                        field_name,
                        field_qualname,
                        node_type,
                        child,
                        ctx.file_path,
                    ));
                }
            }
            _ => {}
        }
    }

    ctx.scope_stack.pop();
    events.push(Event::exit_scope(
        ScopeType::Interface,
        name,
        qualname,
        node,
        ctx.file_path,
    ));
}

fn emit_method(ctx: &mut Ctx, node: Node, events: &mut Vec<Event>) {
    let name = match node.child_by_field_name("name") {
        Some(n) => ctx.get_text(n).to_string(),
        None => return,
    };

    let qualname = ctx.build_qualname(&name);

    let params = node
        .child_by_field_name("parameters")
        .map(|p| collect_params(ctx, p))
        .unwrap_or_default();

    let docstring = extract_jsdoc(node, ctx.source);
    events.push(Event::define_name(
        name.clone(),
        qualname.clone(),
        "function",
        node,
        ctx.file_path,
    ));
    events.push(Event::enter_scope_with_docstring(
        ScopeType::Function,
        name.clone(),
        qualname.clone(),
        params,
        vec![],
        docstring,
        node,
        ctx.file_path,
    ));

    ctx.scope_stack.push((name.clone(), qualname.clone()));

    // Walk TypeScript typed parameter annotations and return type
    if let Some(params) = node.child_by_field_name("parameters") {
        let mut cursor = params.walk();
        for child in params.children(&mut cursor) {
            if matches!(child.kind(), "required_parameter" | "optional_parameter") {
                walk_node(ctx, child, events);
            }
        }
    }
    if let Some(rt) = node.child_by_field_name("return_type") {
        walk_node(ctx, rt, events);
    }

    if let Some(body) = node.child_by_field_name("body") {
        let mut cursor = body.walk();
        for child in body.children(&mut cursor) {
            walk_node(ctx, child, events);
        }
    }

    ctx.scope_stack.pop();
    events.push(Event::exit_scope(
        ScopeType::Function,
        name,
        qualname,
        node,
        ctx.file_path,
    ));
}

fn emit_interface(ctx: &mut Ctx, node: Node, events: &mut Vec<Event>) {
    let name = match node.child_by_field_name("name") {
        Some(n) => ctx.get_text(n).to_string(),
        None => return,
    };

    let qualname = ctx.build_qualname(&name);

    // Collect base interfaces from `extends` clause
    let bases = collect_interface_bases(ctx, node);

    let docstring = extract_jsdoc(node, ctx.source);
    events.push(Event::define_name(
        name.clone(),
        qualname.clone(),
        "interface",
        node,
        ctx.file_path,
    ));
    events.push(Event::enter_scope_with_docstring(
        ScopeType::Interface,
        name.clone(),
        qualname.clone(),
        vec![],
        bases,
        docstring,
        node,
        ctx.file_path,
    ));

    ctx.scope_stack.push((name.clone(), qualname.clone()));

    if let Some(body) = node.child_by_field_name("body") {
        let mut cursor = body.walk();
        for child in body.children(&mut cursor) {
            match child.kind() {
                "method_signature" | "property_signature" | "index_signature" => {
                    if let Some(name_node) = child.child_by_field_name("name") {
                        let member_name = ctx.get_text(name_node).to_string();
                        let member_qualname = ctx.build_qualname(&member_name);
                        let node_type = if child.kind() == "method_signature" {
                            "function"
                        } else {
                            "variable"
                        };
                        events.push(Event::define_name(
                            member_name,
                            member_qualname,
                            node_type,
                            child,
                            ctx.file_path,
                        ));
                    }
                }
                _ => {}
            }
        }
    }

    ctx.scope_stack.pop();
    events.push(Event::exit_scope(
        ScopeType::Interface,
        name,
        qualname,
        node,
        ctx.file_path,
    ));
}

fn emit_import(ctx: &mut Ctx, node: Node, events: &mut Vec<Event>) {
    let mut module = String::new();
    let mut names: Vec<String> = Vec::new();
    let mut aliases: std::collections::HashMap<String, String> = std::collections::HashMap::new();

    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        match child.kind() {
            "string" => {
                module = ctx
                    .get_text(child)
                    .trim_matches(|c| c == '"' || c == '\'' || c == '`')
                    .to_string();
            }
            "import_clause" => {
                let mut c = child.walk();
                for clause_child in child.children(&mut c) {
                    match clause_child.kind() {
                        "identifier" => {
                            // Default import: `import Foo from 'mod'`
                            names.push(ctx.get_text(clause_child).to_string());
                        }
                        "named_imports" => {
                            // Named imports: `import { Foo, Bar } from 'mod'`
                            // Also handles `import { Foo as F } from 'mod'`
                            let mut nc = clause_child.walk();
                            for spec in clause_child.children(&mut nc) {
                                if spec.kind() == "import_specifier" {
                                    if let Some(nm) = spec.child_by_field_name("name") {
                                        let original = ctx.get_text(nm).to_string();
                                        names.push(original.clone());
                                        if let Some(alias_node) = spec.child_by_field_name("alias") {
                                            let alias = ctx.get_text(alias_node).to_string();
                                            aliases.insert(original, alias);
                                        }
                                    }
                                }
                            }
                        }
                        "namespace_import" => {
                            // `import * as Foo from 'mod'`
                            names.push("*".to_string());
                            // Capture alias for `* as Name`
                            if let Some(alias_node) = clause_child.child_by_field_name("name") {
                                let alias = ctx.get_text(alias_node).to_string();
                                aliases.insert("*".to_string(), alias);
                            }
                        }
                        _ => {}
                    }
                }
            }
            _ => {}
        }
    }

    if !module.is_empty() {
        // Resolve path-alias imports to canonical project-rooted qualnames so
        // they match the module paths produced by `derive_module_path`.
        // e.g. `@app/store` → `frontend.src.app.store`.
        let module = normalize_import(&module, ctx.file_path, &ctx.project_info);
        events.push(Event::import_statement(module, names, aliases, false, node, ctx.file_path));
    }
}

fn emit_identifier_use(ctx: &Ctx, node: Node, events: &mut Vec<Event>) {
    if let Some(parent) = node.parent() {
        match parent.kind() {
            // Skip: declarator name (const FOO = ...)
            "variable_declarator" => {
                if parent.child_by_field_name("name").is_some_and(|n| n.id() == node.id()) {
                    return;
                }
            }
            // Skip: function / generator declaration name
            "function_declaration" | "generator_function_declaration"
            | "function" | "generator_function" => {
                if parent.child_by_field_name("name").is_some_and(|n| n.id() == node.id()) {
                    return;
                }
            }
            // Skip: class declaration name
            "class_declaration" | "class" | "abstract_class_declaration" => {
                if parent.child_by_field_name("name").is_some_and(|n| n.id() == node.id()) {
                    return;
                }
            }
            // Skip: method / property signature name
            "method_definition" | "method_signature" | "property_signature"
            | "public_field_definition" => {
                if parent.child_by_field_name("name").is_some_and(|n| n.id() == node.id()) {
                    return;
                }
            }
            // Skip: all import binding positions
            "import_clause" | "import_specifier" | "namespace_import" => return,
            // Skip: export specifier  (export { X })
            "export_specifier" => return,
            // Skip: labeled statement label
            "labeled_statement" => {
                if parent.child_by_field_name("label").is_some_and(|n| n.id() == node.id()) {
                    return;
                }
            }
            // Skip: member-expression property  (obj.PROP — not LEGB-resolvable)
            // The object part (obj) is NOT skipped and will fire separately.
            "member_expression" => {
                if parent.child_by_field_name("property").is_some_and(|n| n.id() == node.id()) {
                    return;
                }
            }
            // Skip: object literal key  { key: value }
            "pair" => {
                if parent.child_by_field_name("key").is_some_and(|n| n.id() == node.id()) {
                    return;
                }
            }
            // Skip: TypeScript type parameter declaration
            "type_parameter" => return,
            // Skip: TypeScript parameter names — the `name` field is a definition, not a use.
            // The `type` field IS walked (by the required_parameter arm in walk_node).
            "required_parameter" | "optional_parameter" => {
                if parent.child_by_field_name("name").is_some_and(|n| n.id() == node.id()) {
                    return;
                }
            }
            _ => {}
        }
    }
    let name = ctx.get_text(node);
    if name.is_empty()
        || name == "undefined"
        || name == "null"
        || name == "this"
        || name == "super"
    {
        return;
    }
    events.push(Event::use_name(name.to_string(), node, ctx.file_path));
}

fn emit_function(ctx: &mut Ctx, node: Node, events: &mut Vec<Event>) {
    let name = match node.child_by_field_name("name") {
        Some(n) => ctx.get_text(n).to_string(),
        None => return, // anonymous; handled by emit_variable_declarator
    };

    let qualname = ctx.build_qualname(&name);

    let params = node
        .child_by_field_name("parameters")
        .map(|p| collect_params(ctx, p))
        .unwrap_or_default();

    let docstring = extract_jsdoc(node, ctx.source);
    events.push(Event::define_name(
        name.clone(),
        qualname.clone(),
        "function",
        node,
        ctx.file_path,
    ));
    events.push(Event::enter_scope_with_docstring(
        ScopeType::Function,
        name.clone(),
        qualname.clone(),
        params,
        vec![],
        docstring,
        node,
        ctx.file_path,
    ));

    ctx.scope_stack.push((name.clone(), qualname.clone()));

    // Walk TypeScript typed parameter annotations and return type so that type
    // references (e.g. `SomeType` in `fn f(x: SomeType): ReturnType`) emit UseName.
    if let Some(params) = node.child_by_field_name("parameters") {
        let mut cursor = params.walk();
        for child in params.children(&mut cursor) {
            if matches!(child.kind(), "required_parameter" | "optional_parameter") {
                walk_node(ctx, child, events);
            }
        }
    }
    if let Some(rt) = node.child_by_field_name("return_type") {
        walk_node(ctx, rt, events);
    }

    if let Some(body) = node.child_by_field_name("body") {
        let mut cursor = body.walk();
        for child in body.children(&mut cursor) {
            walk_node(ctx, child, events);
        }
    }

    ctx.scope_stack.pop();
    events.push(Event::exit_scope(
        ScopeType::Function,
        name,
        qualname,
        node,
        ctx.file_path,
    ));
}

fn emit_for_loop(ctx: &mut Ctx, node: Node, events: &mut Vec<Event>) {
    // Walk the `right` (iterable) first to emit use/call events for it.
    if let Some(right) = node.child_by_field_name("right") {
        walk_node(ctx, right, events);
    }

    // Bind the loop variable(s) from the `left` field.
    if let Some(left) = node.child_by_field_name("left") {
        let bindings = collect_binding_names(ctx, left);
        for (name, binding_node) in bindings {
            let qualname = ctx.build_qualname(&name);
            events.push(Event::define_name(
                name,
                qualname,
                "variable",
                binding_node,
                ctx.file_path,
            ));
        }
    }

    // Recurse into the loop body.
    if let Some(body) = node.child_by_field_name("body") {
        walk_node(ctx, body, events);
    }
}

fn emit_export(ctx: &mut Ctx, node: Node, events: &mut Vec<Event>) {
    // Check for re-export: `export { X } from 'source'` or `export * from 'source'`
    // These have a `string` child for the source module.
    let mut source_module: Option<String> = None;
    let mut export_names: Vec<String> = Vec::new();
    let mut has_export_clause = false;
    let mut has_namespace_export = false;

    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        match child.kind() {
            "string" => {
                source_module = Some(
                    ctx.get_text(child)
                        .trim_matches(|c| c == '"' || c == '\'' || c == '`')
                        .to_string(),
                );
            }
            "export_clause" => {
                has_export_clause = true;
                let mut ec = child.walk();
                for spec in child.children(&mut ec) {
                    if spec.kind() == "export_specifier" {
                        if let Some(nm) = spec.child_by_field_name("name") {
                            export_names.push(ctx.get_text(nm).to_string());
                        }
                    }
                }
            }
            "namespace_export" => {
                has_namespace_export = true;
                export_names.push("*".to_string());
            }
            _ => {}
        }
    }

    if let Some(src) = source_module {
        // This is a re-export statement — emit an import event for the dependency.
        if has_export_clause || has_namespace_export {
            let resolved = normalize_import(&src, ctx.file_path, &ctx.project_info);
            events.push(Event::import_statement(resolved, export_names, std::collections::HashMap::new(), false, node, ctx.file_path));
            return;
        }
    }

    // Not a re-export — walk child declarations normally.
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        match child.kind() {
            "function_declaration" | "generator_function_declaration" => {
                emit_function(ctx, child, events);
            }
            "class_declaration" | "abstract_class_declaration" => {
                emit_class(ctx, child, events);
            }
            "lexical_declaration" | "variable_declaration" => {
                emit_variable_declaration(ctx, child, events);
            }
            "interface_declaration" => {
                emit_interface(ctx, child, events);
            }
            "type_alias_declaration" => {
                emit_type_alias(ctx, child, events);
            }
            "enum_declaration" => {
                emit_enum(ctx, child, events);
            }
            _ => {}
        }
    }
}

fn emit_enum(ctx: &mut Ctx, node: Node, events: &mut Vec<Event>) {
    let name = match node.child_by_field_name("name") {
        Some(n) => ctx.get_text(n).to_string(),
        None => return,
    };

    let qualname = ctx.build_qualname(&name);

    // Enums are class-like in the graph
    let docstring = extract_jsdoc(node, ctx.source);
    events.push(Event::define_name(
        name.clone(),
        qualname.clone(),
        "class",
        node,
        ctx.file_path,
    ));
    events.push(Event::enter_scope_with_docstring(
        ScopeType::Class,
        name.clone(),
        qualname.clone(),
        vec![],
        vec![],
        docstring,
        node,
        ctx.file_path,
    ));

    ctx.scope_stack.push((name.clone(), qualname.clone()));

    if let Some(body) = node.child_by_field_name("body") {
        let mut cursor = body.walk();
        for child in body.children(&mut cursor) {
            if child.kind() == "enum_member" {
                // First child of enum_member is the property_identifier
                let mut mc = child.walk();
                for member_child in child.children(&mut mc) {
                    if matches!(member_child.kind(), "property_identifier" | "string") {
                        let member_name = ctx
                            .get_text(member_child)
                            .trim_matches(|c| c == '"' || c == '\'')
                            .to_string();
                        if !member_name.is_empty() {
                            let member_qualname = ctx.build_qualname(&member_name);
                            events.push(Event::define_name(
                                member_name,
                                member_qualname,
                                "variable",
                                member_child,
                                ctx.file_path,
                            ));
                        }
                        break;
                    }
                }
            }
        }
    }

    ctx.scope_stack.pop();
    events.push(Event::exit_scope(
        ScopeType::Class,
        name,
        qualname,
        node,
        ctx.file_path,
    ));
}

fn emit_decorator(ctx: &mut Ctx, node: Node, events: &mut Vec<Event>) {
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        match child.kind() {
            "identifier" => {
                let name = ctx.get_text(child).to_string();
                events.push(Event::decorator(name, false, vec![], node, ctx.file_path));
            }
            "member_expression" => {
                let name = ctx.get_text(child).to_string();
                events.push(Event::decorator(name, false, vec![], node, ctx.file_path));
            }
            "call_expression" => {
                let callee = child
                    .child_by_field_name("function")
                    .map(|n| ctx.get_text(n).to_string())
                    .unwrap_or_default();
                let mut args = Vec::new();
                if let Some(args_node) = child.child_by_field_name("arguments") {
                    let mut c = args_node.walk();
                    for arg in args_node.children(&mut c) {
                        match arg.kind() {
                            "(" | ")" | "," => {}
                            _ if arg.is_named() => {
                                let text = ctx.get_text(arg).to_string();
                                if !text.is_empty() {
                                    args.push(text);
                                }
                            }
                            _ => {}
                        }
                    }
                }
                events.push(Event::decorator(callee, true, args, node, ctx.file_path));
            }
            _ => {}
        }
    }
}

fn emit_class_field(ctx: &mut Ctx, node: Node, events: &mut Vec<Event>) {
    if let Some(name_node) = node.child_by_field_name("name") {
        let name = ctx.get_text(name_node).to_string();
        let qualname = ctx.build_qualname(&name);
        events.push(Event::define_name(name, qualname, "variable", node, ctx.file_path));
    }
}

fn emit_class(ctx: &mut Ctx, node: Node, events: &mut Vec<Event>) {
    let name = match node.child_by_field_name("name") {
        Some(n) => ctx.get_text(n).to_string(),
        None => return,
    };

    let qualname = ctx.build_qualname(&name);

    let bases = node
        .child_by_field_name("superclass")
        .map(|n| vec![ctx.get_text(n).to_string()])
        .unwrap_or_default();

    let docstring = extract_jsdoc(node, ctx.source);
    events.push(Event::define_name(
        name.clone(),
        qualname.clone(),
        "class",
        node,
        ctx.file_path,
    ));
    events.push(Event::enter_scope_with_docstring(
        ScopeType::Class,
        name.clone(),
        qualname.clone(),
        vec![],
        bases,
        docstring,
        node,
        ctx.file_path,
    ));

    ctx.scope_stack.push((name.clone(), qualname.clone()));

    if let Some(body) = node.child_by_field_name("body") {
        let mut cursor = body.walk();
        for child in body.children(&mut cursor) {
            match child.kind() {
                "method_definition" => emit_method(ctx, child, events),
                "public_field_definition" | "field_definition" => {
                    emit_class_field(ctx, child, events);
                }
                _ => {}
            }
        }
    }

    ctx.scope_stack.pop();
    events.push(Event::exit_scope(
        ScopeType::Class,
        name,
        qualname,
        node,
        ctx.file_path,
    ));
}

fn emit_catch_clause(ctx: &mut Ctx, node: Node, events: &mut Vec<Event>) {
    if let Some(param) = node.child_by_field_name("parameter") {
        let bindings = collect_binding_names(ctx, param);
        for (name, binding_node) in bindings {
            let qualname = ctx.build_qualname(&name);
            events.push(Event::define_name(
                name,
                qualname,
                "variable",
                binding_node,
                ctx.file_path,
            ));
        }
    }

    // Recurse into body.
    if let Some(body) = node.child_by_field_name("body") {
        let mut cursor = body.walk();
        for child in body.children(&mut cursor) {
            walk_node(ctx, child, events);
        }
    }
}

fn emit_call(ctx: &mut Ctx, node: Node, events: &mut Vec<Event>) {
    // call_expression: function field; new_expression: constructor field
    let callee_node = node
        .child_by_field_name("function")
        .or_else(|| node.child_by_field_name("constructor"));

    if let Some(func_node) = callee_node {
        let callee = ctx.get_text(func_node).to_string();

        let mut arguments = Vec::new();
        if let Some(args_node) = node.child_by_field_name("arguments") {
            let mut cursor = args_node.walk();
            for child in args_node.children(&mut cursor) {
                match child.kind() {
                    "(" | ")" | "," => {}
                    _ => {
                        let text = ctx.get_text(child).to_string();
                        if !text.is_empty() {
                            arguments.push(text);
                        }
                    }
                }
            }
        }

        events.push(Event::call_expression(callee, arguments, node, ctx.file_path));
    }
}

pub fn derive_module_path(file_path: &str) -> Vec<String> {
    use std::path::{Component, Path};

    let path = Path::new(file_path);
    let stem = path
        .file_stem()
        .and_then(|s| s.to_str())
        .unwrap_or("index");

    // Use the project root as anchor when available.
    if let Some(info) = find_project_info(file_path) {
        let prefix = format!("{}/", info.root_path);
        if file_path.starts_with(&prefix) {
            let rest = &file_path[prefix.len()..]; // e.g. "src/app/App.tsx"
            if !rest.starts_with("node_modules") {
                let rest_path = Path::new(rest);
                let rest_stem = rest_path
                    .file_stem()
                    .and_then(|s| s.to_str())
                    .unwrap_or(stem);
                let rest_dir = rest_path
                    .parent()
                    .and_then(|p| p.to_str())
                    .unwrap_or("");

                let mut parts = vec![info.root_name];
                if !rest_dir.is_empty() && rest_dir != "." {
                    for seg in rest_dir.split('/') {
                        if !seg.is_empty() {
                            parts.push(seg.to_string());
                        }
                    }
                }
                if rest_stem != "index" {
                    parts.push(rest_stem.to_string());
                }
                return parts;
            }
        }
    }

    // Fallback: collect normal directory components, strip src root.
    let dir_parts: Vec<String> = path
        .parent()
        .map(|p| {
            p.components()
                .filter_map(|c| match c {
                    Component::Normal(n) => n.to_str().map(String::from),
                    _ => None,
                })
                .collect()
        })
        .unwrap_or_default();

    let stops = ["node_modules", ".git", ".venv"];
    let trim_at = dir_parts
        .iter()
        .position(|p| stops.contains(&p.as_str()))
        .unwrap_or(dir_parts.len());
    let dir_parts = &dir_parts[..trim_at];

    // "app" excluded — it is a valid subdirectory name, not a source root.
    let src_roots = ["src", "lib", "packages", "source"];
    let start = dir_parts
        .iter()
        .rposition(|p| src_roots.contains(&p.as_str()))
        .map(|i| i + 1)
        .unwrap_or_else(|| {
            if dir_parts.is_empty() { 0 } else { dir_parts.len() - 1 }
        });

    let mut parts: Vec<String> = dir_parts[start..].to_vec();
    if stem != "index" {
        parts.push(stem.to_string());
    }
    if parts.is_empty() {
        parts.push(stem.to_string());
    }
    parts
}

