    root_name: String,
    /// Absolute path string of that directory (e.g. `"/path/to/frontend"`).
    root_path: String,
    /// Tsconfig path alias mappings: `(alias_prefix, target_dir)`.
    /// e.g. `("@app", "src/app")`.
    aliases: Vec<(String, String)>,
}

pub enum JsLang {
